const REMOVED_BACKEND_SETTING_KEYS = new Set();

function backendOwnedSettingsPayload(settings) {
  const normalized = normalizeAgentSettings(settings);
  const payload = {};
  for (const [key, value] of Object.entries(normalized)) {
    if (!REMOVED_BACKEND_SETTING_KEYS.has(key)) {
      payload[key] = value;
    }
  }
  return payload;
}

function storedJson(key, fallback) {
  if (!key) return { ...fallback };
  try {
    const raw = readStoredPreference(key);
    if (!raw) {
      return { ...fallback };
    }
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? { ...fallback, ...parsed } : { ...fallback };
  } catch {
    return { ...fallback };
  }
}

function storedStringArray(key, fallback = []) {
  try {
    const raw = readStoredPreference(key);
    if (!raw) {
      return [...fallback];
    }
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map((item) => String(item || "")).filter(Boolean) : [...fallback];
  } catch {
    return [...fallback];
  }
}

function persistStringArray(key, values) {
  writeStoredPreference(
    key,
    JSON.stringify(Array.isArray(values) ? values.map((item) => String(item || "")).filter(Boolean) : []),
  );
}

function persistJson(key, value) {
  if (!key) return;
  writeStoredPreference(key, JSON.stringify(value || {}));
}

function hasStoredPreference(key) {
  if (!key) return false;
  if (volatileUiStorage.has(key)) {
    return true;
  }
  try {
    return durableUiStorage()?.getItem(key) !== null;
  } catch {
    return false;
  }
}

function migrateAudioSilenceTimeoutSetting(settings) {
  return { ...(settings || {}) };
}

function withLegacyRequestPreferences(settings) {
  return { ...(settings || {}) };
}

function isLikelyMobileBrowser() {
  if (typeof window === "undefined" || typeof navigator === "undefined") {
    return false;
  }
  const coarsePointer = window.matchMedia?.("(pointer: coarse)");
  if (coarsePointer?.matches) {
    return true;
  }
  return /android|iphone|ipad|ipod|mobile|silk|kindle|blackberry/i.test(
    navigator.userAgent || "",
  );
}

function resolveInitialImmersiveMode() {
  const hasStored = hasStoredPreference(uiPreferences.immersiveMode);
  if (hasStored) {
    return storedBoolean(uiPreferences.immersiveMode, false);
  }
  return isLikelyMobileBrowser();
}

function installMobileZoomGuards() {
  if (!isLikelyMobileBrowser()) {
    return;
  }
  const preventPinchZoom = (event) => {
    if (event.touches && event.touches.length > 1) {
      event.preventDefault();
    }
  };
  const preventGestureZoom = (event) => {
    event.preventDefault();
  };
  document.addEventListener("touchstart", preventPinchZoom, { passive: false });
  document.addEventListener("touchmove", preventPinchZoom, { passive: false });
  document.addEventListener("gesturestart", preventGestureZoom, { passive: false });
  document.addEventListener("gesturechange", preventGestureZoom, { passive: false });
}

function installMobileKeyboardGuards() {
  if (!isLikelyMobileBrowser() || !promptInput) {
    return;
  }
  const normalizeForKeyboard = () => {
    setAppViewportHeight();
    window.scrollTo(0, 0);
  };
  const scheduleKeyboardGuardRefresh = () => {
    window.setTimeout(normalizeForKeyboard, 0);
  };
  promptInput.addEventListener("focusin", () => {
    scheduleKeyboardGuardRefresh();
  });
  promptInput.addEventListener("focusout", () => {
    scheduleKeyboardGuardRefresh();
  });
  window.visualViewport?.addEventListener("resize", () => {
    if (document.activeElement === promptInput) {
      scheduleKeyboardGuardRefresh();
    }
  }, { passive: true });
}

function shouldCollapsePanelsByDefault() {
  return TRACE_VISUAL_PREFERENCE_KEYS.every((key) => !hasStoredPreference(key));
}

