function chatScrollDistanceFromBottom() {
  if (!chatLog) {
    return 0;
  }
  return chatLog.scrollHeight - chatLog.clientHeight - chatLog.scrollTop;
}

function chatIsScrolledToBottom() {
  return chatScrollDistanceFromBottom() <= CHAT_AUTO_SCROLL_BOTTOM_THRESHOLD_PX;
}

function updateChatAutoScrollPinned() {
  chatAutoScrollPinned = chatIsScrolledToBottom();
}

function scrollChatToBottom(options = {}) {
  if (!chatLog) {
    return false;
  }
  const force = options?.force === true;
  if (!force && !chatAutoScrollPinned) {
    return false;
  }
  chatAutoScrollPinned = true;
  const behavior = String(options?.behavior || "").trim();
  if (typeof chatLog.scrollTo === "function") {
    const scrollOptions = { top: chatLog.scrollHeight };
    if (behavior) {
      scrollOptions.behavior = behavior;
    }
    chatLog.scrollTo(scrollOptions);
    return true;
  }
  chatLog.scrollTop = chatLog.scrollHeight;
  return true;
}

function scheduleChatAutoScroll(options = {}) {
  if (!chatLog || chatAutoScrollFrame || (options?.force !== true && !chatAutoScrollPinned)) {
    return;
  }
  const run = () => {
    chatAutoScrollFrame = 0;
    scrollChatToBottom(options);
  };
  if (typeof window !== "undefined" && typeof window.requestAnimationFrame === "function") {
    chatAutoScrollFrame = window.requestAnimationFrame(run);
    return;
  }
  chatAutoScrollFrame = window.setTimeout(run, 0);
}

function installChatAutoScrollLock() {
  if (!chatLog || chatAutoScrollLockInstalled) {
    return;
  }
  chatAutoScrollLockInstalled = true;
  updateChatAutoScrollPinned();
  chatLog.addEventListener("scroll", updateChatAutoScrollPinned, { passive: true });
}

function installChatAutoScrollObserver() {
  if (!chatLog || chatAutoScrollObserver || typeof MutationObserver === "undefined") {
    return;
  }
  chatAutoScrollObserver = new MutationObserver(() => scheduleChatAutoScroll());
  chatAutoScrollObserver.observe(chatLog, {
    characterData: true,
    childList: true,
    subtree: true,
  });
}

installChatAutoScrollLock();
installChatAutoScrollObserver();
