function formatWallClockTime(now) {
  if (typeof wallClockFormatter.formatToParts !== "function") {
    return wallClockFormatter
      .format(now)
      .replace(/(\d)([AP]M)$/i, `$1${wallClockMeridiemSpacer}$2`);
  }
  const parts = wallClockFormatter.formatToParts(now);
  if (!parts.some((part) => part.type === "dayPeriod")) {
    return wallClockFormatter.format(now);
  }
  let text = "";
  parts.forEach((part, index) => {
    const next = parts[index + 1];
    if (
      part.type === "literal"
      && next?.type === "dayPeriod"
      && !part.value.trim()
    ) {
      return;
    }
    if (part.type === "dayPeriod") {
      text = text.replace(/\s+$/u, "");
      if (text) {
        text += wallClockMeridiemSpacer;
      }
    }
    text += part.value;
  });
  return text;
}

function renderWallClock() {
  const now = new Date();
  const text = formatWallClockTime(now);
  const title = wallClockTitleFormatter.format(now);
  [wallClock, immersiveWallClock].forEach((clock) => {
    if (!clock) {
      return;
    }
    updateAnimatedNumber(clock, text);
    clock.dateTime = now.toISOString();
    clock.title = title;
  });
}

function startWallClock() {
  renderWallClock();
  window.setInterval(renderWallClock, 1000);
}

function setTopbarMenuOpen(open) {
  const next = Boolean(open);
  topbarActions?.classList.toggle("topbar-actions-open", next);
  if (!topbarActions) {
    return;
  }
  if (topbarMenuButton) {
    topbarMenuButton.setAttribute("aria-expanded", String(next));
    topbarMenuButton.setAttribute("aria-label", next ? "Close header menu" : "Open header menu");
    topbarMenuButton.title = next ? "Close menu" : "Open menu";
  }
}

function syncTopbarCompactMode() {
  if (!userTopbar) {
    return;
  }
  const width = userTopbar.getBoundingClientRect().width;
  const compact = Number.isFinite(width) && width > 0 && width <= TOPBAR_COMPACT_WIDTH_PX;
  userTopbar.classList.toggle("topbar-compact", compact);
  if (topbarMenuButton) {
    topbarMenuButton.setAttribute(
      "aria-expanded",
      String(topbarActions?.classList.contains("topbar-actions-open")),
    );
  }
  if (topbarActions?.classList.contains("topbar-actions-open")) {
    void setTopbarMenuOpen(true);
  }
}

function installTopbarCompactObserver() {
  syncTopbarCompactMode();
  if (typeof ResizeObserver === "function" && userTopbar) {
    const observer = new ResizeObserver(syncTopbarCompactMode);
    observer.observe(userTopbar);
  }
  window.addEventListener("resize", syncTopbarCompactMode);
}

function setQuickControlsOpen(open) {
  const next = state.agentUiClientMode ? false : Boolean(open);
  state.quickControlsOpen = next;
  quickControlsPanel?.classList.toggle("open", next);
  quickControlsPanel?.setAttribute("aria-hidden", String(!next));
  if (quickControlsPanel) {
    quickControlsPanel.inert = !next;
    quickControlsPanel.toggleAttribute("inert", !next);
  }
  if (quickControlsToggle) {
    quickControlsToggle.setAttribute("aria-expanded", String(next));
    quickControlsToggle.title = next ? "Close quick controls" : "Quick controls";
  }
}

