function saveAgentSettings(settings, options = {}) {
  const { persistLocal = true, persistBackend = true } = options || {};
  state.agentSettings = normalizeAgentSettings(settings);
  const nextCommandOutputExpandedDefault =
    state.agentSettings.ui_command_output_expanded_by_default === true;
  state.reasoningProfile = state.agentSettings.reasoning_profile;
  state.workflowExecutionMode = state.agentSettings.workflow_execution_mode;
  state.agentEventsEnabled = state.agentSettings.agent_events_enabled !== false;
  state.autoApproveCommands = state.agentSettings.auto_approve_commands === true;
  state.audioVoiceInputEnabled = state.agentSettings.audio_voice_input_enabled !== false;
  state.outputCompositionMode = normalizeFinalResponseMode(
    state.agentSettings.llm_operator_final_response_mode,
  );
  state.verificationEnforced = state.agentSettings.llm_operator_verification_enforced !== false;
  if (autoApproveToggle) {
    autoApproveToggle.checked = state.autoApproveCommands;
  }
  void persistLocal;
  if (persistBackend) {
    queuePersistAgentSettingsToBackend(state.agentSettings);
  }
  document.documentElement.dataset.numberAnimation = state.agentSettings.ui_number_animation;
  document.documentElement.dataset.thinkingTextAnimation =
    state.agentSettings.ui_thinking_text_animation;
  applyTheme(state.agentSettings.ui_theme, false);
  if (normalizeAgentMode(state.agentSettings.ui_agent_mode) !== currentAgentMode()) {
    setAgentMode(state.agentSettings.ui_agent_mode, { persist: false });
  }
  applyUiLayoutSettings(state.agentSettings);
  renderWallClock();
  applySettingsToControls(state.agentSettings);
  updateAgentNameDisplay();
  updateWorkflowExecutionModeBadge();
  updateLlmStreamPaneVisibility();
  updateEventCountLabel();
  updateLlmStreamTokenRate();
  updateAudioVoiceControls();
  renderAllPipelineItemStates();
  updateAgentOptimizationControls();
  setCommandOutputCollapsed(!nextCommandOutputExpandedDefault);
  syncResponsiveImmersiveMode();
}

function normalizedOptimizationProfile(profile) {
  return normalizeAgentSettings({
    ...state.agentSettingsDefaults,
    ...(profile || {}),
  });
}

function optimizationControlledValue(settings, key) {
  const safe = normalizeAgentSettings(settings);
  return safe[key];
}

function optimizationValuesEqual(left, right) {
  return JSON.stringify(left) === JSON.stringify(right);
}

function agentOptimizationProfileFor(settings = state.agentSettings) {
  const safe = normalizeAgentSettings(settings);
  for (const [profileId, profileValues] of Object.entries(agentOptimizationProfiles)) {
    const profile = normalizedOptimizationProfile(profileValues);
    const exact = AGENT_OPTIMIZATION_CONTROLLED_KEYS.every((key) =>
      optimizationValuesEqual(optimizationControlledValue(safe, key), profile[key]),
    );
    if (exact) {
      return profileId;
    }
  }
  return "custom";
}

function agentOptimizationScore(settings = state.agentSettings) {
  const profile = agentOptimizationProfileFor(settings);
  if (profile === "accuracy") return 0;
  if (profile === "speed") return 100;
  const safe = normalizeAgentSettings(settings);
  const accuracy = normalizedOptimizationProfile(agentOptimizationProfiles.accuracy);
  const speed = normalizedOptimizationProfile(agentOptimizationProfiles.speed);
  let speedWeight = 0;
  let totalWeight = 0;
  for (const key of AGENT_OPTIMIZATION_CONTROLLED_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(accuracy, key) || !Object.prototype.hasOwnProperty.call(speed, key)) {
      continue;
    }
    totalWeight += 1;
    const value = safe[key];
    const matchesAccuracy = optimizationValuesEqual(value, accuracy[key]);
    const matchesSpeed = optimizationValuesEqual(value, speed[key]);
    if (matchesSpeed && !matchesAccuracy) {
      speedWeight += 1;
    } else if (!matchesSpeed && !matchesAccuracy) {
      speedWeight += 0.5;
    }
  }
  return totalWeight > 0 ? Math.round((speedWeight / totalWeight) * 100) : 50;
}

function updateAgentOptimizationControls(settings = state.agentSettings) {
  const profile = agentOptimizationProfileFor(settings);
  const score = agentOptimizationScore(settings);
  const hue = Math.round(190 - score * 1.6);
  const fillColor = `hsl(${hue} 72% 46%)`;
  for (const control of agentOptimizationControls) {
    control.dataset.profile = profile;
    control.title = profile === "custom"
      ? "Custom reflects your current settings."
      : `Optimize agent for ${profile === "speed" ? "Speed" : "Accuracy"}`;
    for (const button of control.querySelectorAll("button[data-profile]")) {
      const buttonProfile = String(button.dataset.profile || "");
      const selected = buttonProfile === profile;
      button.setAttribute("aria-pressed", selected ? "true" : "false");
      if (buttonProfile === "custom") {
        button.title = "Custom reflects your current settings.";
      }
    }
  }
  for (const heat of agentOptimizationHeatBars) {
    heat.dataset.profile = profile;
    heat.dataset.score = String(score);
    heat.style.setProperty("--agent-optimization-score", String(score));
    heat.style.setProperty("--agent-optimization-color", fillColor);
    const meter = heat.querySelector("[data-agent-optimization-meter]");
    if (meter) {
      meter.style.width = `${score}%`;
    }
    const value = heat.querySelector("[data-agent-optimization-value]");
    if (value) {
      value.textContent = `${score}% Speed`;
    }
  }
}

function applyAgentOptimizationProfile(profileId) {
  const profile = String(profileId || "").trim();
  if (profile === "custom") {
    updateAgentOptimizationControls();
    return;
  }
  const values = agentOptimizationProfiles[profile];
  if (!values) {
    return;
  }
  const preserved = normalizeAgentSettings(state.agentSettings);
  const nextSettings = normalizeAgentSettings({
    ...preserved,
    ...values,
    auto_approve_commands: preserved.auto_approve_commands,
  });
  saveAgentSettings(nextSettings);
  void saveRuntimeControls();
}

function setOutputCompositionMode(mode, { persist = true } = {}) {
  state.outputCompositionMode = normalizeFinalResponseMode(mode);
  if (outputCompositionToggle) {
    outputCompositionToggle.checked = state.outputCompositionMode === "simple";
  }
  if (persist) {
    saveAgentSettings({
      ...state.agentSettings,
      llm_operator_final_response_mode: state.outputCompositionMode,
    });
  }
}

function setVerificationEnforced(enabled, { persist = true } = {}) {
  state.verificationEnforced = enabled !== false;
  if (verificationEnforcedToggle) {
    verificationEnforcedToggle.checked = state.verificationEnforced;
  }
  if (persist) {
    saveAgentSettings({
      ...state.agentSettings,
      llm_operator_verification_enforced: state.verificationEnforced,
    });
  }
}

function sanitizeAgentDisplayName(value) {
  const cleaned = String(value || "")
    .replace(/[\r\n\t]+/g, " ")
    .replace(/[<>]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 40);
  return cleaned || "Agent";
}

function currentAgentName() {
  return sanitizeAgentDisplayName(state.agentSettings?.agent_display_name);
}

function agentNameKey(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
}

function recentAgentNamesForSuggestion() {
  const seen = new Set();
  const names = [];
  for (const item of [currentAgentName(), ...(state.agentNameRecent || [])]) {
    const name = sanitizeAgentDisplayName(item);
    const key = agentNameKey(name);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    names.push(name);
    if (names.length >= 10) break;
  }
  return names;
}

function rememberAgentNameSuggestion(name) {
  const safe = sanitizeAgentDisplayName(name);
  const key = agentNameKey(safe);
  if (!key || key === "agent") return;
  const next = [safe];
  const seen = new Set([key]);
  for (const item of state.agentNameRecent || []) {
    const existing = sanitizeAgentDisplayName(item);
    const existingKey = agentNameKey(existing);
    if (!existingKey || seen.has(existingKey)) continue;
    seen.add(existingKey);
    next.push(existing);
    if (next.length >= 10) break;
  }
  state.agentNameRecent = next;
  persistStringArray(uiPreferences.agentNameRecent, next);
}

function updateAgentNameDisplay() {
  const name = currentAgentName();
  if (brandAgentName) {
    brandAgentName.textContent = name;
  }
  if (immersiveBrandAgentName) {
    immersiveBrandAgentName.textContent = name;
  }
  if (promptInput) {
    promptInput.placeholder = `Ask ${name}...`;
  }
  document.title = `OpenFabric ${name}`;
}

async function generateRandomAgentName() {
  if (!agentNameRandomButton) {
    return;
  }
  const previous = agentNameRandomButton.textContent;
  agentNameRandomButton.disabled = true;
  agentNameRandomButton.textContent = "Naming...";
  try {
    const response = await fetchWithLlmActivity("/api/agent/name/suggest", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        current_name: currentAgentName(),
        model_name: String(state.activeModelName || state.configuredModel || "auto"),
        recent_names: recentAgentNamesForSuggestion(),
      }),
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    const name = sanitizeAgentDisplayName(payload?.name);
    if (settingAgentName) {
      settingAgentName.value = name;
    }
    rememberAgentNameSuggestion(name);
    saveAgentSettings({ ...state.agentSettings, agent_display_name: name });
  } catch (error) {
    addMessage("assistant", "Name generation failed", String(error?.message || error || "Unable to generate a name."));
  } finally {
    agentNameRandomButton.disabled = false;
    agentNameRandomButton.textContent = previous || "Random";
  }
}

function renderOperatorCacheStats(payload) {
  if (!operatorCacheStats) return;
  const stats = payload?.stats || payload || {};
  const count = Number.parseInt(stats.total_entries, 10) || 0;
  const uses = Number.parseInt(stats.total_uses, 10) || 0;
  const success = Number.parseInt(stats.success_entries, 10) || 0;
  const failure = Number.parseInt(stats.failure_entries, 10) || 0;
  const computationStats = payload?.computation_stats || {};
  const computationCount = Number.parseInt(computationStats.total_entries, 10) || 0;
  const computationUses = Number.parseInt(computationStats.total_uses, 10) || 0;
  const cleared = String(stats.last_cleared_at || "").trim();
  operatorCacheStats.classList.remove("operator-cache-error");
  operatorCacheStats.innerHTML = [
    {
      label: "Plans",
      value: `${count}`,
      detail: `${success} success · ${failure} failure`,
    },
    {
      label: "Computations",
      value: `${computationCount}`,
      detail: `${computationUses} use${computationUses === 1 ? "" : "s"}`,
    },
    {
      label: "Accepted uses",
      value: `${uses}`,
      detail: "plan cache",
    },
    {
      label: "Last cleared",
      value: cleared ? "Saved" : "Never",
      detail: cleared || "not cleared yet",
    },
  ].map((card) => `
    <div class="operator-cache-card">
      <span>${escapeHtml(card.label)}</span>
      <strong>${escapeHtml(card.value)}</strong>
      <small>${escapeHtml(card.detail)}</small>
    </div>
  `).join("");
}

async function refreshOperatorCacheStats() {
  if (!operatorCacheStats) return;
  try {
    const response = await fetch("/api/agent/cache/stats", { cache: "no-store" });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    renderOperatorCacheStats(await response.json());
  } catch (error) {
    operatorCacheStats.classList.add("operator-cache-error");
    operatorCacheStats.textContent = `Cache stats unavailable: ${String(error?.message || error)}`;
  }
}

