function renderAudioTranscriberConfig(config = {}) {
  state.audioTranscriberConfig = config && typeof config === "object" ? config : null;
  const model = state.audioTranscriberConfig?.model || {};
  const binary = state.audioTranscriberConfig?.binary || {};
  if (settingAudioServiceEnabled) {
    settingAudioServiceEnabled.checked = state.audioTranscriberConfig?.enabled === true;
  }
  if (settingAudioEngine) settingAudioEngine.value = String(state.audioTranscriberConfig?.engine || "whisper_cpp");
  if (settingAudioModelPath) settingAudioModelPath.value = String(model.path || "");
  if (settingAudioModelStatus) settingAudioModelStatus.value = String(model.status || "unknown");
  if (settingAudioBinaryPath) settingAudioBinaryPath.value = String(binary.path || "");
  if (settingAudioBinaryStatus) settingAudioBinaryStatus.value = String(binary.status || "unknown");
  if (settingAudioLanguage) settingAudioLanguage.value = String(state.audioTranscriberConfig?.language || "auto");
  if (settingAudioMaxSeconds) {
    settingAudioMaxSeconds.value = String(state.audioTranscriberConfig?.max_duration_seconds || "");
  }
  if (settingAudioMaxUploadMb) {
    settingAudioMaxUploadMb.value = String(state.audioTranscriberConfig?.max_upload_mb || "");
  }
  if (settingAudioServiceUrl) {
    settingAudioServiceUrl.value = String(
      state.audioTranscriberConfig?.service?.url ||
      state.agentSettings?.audio_transcriber_service_url ||
      audioServiceUrlFromSettings(),
    );
  }
  const available = state.audioTranscriberConfig?.available === true;
  const enabled = state.audioTranscriberConfig?.enabled !== false;
  const reason = audioUnavailableReason();
  if (audioTranscriberStatus) {
    audioTranscriberStatus.innerHTML = `
      <div class="operator-cache-card">
        <span>Service</span>
        <strong>${escapeHtml(available ? "Ready" : enabled ? "Unavailable" : "Disabled")}</strong>
        <small>${escapeHtml(available ? `Connected to ${state.audioTranscriberConfig?.service?.url || audioServiceUrlFromSettings()}.` : reason)}</small>
      </div>
      <div class="operator-cache-card">
        <span>Model</span>
        <strong>${escapeHtml(String(model.status || "unknown"))}</strong>
        <small>${escapeHtml(String(model.path || "No model path configured."))}</small>
      </div>
      <div class="operator-cache-card">
        <span>Binary</span>
        <strong>${escapeHtml(String(binary.status || "unknown"))}</strong>
        <small>${escapeHtml(String(binary.resolved_path || binary.path || "No whisper-cli configured."))}</small>
      </div>
    `;
    audioTranscriberStatus.classList.remove("operator-cache-error");
  }
  updateAudioVoiceControls();
}

function audioUnavailableReason() {
  const config = state.audioTranscriberConfig || {};
  if (config.enabled === false) return "The backend audio transcriber is disabled.";
  if (config.service?.status === "unreachable") {
    return config.service?.error || "The audio runtime microservice is unreachable.";
  }
  if (!("MediaRecorder" in window) || !navigator.mediaDevices?.getUserMedia) {
    return "This browser does not support local audio recording.";
  }
  for (const [key, label] of [
    ["binary", "whisper-cli is missing"],
    ["ffmpeg", "ffmpeg is missing"],
    ["ffprobe", "ffprobe is missing"],
    ["model", "Whisper model is missing"],
  ]) {
    const value = config[key];
    if (value && value.available === false) return `${label}.`;
  }
  if (config.available === false) return "Audio transcription is not ready.";
  return "Voice input is turned off.";
}

async function refreshAudioPermissionState() {
  if (!navigator.permissions?.query) {
    state.audioPermissionState = "unknown";
    state.audioPermissionWarningNotified = false;
    updateAudioVoiceControls();
    return state.audioPermissionState;
  }
  try {
    const status = await navigator.permissions.query({ name: "microphone" });
    state.audioPermissionState = status?.state || "unknown";
    state.audioPermissionWarningNotified = state.audioPermissionState === "denied"
      ? state.audioPermissionWarningNotified
      : false;
    status.onchange = () => {
      state.audioPermissionState = status.state || "unknown";
      state.audioPermissionWarningNotified = state.audioPermissionState === "denied"
        ? state.audioPermissionWarningNotified
        : false;
      updateAudioVoiceControls();
    };
  } catch (_error) {
    state.audioPermissionState = "unknown";
    state.audioPermissionWarningNotified = false;
  }
  updateAudioVoiceControls();
  return state.audioPermissionState;
}

function microphonePermissionMessage() {
  if (state.audioPermissionState === "denied") {
    return "Microphone permission is blocked. Open the browser site settings for this page and allow microphone access, then try again.";
  }
  if (state.audioPermissionState === "prompt") {
    return "Click the mic and allow microphone access when the browser asks.";
  }
  return "Allow microphone access to dictate locally.";
}

function notifyMicrophonePermissionBlocked() {
  if (!state.audioPermissionWarningNotified) {
    addMessage("assistant", "Voice input", microphonePermissionMessage());
    state.audioPermissionWarningNotified = true;
  }
}

function syncVoiceInputButtonMountPoint() {
  if (!voiceInputButton) return;
  if (promptVoiceInputAnchor && voiceInputButton.parentElement !== promptVoiceInputAnchor) {
    promptVoiceInputAnchor.appendChild(voiceInputButton);
  }
}

async function refreshAudioTranscriberConfig({ announce = false } = {}) {
  try {
    const response = await fetch("/api/audio-transcriber/config", { cache: "no-store" });
    if (!response.ok) {
      throw new Error(await responseErrorMessage(response, "Audio transcriber unavailable."));
    }
    const payload = await response.json();
    renderAudioTranscriberConfig(payload);
    if (announce && audioTranscriberStatus) {
      const ready = payload?.available === true;
      audioTranscriberStatus.classList.toggle("operator-cache-error", !ready);
    }
    return payload;
  } catch (error) {
    state.audioTranscriberConfig = null;
    if (audioTranscriberStatus) {
      audioTranscriberStatus.classList.add("operator-cache-error");
      audioTranscriberStatus.textContent = `Audio service unavailable: ${shortStatusError(error)}`;
    }
    updateAudioVoiceControls();
    return null;
  }
}

function updateAudioVoiceControls() {
  const enabled = state.agentSettings?.audio_voice_input_enabled !== false;
  state.audioVoiceInputEnabled = enabled;
  if (settingAudioVoiceInputEnabled) {
    settingAudioVoiceInputEnabled.checked = enabled;
  }
  if (quickAudioToggle) {
    quickAudioToggle.checked = enabled;
  }
  const recording = state.audioRecordingState === "recording";
  const transcribing = state.audioRecordingState === "transcribing";
  const silenceWarning = recording && state.audioSilenceWarningActive === true;
  const busy = ["stopping", "transcribing"].includes(state.audioRecordingState);
  const available = state.audioTranscriberConfig?.available === true;
  const permissionState = state.audioPermissionState || "unknown";
  const permissionDenied = permissionState === "denied";
  const permissionPrompt = permissionState === "prompt" || permissionState === "unknown";
  const canRecord =
    enabled
    && available
    && "MediaRecorder" in window
    && Boolean(navigator.mediaDevices?.getUserMedia);
  const controlButtons = [];
  if (voiceInputButton) {
    controlButtons.push(voiceInputButton);
  }
  if (state.audioVoiceTargetButton && state.audioVoiceTargetButton !== voiceInputButton) {
    controlButtons.push(state.audioVoiceTargetButton);
  }
  const inlineClarificationButtons = Array.from(document.querySelectorAll(".clarification-voice-input"));
  for (const button of inlineClarificationButtons) {
    if (button && !controlButtons.includes(button)) {
      controlButtons.push(button);
    }
  }
  if (!controlButtons.length) return;

  for (const button of controlButtons) {
    const requestedTargetContext = button.dataset.voiceContext || "";
    const baseLabel = requestedTargetContext || (button === voiceInputButton ? "prompt" : "response");
    button.dataset.state = state.audioRecordingState;
    button.classList.toggle("is-recording", recording);
    button.classList.toggle("is-transcribing", transcribing);
    button.classList.toggle("is-silence-warning", silenceWarning);
    button.disabled = busy || (!recording && (!canRecord || permissionDenied));
    let loadingDots = button.querySelector(".voice-input-loading-dots");
    if (!loadingDots) {
      loadingDots = document.createElement("span");
      loadingDots.className = "voice-input-loading-dots";
      loadingDots.setAttribute("aria-hidden", "true");
      loadingDots.hidden = true;
      loadingDots.innerHTML = "<span></span><span></span><span></span>";
      button.appendChild(loadingDots);
    }
    loadingDots.hidden = !transcribing;
    const label = silenceWarning
      ? "Silent"
      : recording
        ? "Stop"
      : state.audioRecordingState === "transcribing"
        ? "Mic"
        : permissionDenied
          ? "Blocked"
          : permissionPrompt && canRecord
            ? "Allow Mic"
            : "Mic";
    const labelNode = button.querySelector(".voice-input-label");
    if (labelNode) labelNode.textContent = label;
    const action = baseLabel === "prompt" ? "prompt" : baseLabel;
    const title = silenceWarning
      ? "Silence detected; recording will stop soon"
      : recording
        ? "Stop recording and transcribe"
      : permissionDenied
        ? microphonePermissionMessage()
        : canRecord
          ? (permissionPrompt
            ? "Allow microphone access for local dictation"
            : requestedTargetContext || `Dictate ${action} locally`)
          : audioUnavailableReason();
    button.title = title;
    button.setAttribute("aria-label", title);
  }
  if (enabled && canRecord && permissionDenied) {
    notifyMicrophonePermissionBlocked();
  }
}

function setAudioVoiceInputEnabled(enabled) {
  saveAgentSettings({
    ...state.agentSettings,
    audio_voice_input_enabled: Boolean(enabled),
  });
  if (enabled) {
    void refreshAudioPermissionState();
  }
  updateAudioVoiceControls();
}

function preferredAudioMimeType() {
  const candidates = [
    "audio/webm;codecs=opus",
    "audio/webm",
    "audio/ogg;codecs=opus",
    "audio/mp4",
  ];
  if (!("MediaRecorder" in window)) return "";
  return candidates.find((value) => MediaRecorder.isTypeSupported?.(value)) || "";
}

function audioCapturePresetConfig(settings = state.agentSettings) {
  const preset = normalizeAudioCapturePreset(settings?.audio_capture_preset);
  return AUDIO_CAPTURE_PRESETS[preset] || AUDIO_CAPTURE_PRESETS[AUDIO_CAPTURE_PRESET_DEFAULT];
}

function audioCaptureConstraints(settings = state.agentSettings) {
  const config = audioCapturePresetConfig(settings);
  if (!config || !config.constraints) {
    return { audio: true };
  }
  const constraints = { ...config.constraints };
  if (!Object.keys(constraints).length) {
    return { audio: true };
  }
  return { audio: constraints };
}

function audioCaptureRmsThreshold(settings = state.agentSettings) {
  const config = audioCapturePresetConfig(settings);
  return Number.parseFloat(config?.rmsThreshold) || AUDIO_SILENCE_RMS_THRESHOLD;
}

function audioCaptureSilenceTimeoutMs(settings = state.agentSettings) {
  const timeoutSeconds = normalizeAudioSilenceTimeoutSeconds(settings?.audio_silence_timeout_seconds);
  return Math.max(1000, Math.round(timeoutSeconds * 1000));
}

function audioCaptureSilenceWarningMs(silenceTimeoutMs) {
  return Math.min(3000, Math.max(1200, Math.round(silenceTimeoutMs * 0.25)));
}

function audioAmbientRmsFromSamples(samples, fallback) {
  const values = (Array.isArray(samples) ? samples : [])
    .map((value) => Number.parseFloat(value))
    .filter((value) => Number.isFinite(value) && value >= 0)
    .sort((left, right) => left - right);
  if (!values.length) {
    return Math.max(0, Number.parseFloat(fallback) || 0);
  }
  const index = clamp(
    Math.floor((values.length - 1) * AUDIO_SILENCE_AMBIENT_PERCENTILE),
    0,
    values.length - 1,
  );
  return values[index];
}

function audioDynamicSpeechThreshold(baseThreshold, ambientRms) {
  const base = Math.max(0, Number.parseFloat(baseThreshold) || AUDIO_SILENCE_RMS_THRESHOLD);
  const ambient = Math.max(0, Number.parseFloat(ambientRms) || 0);
  return Math.max(
    base,
    ambient + AUDIO_SILENCE_SPEECH_MARGIN,
    ambient * AUDIO_SILENCE_SPEECH_MULTIPLIER,
  );
}

function audioDynamicRecoveryThreshold(baseThreshold, ambientRms) {
  const base = Math.max(0, Number.parseFloat(baseThreshold) || AUDIO_SILENCE_RMS_THRESHOLD);
  const ambient = Math.max(0, Number.parseFloat(ambientRms) || 0);
  return Math.max(
    base * 0.65,
    ambient + AUDIO_SILENCE_RECOVERY_MARGIN,
    ambient * AUDIO_SILENCE_RECOVERY_MULTIPLIER,
  );
}

function audioShouldSampleAmbientRms(rms, baseThreshold, ambientRms, calibrating) {
  if (calibrating) {
    return true;
  }
  const value = Math.max(0, Number.parseFloat(rms) || 0);
  const base = Math.max(0, Number.parseFloat(baseThreshold) || AUDIO_SILENCE_RMS_THRESHOLD);
  const ambient = Math.max(0, Number.parseFloat(ambientRms) || 0);
  return value <= Math.max(base * 2.2, ambient + AUDIO_SILENCE_AMBIENT_SAMPLE_MARGIN);
}

function insertPromptTextAtCursor(text) {
  insertTextAtCursor(promptInput, text);
}

function resetTextareaHeight(input) {
  if (input instanceof HTMLTextAreaElement) {
    input.style.height = "";
  }
}

function resizePromptInput() {
  resetTextareaHeight(promptInput);
}

function insertTextAtCursor(input, text) {
  if (!input) return;
  const targetInput = input;
  const value = String(text || "").trim();
  if (!value) return;
  const start = targetInput.selectionStart ?? targetInput.value.length;
  const end = targetInput.selectionEnd ?? targetInput.value.length;
  const before = targetInput.value.slice(0, start);
  const after = targetInput.value.slice(end);
  const prefix = before && !/\s$/.test(before) ? " " : "";
  const suffix = after && !/^\s/.test(after) ? " " : "";
  targetInput.value = `${before}${prefix}${value}${suffix}${after}`;
  const cursor = before.length + prefix.length + value.length + suffix.length;
  targetInput.focus();
  targetInput.setSelectionRange(cursor, cursor);
  targetInput.dispatchEvent(new Event("input", { bubbles: true }));
}

function setAudioVoiceTarget(targetInput = null, targetButton = null, targetContext = "") {
  if (targetButton && !targetContext) {
    targetContext = targetButton.dataset.voiceContext || "";
  }
  state.audioVoiceTargetInput = targetInput || null;
  state.audioVoiceTargetButton = targetButton || null;
  state.audioVoiceTargetContext = targetContext || "";
  if (state.audioVoiceTargetButton) {
    state.audioVoiceTargetButton.dataset.voiceContext = state.audioVoiceTargetContext || state.audioVoiceTargetButton.dataset.voiceContext || "";
  }
}

function clearAudioVoiceTarget() {
  state.audioVoiceTargetInput = null;
  state.audioVoiceTargetButton = null;
  state.audioVoiceTargetContext = "";
}

function resolveActiveVoiceTargetInput() {
  if (state.audioVoiceTargetInput) {
    return state.audioVoiceTargetInput;
  }
  return promptInput;
}

function stopAudioTracks() {
  stopMicSilenceDetection();
  if (state.audioMediaStream) {
    for (const track of state.audioMediaStream.getTracks()) {
      track.stop();
    }
  }
  state.audioMediaStream = null;
}

function setAudioSilenceWarningActive(active) {
  const nextActive = Boolean(active);
  if (state.audioSilenceWarningActive === nextActive) return;
  state.audioSilenceWarningActive = nextActive;
  updateAudioVoiceControls();
}

function stopMicSilenceDetection() {
  setAudioSilenceWarningActive(false);
  if (state.audioSilenceDetectorTimer) {
    window.clearInterval(state.audioSilenceDetectorTimer);
    state.audioSilenceDetectorTimer = null;
  }
  if (state.audioSilenceDetectorSource) {
    try {
      state.audioSilenceDetectorSource.disconnect();
    } catch (_error) {
      // Best effort cleanup.
    }
    state.audioSilenceDetectorSource = null;
  }
  state.audioSilenceDetectorAnalyser = null;
  state.audioSilenceDetectorBuffer = null;
  if (state.audioSilenceDetectorContext) {
    try {
      state.audioSilenceDetectorContext.close();
    } catch (_error) {
      // Some browsers reject context close in edge cases; ignore.
    }
    state.audioSilenceDetectorContext = null;
  }
}

function startMicSilenceDetection() {
  const stream = state.audioMediaStream;
  const silenceTimeoutMs = audioCaptureSilenceTimeoutMs();
  if (silenceTimeoutMs <= 0) {
    return;
  }
  if (!stream) return;
  const AudioContextCtor = notificationAudioApi();
  if (!AudioContextCtor) return;
  const baseThreshold = audioCaptureRmsThreshold();
  stopMicSilenceDetection();
  try {
    const context = new AudioContextCtor();
    const source = context.createMediaStreamSource(stream);
    const analyser = context.createAnalyser();
    analyser.fftSize = 1024;
    const buffer = new Uint8Array(analyser.frequencyBinCount);
    source.connect(analyser);
    let aboveThresholdFrames = 0;
    let ambientRms = Math.max(0.002, baseThreshold * 0.5);
    let recoveryHoldUntilMs = 0;
    const ambientSamples = [];

    state.audioSilenceDetectorContext = context;
    state.audioSilenceDetectorSource = source;
    state.audioSilenceDetectorAnalyser = analyser;
    state.audioSilenceDetectorBuffer = buffer;
    state.audioSilenceDetectorLastSoundMs = Date.now();
    setAudioSilenceWarningActive(false);

    state.audioSilenceDetectorTimer = window.setInterval(() => {
      if (state.audioRecordingState !== "recording" || !state.audioSilenceDetectorAnalyser || !state.audioSilenceDetectorBuffer) {
        return;
      }
      try {
        state.audioSilenceDetectorAnalyser.getByteTimeDomainData(state.audioSilenceDetectorBuffer);
      } catch (_error) {
        return;
      }

      let energy = 0;
      for (const sample of state.audioSilenceDetectorBuffer) {
        const delta = (sample - 128) / 128;
        energy += delta * delta;
      }
      const rms = Math.sqrt(energy / state.audioSilenceDetectorBuffer.length);
      const now = Date.now();
      const calibrating = now - state.audioRecordingStartedAt < AUDIO_SILENCE_CALIBRATION_MS;
      if (audioShouldSampleAmbientRms(rms, baseThreshold, ambientRms, calibrating)) {
        ambientSamples.push(rms);
        while (ambientSamples.length > AUDIO_SILENCE_AMBIENT_SAMPLE_COUNT) {
          ambientSamples.shift();
        }
        ambientRms = audioAmbientRmsFromSamples(ambientSamples, ambientRms);
      }
      const speechThreshold = audioDynamicSpeechThreshold(baseThreshold, ambientRms);
      const recoveryThreshold = audioDynamicRecoveryThreshold(baseThreshold, ambientRms);
      const usingRecoveryThreshold = state.audioSilenceWarningActive || now < recoveryHoldUntilMs;
      const speechDetected = rms > (usingRecoveryThreshold ? recoveryThreshold : speechThreshold);
      const recoveringFromWarning = state.audioSilenceWarningActive && speechDetected;
      if (speechDetected && !calibrating) {
        aboveThresholdFrames += 1;
        if (recoveringFromWarning || aboveThresholdFrames >= 2) {
          state.audioSilenceDetectorLastSoundMs = now;
          if (usingRecoveryThreshold) {
            recoveryHoldUntilMs = now + AUDIO_SILENCE_RECOVERY_HOLD_MS;
          }
          setAudioSilenceWarningActive(false);
        }
        return;
      }
      aboveThresholdFrames = 0;
      if (calibrating) {
        state.audioSilenceDetectorLastSoundMs = now;
        return;
      }
      const silentDurationMs = now - state.audioSilenceDetectorLastSoundMs;
      if (silentDurationMs >= audioCaptureSilenceWarningMs(silenceTimeoutMs)) {
        setAudioSilenceWarningActive(true);
      }
      if (silentDurationMs > silenceTimeoutMs) {
        const timeoutSeconds = Math.max(1, Math.round(silenceTimeoutMs / 1000));
        addMessage(
          "assistant",
          "Voice input",
          `Recording stopped after ${timeoutSeconds} seconds of silence.`,
        );
        stopVoiceRecording();
      }
    }, AUDIO_SILENCE_CHECK_INTERVAL_MS);
  } catch (_error) {
    stopMicSilenceDetection();
  }
}

async function startVoiceRecording({ targetInput = null, targetButton = null, targetContext = "" } = {}) {
  if (!voiceInputButton || state.audioRecordingState !== "idle") return;
  setAudioVoiceTarget(targetInput, targetButton, targetContext);
  if (!state.audioTranscriberConfig) {
    await refreshAudioTranscriberConfig();
  }
  if (state.audioTranscriberConfig?.available !== true) {
    addMessage("assistant", "Voice input", audioUnavailableReason());
    clearAudioVoiceTarget();
    updateAudioVoiceControls();
    return;
  }
  if (state.audioPermissionState === "denied") {
    notifyMicrophonePermissionBlocked();
    clearAudioVoiceTarget();
    updateAudioVoiceControls();
    return;
  }
  try {
    let stream;
    try {
      stream = await navigator.mediaDevices.getUserMedia(audioCaptureConstraints());
    } catch (error) {
      if (
        error?.name === "OverconstrainedError" ||
        error?.name === "ConstraintNotSatisfiedError"
      ) {
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      } else {
        throw error;
      }
    }
    state.audioPermissionState = "granted";
    const mimeType = preferredAudioMimeType();
    const recorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);
    state.audioMediaStream = stream;
    state.audioMediaRecorder = recorder;
    state.audioChunks = [];
    state.audioRecordingState = "recording";
    state.audioRecordingStartedAt = Date.now();
    recorder.addEventListener("dataavailable", (event) => {
      if (event.data && event.data.size > 0) state.audioChunks.push(event.data);
    });
    recorder.addEventListener("stop", () => {
      void transcribeRecordedAudio();
    }, { once: true });
    recorder.start();
    const maxMs = Math.max(1, Number(state.audioTranscriberConfig?.max_duration_seconds || 120)) * 1000;
    clearTimeout(state.audioRecordingTimer);
    state.audioRecordingTimer = setTimeout(() => {
      if (state.audioRecordingState === "recording") stopVoiceRecording();
    }, maxMs);
    startMicSilenceDetection();
    updateAudioVoiceControls();
  } catch (error) {
    stopAudioTracks();
    state.audioRecordingState = "idle";
    state.audioSubmitAfterTranscription = false;
    clearAudioVoiceTarget();
    if (error?.name === "NotAllowedError" || error?.name === "SecurityError") {
      state.audioPermissionState = "denied";
      notifyMicrophonePermissionBlocked();
    } else {
      addMessage("assistant", "Voice input", `Microphone unavailable: ${shortStatusError(error)}`);
    }
    updateAudioVoiceControls();
  }
}

function stopVoiceRecording() {
  if (state.audioRecordingState !== "recording" || !state.audioMediaRecorder) return;
  state.audioRecordingState = "stopping";
  setAudioSilenceWarningActive(false);
  clearTimeout(state.audioRecordingTimer);
  state.audioRecordingTimer = null;
  try {
    state.audioMediaRecorder.stop();
  } catch (error) {
    state.audioRecordingState = "idle";
    state.audioSubmitAfterTranscription = false;
    clearAudioVoiceTarget();
    stopAudioTracks();
    addMessage("assistant", "Voice input", `Could not stop recording: ${shortStatusError(error)}`);
  }
  stopMicSilenceDetection();
  updateAudioVoiceControls();
}

async function transcribeRecordedAudio() {
  const chunks = state.audioChunks.slice();
  const type = state.audioMediaRecorder?.mimeType || preferredAudioMimeType() || "audio/webm";
  const targetInput = resolveActiveVoiceTargetInput();
  const shouldSubmitAfterTranscription =
    state.audioSubmitAfterTranscription === true && targetInput === promptInput;
  state.audioRecordingState = "transcribing";
  state.audioMediaRecorder = null;
  stopAudioTracks();
  updateAudioVoiceControls();
  try {
    if (!chunks.length) {
      addMessage("assistant", "Voice input", "No audio was recorded.");
    } else {
      const blob = new Blob(chunks, { type });
      const response = await fetch("/api/audio-transcriber/transcribe", {
        method: "POST",
        headers: { "Content-Type": blob.type || "audio/webm" },
        body: blob,
      });
      if (!response.ok) {
        throw new Error(await responseErrorMessage(response, "Transcription failed."));
      }
      const payload = await response.json();
      const transcript = String(payload?.transcript || "").trim();
      if (!transcript) {
        addMessage("assistant", "Voice input", "No speech was detected in the recording.");
      } else {
        insertTextAtCursor(targetInput, transcript);
      }
    }
  } catch (error) {
    addMessage("assistant", "Voice input", `Transcription failed: ${shortStatusError(error)}`);
  } finally {
    stopMicSilenceDetection();
    clearAudioVoiceTarget();
    state.audioChunks = [];
    state.audioSubmitAfterTranscription = false;
    state.audioRecordingState = "idle";
    updateAudioVoiceControls();
    if (shouldSubmitAfterTranscription && promptInput?.value.trim() && composerCanSubmit()) {
      window.setTimeout(() => {
        if (!composerCanSubmit() || state.audioRecordingState !== "idle") return;
        if (typeof form.requestSubmit === "function") {
          form.requestSubmit(submitButton);
        } else {
          submitButton.click();
        }
      }, 0);
    }
  }
}

function handleVoiceInputButtonClick(
  event,
  {
    targetInput,
    targetButton,
    targetContext,
  } = {},
) {
  event?.preventDefault?.();
  if (state.audioRecordingState === "recording") {
    stopVoiceRecording();
    return;
  }
  if (state.audioRecordingState === "idle") {
    void startVoiceRecording({
      targetInput,
      targetButton,
      targetContext,
    });
  }
}

function handleVoiceRecordingSubmitIntent() {
  if (!["recording", "stopping", "transcribing"].includes(state.audioRecordingState)) {
    return false;
  }
  state.audioSubmitAfterTranscription = resolveActiveVoiceTargetInput() === promptInput;
  if (state.audioRecordingState === "recording") {
    stopVoiceRecording();
  }
  return true;
}

async function addCommandAllowlistEntry(command, reason = "", sourceRequestId = "") {
  const value = String(command || "").trim();
  if (!value) {
    if (commandExceptionStatus) {
      commandExceptionStatus.textContent = "Enter an exact command first.";
    }
    showUiActionError({
      title: "Command required",
      message: "No command exception was saved because the command is empty.",
      fix: "Enter the exact command to allow, then add it again.",
      field: commandExceptionInput,
    });
    return null;
  }
  const response = await fetch("/api/agent/command-allowlist", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      command: value,
      reason: String(reason || ""),
      source_request_id: String(sourceRequestId || ""),
    }),
  });
  if (!response.ok) {
    throw new Error(await response.text());
  }
  const payload = await response.json();
  await loadCommandAllowlist();
  return payload;
}

async function addCommandAllowlistEntryFromSettings() {
  if (!commandExceptionAddButton) return;
  const previous = commandExceptionAddButton.textContent;
  commandExceptionAddButton.disabled = true;
  commandExceptionAddButton.textContent = "Adding...";
  try {
    await addCommandAllowlistEntry(commandExceptionInput?.value || "", "Manually allowed from Settings.");
    if (commandExceptionInput) {
      commandExceptionInput.value = "";
    }
  } catch (error) {
    if (commandExceptionStatus) {
      commandExceptionStatus.textContent = `Add failed: ${String(error?.message || error)}`;
    }
    showUiActionError({
      title: "Command exception add failed",
      message: shortStatusError(error),
      fix: "Check the exact command text and try adding it again.",
      field: commandExceptionInput,
    });
  } finally {
    commandExceptionAddButton.disabled = false;
    commandExceptionAddButton.textContent = previous || "Add command";
  }
}

async function deleteCommandAllowlistEntry(entryId) {
  const id = String(entryId || "").trim();
  if (!id) return;
  try {
    const response = await fetch(`/api/agent/command-allowlist/${encodeURIComponent(id)}`, {
      method: "DELETE",
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    await loadCommandAllowlist();
  } catch (error) {
    if (commandExceptionStatus) {
      commandExceptionStatus.textContent = `Delete failed: ${String(error?.message || error)}`;
    }
    showUiActionError({
      title: "Command exception delete failed",
      message: shortStatusError(error),
      fix: "Refresh command exceptions and try deleting again.",
    });
  }
}

function applyRuntimeControls(payload) {
  const autoApproveEnabled = payload?.auto_approve_commands === true;
  const eventsEnabled = payload?.agent_events_enabled !== false;
  const operatorPolicyProfile = normalizeOperatorPolicyProfile(
    payload?.operator_policy_profile ?? state.agentSettings?.operator_policy_profile,
  );
  const reasoningProfile = normalizeReasoningProfile(
    payload?.reasoning_profile ?? state.agentSettings?.reasoning_profile,
  );
  const repairProfile = normalizeRepairProfile(
    payload?.repair_profile ?? state.agentSettings?.repair_profile,
  );
  const workflowExecutionMode = normalizeWorkflowExecutionMode(
    payload?.workflow_execution_mode ?? state.agentSettings?.workflow_execution_mode,
  );
  const responseStreamingEnabled = Boolean(
    payload?.response_streaming_enabled ?? state.agentSettings?.response_streaming_enabled,
  );
  const promptRephraseEnabled =
    payload?.prompt_rephrase_enabled ?? state.agentSettings?.prompt_rephrase_enabled ?? true;
  const sqlAgentChatRouteMode = normalizeSqlAgentChatRouteMode(
    payload?.sql_agent_chat_route_mode || state.agentSettings?.sql_agent_chat_route_mode,
  );
  const clarificationMode = normalizeClarificationMode(
    payload?.agent_clarification_mode || state.agentSettings?.agent_clarification_mode,
  );
  const workspaceCwdGuardEnabled =
    payload?.operator_workspace_cwd_guard_enabled ??
    state.agentSettings?.operator_workspace_cwd_guard_enabled ??
    false;
  const operatorVerboseEnabled =
    payload?.llm_operator_verbose_enabled ??
    state.agentSettings?.llm_operator_verbose_enabled ??
    true;
  const stepValidationEnabled =
    payload?.llm_operator_step_validation_enabled ??
    state.agentSettings?.llm_operator_step_validation_enabled ??
    true;
  const finalResponseMode = normalizeFinalResponseMode(
    payload?.llm_operator_final_response_mode ??
      state.agentSettings?.llm_operator_final_response_mode,
  );
  const cardinalityJudgeMode = normalizeCardinalityJudgeMode(
    payload?.llm_operator_cardinality_judge_mode ??
      state.agentSettings?.llm_operator_cardinality_judge_mode,
  );
  const verificationEnforcedValue =
    payload?.llm_operator_verification_enforced ??
    state.agentSettings?.llm_operator_verification_enforced ??
    true;
  const maxClarificationRounds = clamp(
    Number.parseInt(
      payload?.llm_operator_max_clarification_rounds ??
        state.agentSettings?.llm_operator_max_clarification_rounds ??
        3,
      10,
    ) || 0,
    0,
    10,
  );
  const agentMemoryEnabled =
    payload?.agent_memory_enabled ?? state.agentSettings?.agent_memory_enabled ?? true;
  const agentMemoryPromptMaxChars = clamp(
    Number.parseInt(
      payload?.agent_memory_prompt_max_chars ??
        state.agentSettings?.agent_memory_prompt_max_chars ??
        3000,
      10,
    ) || 3000,
    200,
    20000,
  );
  const autoLearnEnabled =
    payload?.agent_learning_ledger_auto_learn_enabled ??
    state.agentSettings?.agent_learning_ledger_auto_learn_enabled ??
    true;
  const lrntEnabled = payload?.lrnt_enabled ?? state.agentSettings?.lrnt_enabled ?? true;
  const lrntSimilarityThreshold = normalizedUnitFloat(
    payload?.lrnt_similarity_threshold ?? state.agentSettings?.lrnt_similarity_threshold,
    defaultAgentSettings.lrnt_similarity_threshold,
  );
  const lrDirectEnabled =
    payload?.lrdirect_enabled ?? state.agentSettings?.lrdirect_enabled ?? true;
  const reliabilityMode = normalizeReliabilityMode(
    payload?.reliability_mode ?? state.agentSettings?.reliability_mode,
  );
  const reliabilityVerifierEnforced =
    payload?.reliability_verifier_enforced ??
    state.agentSettings?.reliability_verifier_enforced ??
    true;
  const audioServiceHost = normalizeAudioServiceHost(
    payload?.audio_transcriber_service_host ??
      state.agentSettings?.audio_transcriber_service_host ??
      "localhost",
  );
  const audioServicePort = normalizeAudioServicePort(
    payload?.audio_transcriber_service_port ??
      state.agentSettings?.audio_transcriber_service_port ??
      8012,
  );
  const llmEndpointSettings = normalizeAgentSettings({
    ...state.agentSettings,
    llm_base_scheme: payload?.llm_base_scheme ?? state.agentSettings?.llm_base_scheme,
    llm_base_host: payload?.llm_base_host ?? state.agentSettings?.llm_base_host,
    llm_base_port: payload?.llm_base_port ?? state.agentSettings?.llm_base_port,
    llm_base_path: payload?.llm_base_path ?? state.agentSettings?.llm_base_path,
    llm_timeout_seconds:
      payload?.llm_timeout_seconds ?? state.agentSettings?.llm_timeout_seconds,
    llm_max_tokens: payload?.llm_max_tokens ?? state.agentSettings?.llm_max_tokens,
  });
  const autoImmersiveMinWidthPx = normalizeAutoImmersiveMinWidthPx(
    payload?.ui_auto_immersive_min_width_px ??
      state.agentSettings?.ui_auto_immersive_min_width_px,
  );
  state.autoApproveCommands = autoApproveEnabled;
  state.agentEventsEnabled = eventsEnabled;
  state.reasoningProfile = reasoningProfile;
  state.workflowExecutionMode = workflowExecutionMode;
  if (autoApproveToggle) {
    autoApproveToggle.checked = autoApproveEnabled;
  }
  updateDeepReasoningToggle();
  updateWorkflowExecutionModeBadge();
  if (settingEventsEnabled) {
    settingEventsEnabled.checked = eventsEnabled;
  }
  saveAgentSettings({
    ...state.agentSettings,
    auto_approve_commands: autoApproveEnabled,
    agent_events_enabled: eventsEnabled,
    operator_policy_profile: operatorPolicyProfile,
    reasoning_profile: reasoningProfile,
    repair_profile: repairProfile,
    workflow_execution_mode: workflowExecutionMode,
    prompt_rephrase_enabled: promptRephraseEnabled !== false,
    response_streaming_enabled: responseStreamingEnabled,
    agent_clarification_mode: clarificationMode,
    sql_agent_chat_route_mode: sqlAgentChatRouteMode,
    operator_workspace_cwd_guard_enabled: Boolean(workspaceCwdGuardEnabled),
    llm_operator_verbose_enabled: Boolean(operatorVerboseEnabled),
    llm_operator_step_validation_enabled: Boolean(stepValidationEnabled),
    llm_operator_final_response_mode: finalResponseMode,
    llm_operator_cardinality_judge_mode: cardinalityJudgeMode,
    llm_operator_verification_enforced: verificationEnforcedValue !== false,
    llm_operator_max_clarification_rounds: maxClarificationRounds,
    agent_memory_enabled: agentMemoryEnabled !== false,
    agent_memory_prompt_max_chars: agentMemoryPromptMaxChars,
    agent_learning_ledger_auto_learn_enabled: autoLearnEnabled !== false,
    lrnt_enabled: lrntEnabled !== false,
    lrnt_similarity_threshold: lrntSimilarityThreshold,
    lrdirect_enabled: lrDirectEnabled === true,
    reliability_mode: reliabilityMode,
    reliability_verifier_enforced: reliabilityVerifierEnforced !== false,
    audio_transcriber_service_host: audioServiceHost,
    audio_transcriber_service_port: audioServicePort,
    llm_base_scheme: llmEndpointSettings.llm_base_scheme,
    llm_base_host: llmEndpointSettings.llm_base_host,
    llm_base_port: llmEndpointSettings.llm_base_port,
    llm_base_path: llmEndpointSettings.llm_base_path,
    llm_timeout_seconds: llmEndpointSettings.llm_timeout_seconds,
    llm_max_tokens: llmEndpointSettings.llm_max_tokens,
    ui_auto_immersive_min_width_px: autoImmersiveMinWidthPx,
  });
  renderEvents();
  if (autoApproveEnabled) {
    void maybeAutoApprovePendingConfirmation();
  }
}

async function loadRuntimeControls({
  preservePersistentSettings = false,
  collapsePanelsWhenUnavailable = false,
} = {}) {
  try {
    const response = await fetch("/api/agent/runtime-controls", { cache: "no-store" });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    if (preservePersistentSettings) {
      const safe = normalizeAgentSettings(state.agentSettings);
      Object.assign(payload, {
        auto_approve_commands: safe.auto_approve_commands,
        agent_events_enabled: safe.agent_events_enabled,
        operator_policy_profile: safe.operator_policy_profile,
        reasoning_profile: safe.reasoning_profile,
        repair_profile: safe.repair_profile,
        workflow_execution_mode: safe.workflow_execution_mode,
        prompt_rephrase_enabled: safe.prompt_rephrase_enabled,
        response_streaming_enabled: safe.response_streaming_enabled,
        sql_agent_chat_route_mode: safe.sql_agent_chat_route_mode,
        agent_clarification_mode: safe.agent_clarification_mode,
        operator_workspace_cwd_guard_enabled: safe.operator_workspace_cwd_guard_enabled,
        llm_operator_verbose_enabled: safe.llm_operator_verbose_enabled,
        llm_operator_step_validation_enabled: safe.llm_operator_step_validation_enabled,
        llm_operator_final_response_mode: safe.llm_operator_final_response_mode,
        llm_operator_cardinality_judge_mode: safe.llm_operator_cardinality_judge_mode,
        llm_operator_verification_enforced: safe.llm_operator_verification_enforced,
        llm_operator_max_clarification_rounds: safe.llm_operator_max_clarification_rounds,
        agent_memory_enabled: safe.agent_memory_enabled,
        agent_memory_prompt_max_chars: safe.agent_memory_prompt_max_chars,
        agent_learning_ledger_auto_learn_enabled: safe.agent_learning_ledger_auto_learn_enabled,
        lrnt_enabled: safe.lrnt_enabled,
        lrnt_similarity_threshold: safe.lrnt_similarity_threshold,
        lrdirect_enabled: safe.lrdirect_enabled,
        reliability_mode: safe.reliability_mode,
        reliability_verifier_enforced: safe.reliability_verifier_enforced,
        reliability_max_recovery_probes: safe.reliability_max_recovery_probes,
        reliability_max_autonomous_repair_attempts: safe.reliability_max_autonomous_repair_attempts,
        reliability_weak_model_plan_action_cap: safe.reliability_weak_model_plan_action_cap,
        reliability_approval_envelope_budget: safe.reliability_approval_envelope_budget,
        audio_transcriber_service_host: safe.audio_transcriber_service_host,
        audio_transcriber_service_port: safe.audio_transcriber_service_port,
        llm_base_scheme: safe.llm_base_scheme,
        llm_base_host: safe.llm_base_host,
        llm_base_port: safe.llm_base_port,
        llm_base_path: safe.llm_base_path,
        llm_base_url: safe.llm_base_url,
        llm_timeout_seconds: safe.llm_timeout_seconds,
        llm_max_tokens: safe.llm_max_tokens,
        ui_auto_immersive_min_width_px: safe.ui_auto_immersive_min_width_px,
      });
    }
    applyRuntimeControls(payload);
    if (preservePersistentSettings) {
      void saveRuntimeControls();
    }
  } catch {
    applyRuntimeControls({
      auto_approve_commands: state.agentSettings?.auto_approve_commands === true,
      agent_events_enabled: state.agentSettings?.agent_events_enabled !== false,
      operator_policy_profile: state.agentSettings?.operator_policy_profile || "assisted",
      reasoning_profile: state.agentSettings?.reasoning_profile || "balanced",
      repair_profile: state.agentSettings?.repair_profile || "balanced",
      workflow_execution_mode: state.agentSettings?.workflow_execution_mode || "streaming",
      prompt_rephrase_enabled: state.agentSettings?.prompt_rephrase_enabled !== false,
      response_streaming_enabled: state.agentSettings?.response_streaming_enabled !== false,
      agent_clarification_mode: state.agentSettings?.agent_clarification_mode || "balanced",
      sql_agent_chat_route_mode: state.agentSettings?.sql_agent_chat_route_mode || "agentic",
      operator_workspace_cwd_guard_enabled:
        state.agentSettings?.operator_workspace_cwd_guard_enabled === true,
      llm_operator_verbose_enabled: state.agentSettings?.llm_operator_verbose_enabled === true,
      llm_operator_step_validation_enabled:
        state.agentSettings?.llm_operator_step_validation_enabled !== false,
      llm_operator_final_response_mode:
        state.agentSettings?.llm_operator_final_response_mode || "simple",
      llm_operator_cardinality_judge_mode:
        state.agentSettings?.llm_operator_cardinality_judge_mode || "auto",
      llm_operator_verification_enforced:
        state.agentSettings?.llm_operator_verification_enforced !== false,
      llm_operator_max_clarification_rounds:
        state.agentSettings?.llm_operator_max_clarification_rounds ?? 3,
      agent_memory_enabled: state.agentSettings?.agent_memory_enabled !== false,
      agent_memory_prompt_max_chars:
        state.agentSettings?.agent_memory_prompt_max_chars ?? 3000,
      agent_learning_ledger_auto_learn_enabled:
        state.agentSettings?.agent_learning_ledger_auto_learn_enabled !== false,
      lrnt_enabled: state.agentSettings?.lrnt_enabled !== false,
      lrnt_similarity_threshold:
        state.agentSettings?.lrnt_similarity_threshold ??
        defaultAgentSettings.lrnt_similarity_threshold,
      lrdirect_enabled: state.agentSettings?.lrdirect_enabled !== false,
      reliability_mode: state.agentSettings?.reliability_mode || "standard",
      reliability_verifier_enforced: state.agentSettings?.reliability_verifier_enforced !== false,
      reliability_max_recovery_probes:
        state.agentSettings?.reliability_max_recovery_probes ?? 3,
      reliability_max_autonomous_repair_attempts:
        state.agentSettings?.reliability_max_autonomous_repair_attempts ?? 2,
      reliability_weak_model_plan_action_cap:
        state.agentSettings?.reliability_weak_model_plan_action_cap ?? 4,
      reliability_approval_envelope_budget:
        state.agentSettings?.reliability_approval_envelope_budget ?? 2,
      audio_transcriber_service_host:
        state.agentSettings?.audio_transcriber_service_host || "localhost",
      audio_transcriber_service_port:
        state.agentSettings?.audio_transcriber_service_port || 8012,
      llm_base_scheme: state.agentSettings?.llm_base_scheme || "http",
      llm_base_host: state.agentSettings?.llm_base_host || "127.0.0.1",
      llm_base_port: state.agentSettings?.llm_base_port || 8000,
      llm_base_path: state.agentSettings?.llm_base_path || "/v1",
      llm_base_url: state.agentSettings?.llm_base_url || "http://127.0.0.1:8000/v1",
      llm_timeout_seconds: state.agentSettings?.llm_timeout_seconds || 120,
      llm_max_tokens: state.agentSettings?.llm_max_tokens ?? 0,
      ui_auto_immersive_min_width_px:
        state.agentSettings?.ui_auto_immersive_min_width_px ?? DEFAULT_AUTO_IMMERSIVE_MIN_WIDTH_PX,
    });
    if (collapsePanelsWhenUnavailable || shouldCollapsePanelsByDefault()) {
      setTraceCollapsed(true);
      setVisualizationCollapsed(true);
    }
  }
}

async function saveRuntimeControls({ notifyOnError = false, rethrow = false } = {}) {
  const safe = normalizeAgentSettings(state.agentSettings);
  try {
    const response = await fetch("/api/agent/runtime-controls", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        auto_approve_commands: state.autoApproveCommands === true,
        agent_events_enabled: state.agentEventsEnabled !== false,
        operator_policy_profile: safe.operator_policy_profile,
        reasoning_profile: safe.reasoning_profile,
        repair_profile: safe.repair_profile,
        workflow_execution_mode: safe.workflow_execution_mode,
        prompt_rephrase_enabled: safe.prompt_rephrase_enabled,
        response_streaming_enabled: safe.response_streaming_enabled,
        agent_clarification_mode: safe.agent_clarification_mode,
        sql_agent_chat_route_mode: safe.sql_agent_chat_route_mode,
        operator_workspace_cwd_guard_enabled: safe.operator_workspace_cwd_guard_enabled,
        llm_operator_verbose_enabled: safe.llm_operator_verbose_enabled,
        llm_operator_step_validation_enabled: safe.llm_operator_step_validation_enabled,
        llm_operator_final_response_mode: safe.llm_operator_final_response_mode,
        llm_operator_cardinality_judge_mode: safe.llm_operator_cardinality_judge_mode,
        llm_operator_verification_enforced: safe.llm_operator_verification_enforced,
        llm_operator_max_clarification_rounds: safe.llm_operator_max_clarification_rounds,
        agent_memory_enabled: safe.agent_memory_enabled,
        agent_memory_prompt_max_chars: safe.agent_memory_prompt_max_chars,
        agent_learning_ledger_auto_learn_enabled: safe.agent_learning_ledger_auto_learn_enabled,
        lrnt_enabled: safe.lrnt_enabled,
        lrnt_similarity_threshold: safe.lrnt_similarity_threshold,
        lrdirect_enabled: safe.lrdirect_enabled,
        reliability_mode: safe.reliability_mode,
        reliability_verifier_enforced: safe.reliability_verifier_enforced,
        audio_transcriber_service_host: safe.audio_transcriber_service_host,
        audio_transcriber_service_port: safe.audio_transcriber_service_port,
        llm_base_scheme: safe.llm_base_scheme,
        llm_base_host: safe.llm_base_host,
        llm_base_port: safe.llm_base_port,
        llm_base_path: safe.llm_base_path,
        llm_base_url: safe.llm_base_url,
        llm_timeout_seconds: safe.llm_timeout_seconds,
        llm_max_tokens: safe.llm_max_tokens,
        ui_auto_immersive_min_width_px: safe.ui_auto_immersive_min_width_px,
      }),
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    applyRuntimeControls(await response.json());
  } catch (error) {
    await loadRuntimeControls();
    if (notifyOnError) {
      showUiActionError({
        title: "Runtime settings save failed",
        message: shortStatusError(error),
        fix: "Check the runtime connection, then apply the settings again.",
      });
    }
    if (rethrow) {
      throw error;
    }
  }
}

function setAutoApproveCommands(enabled, { syncServer = true } = {}) {
  state.autoApproveCommands = Boolean(enabled);
  if (autoApproveToggle) {
    autoApproveToggle.checked = state.autoApproveCommands;
  }
  saveAgentSettings({
    ...state.agentSettings,
    auto_approve_commands: state.autoApproveCommands,
  });
  if (syncServer) {
    void saveRuntimeControls();
    return;
  }
  if (state.autoApproveCommands) {
    void maybeAutoApprovePendingConfirmation();
  }
}

function updateDeepReasoningToggle(modeOverride) {
  const mode = normalizeReasoningProfile(
    modeOverride || state.reasoningProfile || state.agentSettings?.reasoning_profile,
  );
  if (deepReasoningToggle) {
    for (const button of deepReasoningToggle.querySelectorAll("button[data-mode]")) {
      const selected = String(button.dataset.mode || "") === mode;
      button.setAttribute("aria-pressed", selected ? "true" : "false");
    }
    deepReasoningToggle.dataset.mode = mode;
    deepReasoningToggle.title = `Reasoning profile: ${mode}`;
  }
  if (conversationDeepReasoningBadge) {
    const enabled = mode !== "fast";
    conversationDeepReasoningBadge.hidden = !enabled;
    conversationDeepReasoningBadge.textContent = mode === "deep" ? "DR+" : "BAL";
    conversationDeepReasoningBadge.title = `Reasoning profile: ${mode}`;
    conversationDeepReasoningBadge.setAttribute("aria-label", conversationDeepReasoningBadge.title);
  }
}

function setReasoningProfile(mode, { syncServer = true } = {}) {
  state.reasoningProfile = normalizeReasoningProfile(mode);
  saveAgentSettings({
    ...state.agentSettings,
    reasoning_profile: state.reasoningProfile,
  });
  updateDeepReasoningToggle();
  if (syncServer) {
    void saveRuntimeControls();
  }
}

function updateWorkflowExecutionModeBadge(modeOverride) {
  const mode = normalizeWorkflowExecutionMode(
    modeOverride || state.workflowExecutionMode || state.agentSettings?.workflow_execution_mode,
  );
  if (conversationStreamingBadge) {
    const enabled = mode === "streaming";
    conversationStreamingBadge.hidden = !enabled;
    conversationStreamingBadge.textContent = "Streaming";
    conversationStreamingBadge.title = "Workflow streaming is enabled";
    conversationStreamingBadge.setAttribute("aria-label", conversationStreamingBadge.title);
  }
}

function setAgentEventsEnabled(enabled, { syncServer = true } = {}) {
  state.agentEventsEnabled = Boolean(enabled);
  if (settingEventsEnabled) {
    settingEventsEnabled.checked = state.agentEventsEnabled;
  }
  saveAgentSettings({ ...state.agentSettings, agent_events_enabled: state.agentEventsEnabled });
  renderEvents();
  if (syncServer) {
    void saveRuntimeControls().then(() => loadEvents());
  }
}

function refreshModelAfterEndpointSettingsChange() {
  clearObservedEngineModel();
  updateModelStatus();
  renderLlmServiceStatus("Checking LLM endpoint...");
  void refreshModelConfig();
}

function agentSettingsContext() {
  const safe = normalizeAgentSettings(readSettingsFromControls());
  return {
    active_llm_model: String(state.activeModelName || "").trim(),
    agent_display_name: currentAgentName(),
    target_ui: "agent_ui",
    ...selectedGatewayContext(),
  };
}

function normalizeSpokenQuotedSegments(prompt) {
  const value = String(prompt || "");
  const spokenQuotedPattern =
    /\b(commit\s+message|commit\s+description|description|message|content|slash\s+type\s*in|slash\s+typein|\/\s*type\s*in|\/\s*typein|type\s*in|typein|slash\s+check\s+online\s+a\.?\s*i\.?|slash\s+checkonlineai|\/\s*check\s+online\s+a\.?\s*i\.?|\/\s*checkonlineai|check\s+online\s+a\.?\s*i\.?|checkonlineai)\s+(?:begin|start)\s+([\s\S]+?)\s+(?:end|stop)\b/gi;
  return value.replace(spokenQuotedPattern, (match, starter, textContent) => {
    const normalizedStarter = String(starter || "")
      .trim()
      .toLowerCase()
      .replace(/^[/:/ ]*slash\s+/, "")
      .replace(/^[/:/ ]+/, "")
      .replace(/\./g, "")
      .replace(/\s+/g, " ");
    let canonical = normalizedStarter;
    if (["type in", "typein"].includes(normalizedStarter)) {
      canonical = "typein";
    } else if (["check online ai", "check online a i", "checkonlineai"].includes(normalizedStarter)) {
      canonical = "checkonlineai";
    }
    const quoted = JSON.stringify(String(textContent || "").trim().replace(/\s+/g, " "));
    return `${canonical} ${quoted}`;
  });
}

function parseRequestIntents(prompt) {
  const value = normalizeSpokenQuotedSegments(String(prompt || "").trim());
  const autoApprovePattern =
    /(?:^\s*(?:\/?\s*auto[\s_-]*approv(?:e|ed)|\/?\s*auto[\s_-]*approval|\/?\s*auto[\s_-]*confirm(?:ed)?|slash\s+auto[\s_-]*(?:approv(?:e|ed)|approval|confirm(?:ed)?)|approve\s+automatically|automatically\s+approve)(?=$|[\s,.;:!?])|[\s,.;:!?](?:\/?\s*auto[\s_-]*approv(?:e|ed)|\/?\s*auto[\s_-]*approval|\/?\s*auto[\s_-]*confirm(?:ed)?|slash\s+auto[\s_-]*(?:approv(?:e|ed)|approval|confirm(?:ed)?)|approve\s+automatically|automatically\s+approve)\s*$)/gi;
  const quotePattern = /\bqoutes?\b/gi;
  const descriptionPattern = /\bdescription\s+begin\s+([\s\S]*?)\s+end\b/gi;
  const normalizedAutoApprove = value.replace(autoApprovePattern, " ");
  const withInlineQuote = normalizedAutoApprove.replace(quotePattern, "\"");
  const normalized = withInlineQuote.replace(
    descriptionPattern,
    (match, textContent) => `description "${String(textContent || "").trim()}"`,
  );
  const hasChanges = value !== normalized;
  if (hasChanges) {
    return {
      prompt: normalized.replace(/\s{2,}/g, " ").trim(),
      autoApprove: normalizedAutoApprove !== value,
    };
  }
  return { prompt: value, autoApprove: false };
}

function normalizeAgentMode(mode) {
  const value = String(mode || "").trim();
  return ["llm_operator", "standard", "advisory"].includes(value) ? value : "llm_operator";
}

function currentAgentMode() {
  return normalizeAgentMode(state.agentMode);
}

function setAgentMode(mode, options = {}) {
  const { persist = true } = options || {};
  const normalized = normalizeAgentMode(mode);
  state.agentMode = normalized;
  if (persist) {
    if (state.agentSettings?.ui_agent_mode !== normalized) {
      saveAgentSettings({ ...state.agentSettings, ui_agent_mode: normalized });
    }
  }
  for (const button of agentModeButtons) {
    const active = String(button.dataset.agentMode || "") === normalized;
    button.setAttribute("aria-checked", String(active));
    button.classList.toggle("active", active);
  }
  agentModeControl?.setAttribute("data-agent-mode", normalized);
}

function agentModePreservesConversation(mode = currentAgentMode()) {
  return ["llm_operator", "advisory"].includes(normalizeAgentMode(mode));
}

function selectedGatewayRecord() {
  const selectedId = String(state.selectedGatewayId || "").trim();
  return gatewayRecordById(selectedId);
}

function gatewayRecordById(gatewayId) {
  const id = String(gatewayId || "").trim();
  if (!id) {
    return null;
  }
  return state.gateways.find((gateway) => gateway.gateway_id === id) || null;
}

function enabledGateways() {
  return state.gateways.filter((gateway) => gateway.enabled !== false);
}

function rememberOperatedGateway(gatewayId) {
  const id = String(gatewayId || "").trim();
  if (!id) {
    return;
  }
  state.lastOperatedGatewayId = id;
  persistString(uiPreferences.lastOperatedGatewayId, id);
}

function restoreLastOperatedGatewaySelection() {
  if (state.gatewaySelectionRestored) {
    return;
  }
  state.gatewaySelectionRestored = true;
  const id = String(state.lastOperatedGatewayId || "").trim();
  if (!id) {
    return;
  }
  const enabled = state.gateways.filter((gateway) => gateway.enabled !== false);
  if (enabled.some((gateway) => gateway.gateway_id === id)) {
    state.selectedGatewayId = id;
    persistString(uiPreferences.selectedGatewayId, id);
  }
}

function terminalGatewayRecord() {
  const gatewayId = String(state.terminalConfig?.gateway_id || state.selectedGatewayId || "").trim();
  return state.gateways.find((gateway) => gateway.gateway_id === gatewayId) || selectedGatewayRecord();
}

function gatewayRegistrySelectedRecord() {
  const selectedId = String(state.selectedGatewayEditorId || state.selectedGatewayId || "").trim();
  return state.gateways.find((gateway) => gateway.gateway_id === selectedId) || selectedGatewayRecord();
}

function selectedGatewayContext() {
  const gateway = selectedGatewayRecord();
  return gatewayContextFromRecord(gateway);
}

function gatewayContextFromRecord(gateway) {
  if (!gateway) {
    return {};
  }
  const context = { gateway_id: gateway.gateway_id };
  const node = String(gateway.node || "").trim();
  if (node) {
    context.gateway_node = node;
  }
  [
    ["gateway_platform", gateway.platform],
    ["gateway_platform_label", gateway.platform_label],
    ["gateway_platform_version", gateway.platform_version],
    ["gateway_architecture", gateway.architecture],
    ["gateway_shell", gateway.shell],
    ["gateway_command_profile", gateway.command_profile],
  ].forEach(([key, value]) => {
    const text = String(value || "").trim();
    if (text) {
      context[key] = text;
    }
  });
  if (Array.isArray(gateway.capability_tags) && gateway.capability_tags.length) {
    context.gateway_capability_tags = gateway.capability_tags
      .map((tag) => String(tag || "").trim())
      .filter(Boolean);
  }
  return context;
}

function gatewayDisplayName(gateway) {
  const label = String(gateway?.label || gateway?.node || gateway?.host || "Gateway").trim();
  const node = String(gateway?.node || "").trim();
  return node && node !== label ? `${label} (${node})` : label;
}

function gatewayPlatformLabel(gateway) {
  const label = String(gateway?.platform_label || "").trim();
  if (label) {
    return label;
  }
  const platform = String(gateway?.platform || "").trim().toLowerCase();
  if (platform === "macos") return "macOS";
  if (platform === "linux") return "Linux";
  if (platform === "windows") return "Windows";
  return "Unknown";
}

function gatewayPlatformSummary(gateway) {
  const label = gatewayPlatformLabel(gateway);
  const version = String(gateway?.platform_version || "").trim();
  const arch = String(gateway?.architecture || "").trim();
  return [label, version, arch].filter(Boolean).join(" ");
}

function gatewayAddressText(gateway) {
  const host = String(gateway?.host || "").trim();
  const port = String(gateway?.port || "").trim();
  if (host) {
    return port ? `${host}:${port}` : host;
  }
  const baseUrl = String(gateway?.base_url || "").trim();
  if (!baseUrl) {
    return "";
  }
  try {
    const url = new URL(baseUrl);
    return url.port ? `${url.hostname}:${url.port}` : url.host;
  } catch {
    return baseUrl.replace(/^https?:\/\//i, "").replace(/\/$/, "");
  }
}

function updateTerminalGatewayBadge() {
  if (!terminalGatewayBadge) {
    return;
  }
  const config = state.terminalConfig || null;
  const gatewayId = String(config?.gateway_id || "").trim();
  const gateway = gatewayRecordById(gatewayId) || (config ? terminalGatewayRecord() : null);
  const name = gateway ? gatewayDisplayName(gateway) : String(config?.node || "").trim();
  const address = gatewayAddressText(gateway);
  const platform = gateway ? gatewayPlatformLabel(gateway) : "";
  const endpoint = [name, address].filter(Boolean).join(" @ ");
  const text = [platform, endpoint].filter(Boolean).join(" · ");
  terminalGatewayBadge.hidden = !text;
  terminalGatewayBadge.textContent = text;
  terminalGatewayBadge.title = text ? `Terminal gateway: ${text}` : "";
  terminalGatewayBadge.classList.toggle("connected", Boolean(text && state.terminalConnected));
  terminalGatewayBadge.dataset.connected = String(Boolean(text && state.terminalConnected));
}

function normalizeGatewayNickname(value) {
  return String(value || "").trim().split(/\s+/).filter(Boolean).join(" ");
}

function escapeRegExp(value) {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function gatewayNicknamePattern(gateway) {
  const nickname = normalizeGatewayNickname(gateway?.label || "");
  if (!nickname) {
    return null;
  }
  const body = nickname.split(/\s+/).map(escapeRegExp).join("\\s+");
  return new RegExp(`(^|[^A-Za-z0-9_])(@?${body})(?=$|[^A-Za-z0-9_])`, "gi");
}

function gatewayRoutingMetadata(mode, gateway = null, matchedText = "") {
  const metadata = { mode: String(mode || "default") || "default" };
  if (gateway) {
    metadata.gateway_id = String(gateway.gateway_id || "");
    metadata.gateway_nickname = normalizeGatewayNickname(gateway.label || "");
    metadata.gateway_node = String(gateway.node || "").trim();
    metadata.gateway_display_name = gatewayDisplayName(gateway);
    metadata.gateway_platform = String(gateway.platform || "").trim();
    metadata.gateway_platform_label = gatewayPlatformLabel(gateway);
    metadata.gateway_platform_version = String(gateway.platform_version || "").trim();
    metadata.gateway_shell = String(gateway.shell || "").trim();
    metadata.gateway_command_profile = String(gateway.command_profile || "").trim();
  }
  const match = String(matchedText || "").trim().replace(/^@/, "");
  if (match) {
    metadata.matched_text = match;
  }
  return metadata;
}

function distinctGatewayMatches(matches) {
  const seen = new Set();
  const distinct = [];
  matches.forEach((match) => {
    const gatewayId = String(match.gateway?.gateway_id || "").trim();
    if (!gatewayId || seen.has(gatewayId)) {
      return;
    }
    seen.add(gatewayId);
    distinct.push(match);
  });
  return distinct;
}

function gatewayRoutingPreview(prompt) {
  const text = String(prompt || "");
  const matches = [];
  state.gateways.forEach((gateway) => {
    const pattern = gatewayNicknamePattern(gateway);
    if (!pattern) {
      return;
    }
    let match = pattern.exec(text);
    while (match) {
      matches.push({
        gateway,
        matchedText: String(match[2] || match[0] || "").trim(),
        index: match.index + String(match[1] || "").length,
      });
      match = pattern.exec(text);
    }
  });
  matches.sort((left, right) => Number(left.index || 0) - Number(right.index || 0));
  const disabledMatches = distinctGatewayMatches(matches.filter((match) => match.gateway?.enabled === false));
  if (disabledMatches.length) {
    const names = disabledMatches.map((match) => gatewayDisplayName(match.gateway)).join(", ");
    return {
      status: "error",
      message: `Gateway nickname is disabled: ${names}. Pick an enabled gateway before running.`,
    };
  }
  const enabledMatches = distinctGatewayMatches(matches.filter((match) => match.gateway?.enabled !== false));
  if (enabledMatches.length > 1) {
    const names = enabledMatches.map((match) => gatewayDisplayName(match.gateway)).join(", ");
    return {
      status: "error",
      message: `Multiple gateway nicknames were mentioned: ${names}. Mention one gateway nickname.`,
    };
  }
  if (enabledMatches.length === 1) {
    const match = enabledMatches[0];
    const metadata = gatewayRoutingMetadata("nickname", match.gateway, match.matchedText);
    return {
      status: "ok",
      mode: "nickname",
      gateway: match.gateway,
      context: gatewayContextFromRecord(match.gateway),
      metadata,
    };
  }
  const selected = selectedGatewayRecord();
  if (selected) {
    return {
      status: "ok",
      mode: "selected",
      gateway: selected,
      context: gatewayContextFromRecord(selected),
      metadata: gatewayRoutingMetadata("selected", selected),
    };
  }
  return {
    status: "ok",
    mode: "default",
    gateway: null,
    context: {},
    metadata: gatewayRoutingMetadata("default"),
  };
}

function gatewayStatusText(gateway) {
  const status = String(gateway?.status || "unknown").trim() || "unknown";
  return gateway?.enabled === false ? `${status} / disabled` : status;
}

function defaultGatewayTerminalCwd() {
  return String(state.agentSettings?.llm_launch_cwd || defaultAgentSettings.llm_launch_cwd || "/tmp").trim() || "/tmp";
}

function gatewayTerminalCwdValue(gateway) {
  return String(gateway?.terminal_cwd || "").trim() || defaultGatewayTerminalCwd();
}

function gatewayIdFromContext(context = {}) {
  const raw = String(context?.gateway_id || "").trim();
  if (raw) {
    return raw;
  }
  const node = String(context?.gateway_node || context?.node || "").trim();
  if (!node) {
    return "";
  }
  const gateway = state.gateways.find((item) => String(item.node || "").trim() === node);
  return String(gateway?.gateway_id || "").trim();
}

function eventGatewayLabelFromContext(context = {}) {
  const gatewayId = gatewayIdFromContext(context);
  const gateway = gatewayRecordById(gatewayId);
  if (gateway) {
    return gatewayDisplayName(gateway);
  }
  const node = String(context?.gateway_node || context?.node || "").trim();
  if (gatewayId) {
    return `Missing gateway (${gatewayId})`;
  }
  if (node) {
    return `Gateway node ${node}`;
  }
  return "Default gateway";
}

function eventGatewaySelectedId() {
  return String(eventGateway?.value || state.eventEditorGatewayId || "").trim();
}

function eventGatewayRecord() {
  return gatewayRecordById(eventGatewaySelectedId());
}

function eventGatewayContext() {
  return gatewayContextFromRecord(eventGatewayRecord());
}

function renderEventGatewaySelect() {
  if (!eventGateway) {
    return;
  }
  const enabled = enabledGateways();
  const requestedId = String(
    state.eventEditorGatewayId || gatewayIdFromContext(state.eventEditorContext) || "",
  ).trim();
  eventGateway.replaceChildren();
  const defaultOption = document.createElement("option");
  defaultOption.value = "";
  defaultOption.textContent = enabled.length ? "Default gateway at run time" : "Default gateway";
  eventGateway.append(defaultOption);
  let hasRequested = requestedId === "";
  enabled.forEach((gateway) => {
    const option = document.createElement("option");
    option.value = gateway.gateway_id;
    option.textContent = gatewayDisplayName(gateway);
    eventGateway.append(option);
    if (gateway.gateway_id === requestedId) {
      hasRequested = true;
    }
  });
  if (requestedId && !hasRequested) {
    const option = document.createElement("option");
    option.value = requestedId;
    option.textContent = eventGatewayLabelFromContext({
      ...state.eventEditorContext,
      gateway_id: requestedId,
    });
    eventGateway.append(option);
  }
  eventGateway.value = requestedId;
  state.eventEditorGatewayId = String(eventGateway.value || "").trim();
}

function gatewaySummaryNames(gateways) {
  if (!gateways.length) {
    return "None";
  }
  return gateways.map((gateway) => gatewayDisplayName(gateway)).join(", ");
}

function updateGatewayRecord(record) {
  if (!record || !record.gateway_id) {
    return;
  }
  const index = state.gateways.findIndex((gateway) => gateway.gateway_id === record.gateway_id);
  if (index >= 0) {
    state.gateways.splice(index, 1, record);
  } else {
    state.gateways.push(record);
  }
}

function ensureSelectedGateway() {
  const enabled = enabledGateways();
  if (!enabled.length) {
    state.selectedGatewayId = "";
    persistString(uiPreferences.selectedGatewayId, "");
    return;
  }
  if (!enabled.some((gateway) => gateway.gateway_id === state.selectedGatewayId)) {
    const fallback = enabled.find((gateway) => gateway.gateway_id === state.defaultGatewayId) || enabled[0];
    state.selectedGatewayId = fallback.gateway_id;
    persistString(uiPreferences.selectedGatewayId, state.selectedGatewayId);
  }
}

function renderGatewaySelectElement(select, enabled) {
  select.replaceChildren();
  if (!enabled.length) {
    const option = document.createElement("option");
    option.value = "";
    option.textContent = "Default";
    select.append(option);
    select.value = "";
    return;
  }
  enabled.forEach((gateway) => {
    const option = document.createElement("option");
    option.value = gateway.gateway_id;
    option.textContent = gatewayDisplayName(gateway);
    select.append(option);
  });
  select.value = state.selectedGatewayId;
}

function renderGatewaySelector() {
  const selects = [gatewaySelect, immersiveGatewaySelect].filter(Boolean);
  if (!selects.length) {
    renderEventGatewaySelect();
    return;
  }
  ensureSelectedGateway();
  const enabled = enabledGateways();
  selects.forEach((select) => renderGatewaySelectElement(select, enabled));
  renderEventGatewaySelect();
}

function setSelectedGatewayFromPicker(value) {
  state.selectedGatewayId = String(value || "");
  state.selectedGatewayEditorId = state.selectedGatewayId;
  persistString(uiPreferences.selectedGatewayId, state.selectedGatewayId);
  renderGatewaySelector();
  fillGatewayEditor(selectedGatewayRecord());
  resetTerminalForGatewaySwitch();
  renderGatewayList();
  if (state.terminalVisible) {
    void setTerminalVisible(true);
  }
  void refreshGatewayHealth(state.selectedGatewayId);
}

function renderGatewaySummary() {
  if (!gatewayStatusSummary) {
    return;
  }
  const connected = state.gateways.filter((gateway) => gateway.enabled !== false && gateway.status === "connected");
  const disconnected = state.gateways.filter((gateway) => gateway.enabled === false || gateway.status !== "connected");
  const rows = [
    ["Connected", connected.length, gatewaySummaryNames(connected), "success"],
    ["Disconnected", disconnected.length, gatewaySummaryNames(disconnected), disconnected.length ? "failed" : "neutral"],
    ["Total", state.gateways.length, state.gateways.length ? "registered gateways" : "no gateways", "neutral"],
  ];
  gatewayStatusSummary.replaceChildren();
  for (const [label, value, detail, tone] of rows) {
    const card = document.createElement("div");
    card.className = `memory-stat-card gateway-stat-card ${tone}`;
    card.title = String(detail || "");
    const number = document.createElement("strong");
    number.textContent = String(value);
    const caption = document.createElement("span");
    caption.textContent = label;
    const detailText = document.createElement("small");
    detailText.textContent = String(detail || "");
    card.append(number, caption, detailText);
    gatewayStatusSummary.append(card);
  }
}

function renderGatewayActiveSummary() {
  if (!gatewayActiveSummary) {
    return;
  }
  const active = selectedGatewayRecord();
  const titleText = active ? gatewayDisplayName(active) : "Default";
  const detailText = active
    ? `${gatewayStatusText(active)} - ${gatewayPlatformSummary(active)} - cwd ${gatewayTerminalCwdValue(active)} - ${active.base_url || `${active.scheme}://${active.host}:${active.port}`}`
    : "Using the local/default execution target.";
  gatewayActiveSummary.replaceChildren();
  const label = document.createElement("span");
  label.textContent = "Active Gateway";
  const title = document.createElement("strong");
  title.textContent = titleText;
  const platformBadge = document.createElement("span");
  platformBadge.className = "gateway-os-badge";
  platformBadge.textContent = active ? gatewayPlatformLabel(active) : "Default";
  const detail = document.createElement("small");
  detail.textContent = detailText;
  gatewayActiveSummary.append(label, title, platformBadge, detail);
}

function fillGatewayEditor(gateway = null) {
  state.selectedGatewayEditorId = String(gateway?.gateway_id || "");
  if (gatewayLabel) gatewayLabel.value = String(gateway?.label || "");
  if (gatewayScheme) gatewayScheme.value = String(gateway?.scheme || "http");
  if (gatewayHost) gatewayHost.value = String(gateway?.host || "");
  if (gatewayPort) gatewayPort.value = String(gateway?.port || 8787);
  if (gatewayNode) gatewayNode.value = String(gateway?.node || "");
  if (gatewayTerminalCwd) gatewayTerminalCwd.value = gateway ? gatewayTerminalCwdValue(gateway) : defaultGatewayTerminalCwd();
  if (gatewayEnabled) gatewayEnabled.checked = gateway ? gateway.enabled !== false : true;
}

function renderGatewayRegistrySelect() {
  if (!gatewayRegistrySelect) {
    return;
  }
  gatewayRegistrySelect.replaceChildren();
  if (!state.gateways.length) {
    const option = document.createElement("option");
    option.value = "";
    option.textContent = "No gateways registered";
    gatewayRegistrySelect.append(option);
    gatewayRegistrySelect.value = "";
    gatewayRegistrySelect.disabled = true;
    return;
  }
  gatewayRegistrySelect.disabled = false;
  state.gateways.forEach((gateway) => {
    const option = document.createElement("option");
    option.value = gateway.gateway_id;
    option.textContent = `${gatewayDisplayName(gateway)} - ${gatewayPlatformLabel(gateway)} - ${gatewayStatusText(gateway)}`;
    gatewayRegistrySelect.append(option);
  });
  const selected = gatewayRegistrySelectedRecord();
  gatewayRegistrySelect.value = selected?.gateway_id || "";
}

function appendGatewayDetailRow(label, value) {
  if (!gatewayDetailsBody) {
    return;
  }
  const row = document.createElement("tr");
  const key = document.createElement("th");
  key.scope = "row";
  key.textContent = label;
  const detail = document.createElement("td");
  if (value === true) {
    detail.textContent = "Yes";
  } else if (value === false) {
    detail.textContent = "No";
  } else {
    detail.textContent = String(value || "-");
  }
  row.append(key, detail);
  gatewayDetailsBody.append(row);
}

function renderGatewayDetails() {
  if (!gatewayDetailsBody) {
    return;
  }
  gatewayDetailsBody.replaceChildren();
  const gateway = gatewayRegistrySelectedRecord();
  if (!gateway) {
    appendGatewayDetailRow("Selection", "Select a gateway to inspect its details.");
    return;
  }
  const knownRows = [
    ["Name", gatewayDisplayName(gateway)],
    ["Active target", gateway.gateway_id === state.selectedGatewayId],
    ["Status", gatewayStatusText(gateway)],
    ["Enabled", gateway.enabled !== false],
    ["Gateway ID", gateway.gateway_id],
    ["Base URL", gateway.base_url || `${gateway.scheme}://${gateway.host}:${gateway.port}`],
    ["Platform", gatewayPlatformSummary(gateway)],
    ["Shell", gateway.shell],
    ["Command profile", gateway.command_profile],
    ["Capability tags", Array.isArray(gateway.capability_tags) ? gateway.capability_tags.join(", ") : ""],
    ["Scheme", gateway.scheme],
    ["Host / IP", gateway.host],
    ["Port", gateway.port],
    ["Node", gateway.node],
    ["Terminal working dir", gatewayTerminalCwdValue(gateway)],
    ["Last checked", gateway.last_checked_at],
    ["Last error", gateway.last_error],
    ["Created", gateway.created_at],
    ["Updated", gateway.updated_at],
    ["Source", gateway.source],
  ];
  knownRows.forEach(([label, value]) => appendGatewayDetailRow(label, value));
}

function renderGatewayList() {
  renderGatewaySelector();
  renderTaskGatewayOptions();
  renderGatewaySummary();
  renderGatewayActiveSummary();
  updateTerminalGatewayBadge();
  if (!gatewayList) {
    return;
  }
  renderGatewayRegistrySelect();
  renderGatewayDetails();
}

async function loadGateways() {
  try {
    const response = await fetch("/api/agent/gateways", { cache: "no-store" });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    state.gateways = Array.isArray(payload.gateways) ? payload.gateways : [];
    state.defaultGatewayId = String(payload.default_gateway_id || "");
    restoreLastOperatedGatewaySelection();
    ensureSelectedGateway();
    renderGatewayList();
  } catch (error) {
    if (gatewayStatusSummary) {
      gatewayStatusSummary.textContent = `Gateway registry unavailable: ${shortStatusError(error)}`;
    }
    showUiActionError({
      title: "Gateway registry unavailable",
      message: shortStatusError(error),
      fix: "Check that the agent server is running, then refresh gateways again.",
    });
  }
}

async function refreshGatewayHealth(gatewayId) {
  const id = String(gatewayId || state.selectedGatewayId || "").trim();
  if (!id) {
    showUiActionError({
      title: "Gateway test needs a selection",
      message: "No gateway is selected for health check.",
      fix: "Select a saved gateway or save a new gateway first.",
      field: gatewayRegistrySelect || gatewayLabel,
    });
    return;
  }
  try {
    const response = await fetch(`/api/agent/gateways/${encodeURIComponent(id)}/health`, {
      method: "POST",
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    if (payload.gateway) {
      updateGatewayRecord(payload.gateway);
      renderGatewayList();
    }
  } catch (error) {
    if (gatewayStatusSummary) {
      gatewayStatusSummary.textContent = `Gateway check failed: ${shortStatusError(error)}`;
    }
    showUiActionError({
      title: "Gateway check failed",
      message: shortStatusError(error),
      fix: "Verify the gateway host, port, and gateway agent are reachable, then test again.",
      field: gatewayHost,
    });
  }
}

async function refreshVisibleGateways() {
  const ids = new Set();
  if (state.selectedGatewayId) {
    ids.add(state.selectedGatewayId);
  }
  if (state.gatewayDrawerOpen) {
    state.gateways.forEach((gateway) => ids.add(gateway.gateway_id));
  }
  for (const id of ids) {
    await refreshGatewayHealth(id);
  }
}

function startGatewayStatusPolling() {
  if (state.gatewayStatusTimer) {
    window.clearInterval(state.gatewayStatusTimer);
  }
  state.gatewayStatusTimer = window.setInterval(() => {
    void refreshVisibleGateways();
  }, 10000);
}

function readGatewayEditorPayload() {
  return {
    label: String(gatewayLabel?.value || "").trim(),
    scheme: String(gatewayScheme?.value || "http").trim() || "http",
    host: String(gatewayHost?.value || "").trim(),
    port: Number(gatewayPort?.value || 8787),
    node: String(gatewayNode?.value || "").trim(),
    terminal_cwd: String(gatewayTerminalCwd?.value || "").trim(),
    enabled: gatewayEnabled?.checked !== false,
  };
}

async function saveGatewayFromEditor() {
  const payload = readGatewayEditorPayload();
  if (!payload.label) {
    if (gatewayStatusSummary) {
      gatewayStatusSummary.textContent = "Gateway nickname is required.";
    }
    showUiActionError({
      title: "Gateway nickname required",
      message: "The gateway was not saved because the nickname is missing.",
      fix: "Enter a short nickname such as Workstation, then save again.",
      field: gatewayLabel,
    });
    return;
  }
  if (!payload.host) {
    if (gatewayStatusSummary) {
      gatewayStatusSummary.textContent = "Gateway host is required.";
    }
    showUiActionError({
      title: "Gateway host required",
      message: "The gateway was not saved because the host or IP address is missing.",
      fix: "Enter the gateway machine host or IP address, then save again.",
      field: gatewayHost,
    });
    return;
  }
  const editingId = String(state.selectedGatewayEditorId || "").trim();
  try {
    const response = await fetch(
      editingId ? `/api/agent/gateways/${encodeURIComponent(editingId)}` : "/api/agent/gateways",
      {
        method: editingId ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      },
    );
    if (!response.ok) {
      const message = await response.text();
      if (gatewayStatusSummary) {
        gatewayStatusSummary.textContent = message;
      }
      showUiActionError({
        title: editingId ? "Gateway update failed" : "Gateway save failed",
        message: shortStatusError(message),
        fix: "Review the gateway fields, especially nickname, host, and port, then save again.",
      });
      return;
    }
    const body = await response.json();
    if (body.gateway) {
      updateGatewayRecord(body.gateway);
      state.selectedGatewayId = body.gateway.gateway_id;
      persistString(uiPreferences.selectedGatewayId, state.selectedGatewayId);
      fillGatewayEditor(body.gateway);
      renderGatewayList();
      resetTerminalForGatewaySwitch();
    }
  } catch (error) {
    const message = shortStatusError(error);
    if (gatewayStatusSummary) {
      gatewayStatusSummary.textContent = message;
    }
    showUiActionError({
      title: editingId ? "Gateway update failed" : "Gateway save failed",
      message,
      fix: "Check the gateway details and network connection, then save again.",
    });
  }
}

async function deleteSelectedGateway() {
  const id = String(state.selectedGatewayEditorId || state.selectedGatewayId || "").trim();
  if (!id) {
    showUiActionError({
      title: "No gateway selected",
      message: "There is no saved gateway selected to delete.",
      fix: "Choose a gateway from the registry before deleting.",
      field: gatewayRegistrySelect || gatewayLabel,
    });
    return;
  }
  try {
    const response = await fetch(`/api/agent/gateways/${encodeURIComponent(id)}`, { method: "DELETE" });
    if (!response.ok) {
      const message = await response.text();
      if (gatewayStatusSummary) {
        gatewayStatusSummary.textContent = message;
      }
      showUiActionError({
        title: "Gateway delete failed",
        message: shortStatusError(message),
        fix: "Refresh the registry and try deleting the gateway again.",
      });
      return;
    }
    state.gateways = state.gateways.filter((gateway) => gateway.gateway_id !== id);
    if (state.selectedGatewayId === id) {
      state.selectedGatewayId = "";
      persistString(uiPreferences.selectedGatewayId, "");
      resetTerminalForGatewaySwitch();
    }
    fillGatewayEditor(null);
    renderGatewayList();
  } catch (error) {
    const message = shortStatusError(error);
    if (gatewayStatusSummary) {
      gatewayStatusSummary.textContent = message;
    }
    showUiActionError({
      title: "Gateway delete failed",
      message,
      fix: "Refresh the registry and try deleting the gateway again.",
    });
  }
}

function eventById(eventId) {
  const id = String(eventId || "").trim();
  return state.events.find((item) => item.event_id === id) || null;
}

function eventKindValue(event) {
  return String(event?.event_kind || "scheduled").toLowerCase() === "todo" ? "todo" : "scheduled";
}

function eventIntervalParts(seconds, scheduleType = "interval") {
  const value = Math.max(scheduleType === "once" ? 1 : 60, Number(seconds || 3600));
  if (scheduleType === "once" && value < 60) {
    return { value, unit: "seconds" };
  }
  if (value % 86400 === 0) {
    return { value: value / 86400, unit: "days" };
  }
  if (value % 3600 === 0) {
    return { value: value / 3600, unit: "hours" };
  }
  return { value: Math.max(1, Math.round(value / 60)), unit: "minutes" };
}

function eventIntervalSecondsFromEditor() {
  const value = Math.max(1, Number(eventIntervalValue?.value || 1));
  const unit = String(eventIntervalUnit?.value || "hours");
  const multiplier = unit === "days" ? 86400 : unit === "hours" ? 3600 : unit === "minutes" ? 60 : 1;
  const minimum = String(eventScheduleType?.value || "interval") === "once"
    && String(eventActionType?.value || "agent_prompt") === "notification"
    ? 1
    : 60;
  return Math.max(minimum, Math.round(value * multiplier));
}

function eventIntervalLabel(seconds, scheduleType = "interval") {
  const parts = eventIntervalParts(seconds, scheduleType);
  const unit = parts.value === 1 ? parts.unit.replace(/s$/, "") : parts.unit;
  return `${scheduleType === "once" ? "After" : "Every"} ${parts.value} ${unit}`;
}

function formatEventTime(value) {
  const text = String(value || "").trim();
  if (!text) return "-";
  const date = new Date(text);
  if (Number.isNaN(date.getTime())) return text;
  return date.toLocaleString();
}

function eventDurationLabel(totalSeconds) {
  const safeSeconds = Math.max(0, Math.ceil(Number(totalSeconds || 0)));
  const days = Math.floor(safeSeconds / 86400);
  const hours = Math.floor((safeSeconds % 86400) / 3600);
  const minutes = Math.floor((safeSeconds % 3600) / 60);
  const seconds = safeSeconds % 60;
  const pad = (value) => String(value).padStart(2, "0");
  if (days > 0) {
    return `${days}d ${pad(hours)}h ${pad(minutes)}m`;
  }
  if (hours > 0) {
    return `${hours}h ${pad(minutes)}m ${pad(seconds)}s`;
  }
  if (minutes > 0) {
    return `${minutes}m ${pad(seconds)}s`;
  }
  return `${seconds}s`;
}

function eventTimeUntilInfo(value, nowMs = Date.now()) {
  const text = String(value || "").trim();
  if (!text) return { label: "-", state: "none" };
  const date = new Date(text);
  const targetMs = date.getTime();
  if (Number.isNaN(targetMs)) {
    return { label: text, state: "unknown" };
  }
  const diffSeconds = Math.ceil((targetMs - nowMs) / 1000);
  if (Math.abs(diffSeconds) <= 1) {
    return { label: "Due now", state: "due" };
  }
  const duration = eventDurationLabel(Math.abs(diffSeconds));
  if (diffSeconds < 0) {
    return { label: `Overdue by ${duration}`, state: "overdue" };
  }
  return { label: duration, state: "upcoming" };
}

function eventNextInvocationBadgeText(value, nowMs = Date.now()) {
  const info = eventTimeUntilInfo(value, nowMs);
  if (info.state === "none") return "No next run";
  if (info.state === "unknown" || info.state === "overdue" || info.state === "due") return info.label;
  return `Next in ${info.label}`;
}

function refreshEventCountdownElement(element, nowMs = Date.now()) {
  if (!element) return;
  const nextRunAt = element.dataset.eventCountdown || "";
  const mode = element.dataset.eventCountdownMode || "detail";
  const info = eventTimeUntilInfo(nextRunAt, nowMs);
  element.dataset.countdownState = info.state;
  element.textContent = mode === "badge" ? eventNextInvocationBadgeText(nextRunAt, nowMs) : info.label;
  if (nextRunAt) {
    element.title = `Next invocation: ${formatEventTime(nextRunAt)}`;
  } else {
    element.removeAttribute("title");
  }
}

function colorContrastFromHsl(hue, saturation, lightness) {
  const [red, green, blue] = hslToRgb(hue, saturation, lightness);
  const luminance = (0.299 * red + 0.587 * green + 0.114 * blue) / 255;
  return luminance < 0.52 ? "#f8fafc" : "#0f172a";
}

function quickUpcomingEventHeatStyle(nextRunAt, nowMs = Date.now()) {
  const targetMs = Date.parse(String(nextRunAt || ""));
  if (Number.isNaN(targetMs)) {
    return null;
  }
  const remainingMs = targetMs - nowMs;
  const dueThresholdMs = UPCOMING_EVENTS_DUE_WINDOW_SECONDS * 1000;
  const maxWindowMs = UPCOMING_EVENTS_HEATMAP_WINDOW_SECONDS * 1000;
  const clampedProgress = remainingMs <= dueThresholdMs
    ? 0
    : Math.max(
        0,
        Math.min(1, remainingMs / maxWindowMs),
      );
  const hue = Math.round(clampedProgress * 220);
  const saturation = 56;
  const backgroundLightness = 82;
  const background = hslColor(hue, saturation, backgroundLightness);
  const border = hslColor(hue, saturation - 8, 68);
  const countdownBorder = hslColor(hue, saturation - 14, 74);
  const countdownBackground = hslColor(hue, saturation - 12, 90);
  const text = colorContrastFromHsl(hue, saturation, backgroundLightness);
  return {
    background,
    border,
    countdownBackground,
    countdownBorder,
    countdownText: text,
    text,
  };
}

function applyQuickUpcomingEventHeatStyles(eventRow, nowMs = Date.now()) {
  if (!(eventRow instanceof HTMLElement)) {
    return;
  }
  const nextRunAt = eventRow.dataset.nextRunAt || "";
  const style = quickUpcomingEventHeatStyle(nextRunAt, nowMs);
  if (!style) {
    return;
  }
  eventRow.style.setProperty("--quick-upcoming-event-bg", style.background);
  eventRow.style.setProperty("--quick-upcoming-event-text", style.text);
  eventRow.style.setProperty("--quick-upcoming-event-border", style.border);
  eventRow.style.setProperty(
    "--quick-upcoming-event-countdown-bg",
    style.countdownBackground,
  );
  eventRow.style.setProperty(
    "--quick-upcoming-event-countdown-border",
    style.countdownBorder,
  );
  eventRow.style.setProperty("--quick-upcoming-event-countdown-text", style.countdownText);
}

function refreshEventCountdowns() {
  eventsList?.querySelectorAll("[data-event-countdown]").forEach((element) => {
    refreshEventCountdownElement(element);
  });
  quickUpcomingEventsList?.querySelectorAll("[data-event-countdown]").forEach((element) => {
    refreshEventCountdownElement(element);
  });
  quickUpcomingEventsList?.querySelectorAll("[data-next-run-at].quick-upcoming-event").forEach((eventRow) => {
    applyQuickUpcomingEventHeatStyles(eventRow);
  });
}

function defaultEventWorkingDirectory() {
  const terminal = terminalRequestContext();
  const terminalCwd = String(terminal.terminal_cwd || "").trim();
  if (terminalCwd) return terminalCwd;
  const gatewayCwd = String((eventGatewayRecord() || selectedGatewayRecord())?.terminal_cwd || "").trim();
  if (gatewayCwd) return gatewayCwd;
  return defaultGatewayTerminalCwd();
}

function eventWorkingDirectoryLabel(event) {
  const context = event?.context || {};
  const cwd = String(context.terminal_cwd || "").trim();
  if (cwd) {
    return cwd;
  }
  const gateway = gatewayRecordById(gatewayIdFromContext(context));
  if (gateway) {
    return gatewayTerminalCwdValue(gateway);
  }
  return defaultGatewayTerminalCwd() || "-";
}

function setEventWorkingDirectory(value) {
  if (eventTerminalCwd) {
    eventTerminalCwd.value = String(value || "").trim();
  }
}

function openEventSection(section) {
  if (section && "open" in section) {
    section.open = true;
  }
}

function openEventEditorPanel() {
  openEventSection(eventEditorCard);
}

function openEventDetailsPanel() {
  openEventSection(eventRunsCard);
}

function clearEventEditor() {
  state.editingEventId = "";
  state.eventEditorContext = {};
  state.eventEditorEventKind = "scheduled";
  state.eventEditorNextRunAt = "";
  state.eventEditorGatewayId = String(selectedGatewayRecord()?.gateway_id || "").trim();
  openEventEditorPanel();
  if (eventTitle) eventTitle.value = "";
  if (eventPrompt) eventPrompt.value = "";
  renderEventGatewaySelect();
  setEventWorkingDirectory(defaultEventWorkingDirectory());
  if (eventIntervalValue) eventIntervalValue.value = "1";
  if (eventIntervalUnit) eventIntervalUnit.value = "hours";
  if (eventStatus) eventStatus.value = "active";
  if (eventAutoApprove) eventAutoApprove.checked = true;
  if (eventActionType) eventActionType.value = "agent_prompt";
  if (eventScheduleType) eventScheduleType.value = "interval";
  if (eventNotificationMessage) eventNotificationMessage.value = "";
  if (eventNotifySuccess) eventNotifySuccess.checked = false;
  renderEventsList();
  renderEventRuns();
  updateEventControls();
}

function fillEventEditor(event = null, { openEditor = true } = {}) {
  state.editingEventId = String(event?.event_id || "");
  if (event?.event_id) {
    state.selectedEventId = String(event.event_id);
    state.expandedEventIds.add(String(event.event_id));
  }
  state.eventEditorContext = event && event.context && typeof event.context === "object"
    ? { ...event.context }
    : {};
  state.eventEditorEventKind = eventKindValue(event);
  state.eventEditorNextRunAt = String(event?.next_run_at || "").trim();
  state.eventEditorGatewayId = gatewayIdFromContext(state.eventEditorContext);
  if (openEditor) {
    openEventEditorPanel();
  }
  openEventSection(eventListCard);
  if (state.eventEditorEventKind === "todo") {
    openEventSection(todoEventListCard);
  }
  openEventDetailsPanel();
  if (eventTitle) eventTitle.value = String(event?.title || "");
  if (eventPrompt) eventPrompt.value = String(event?.prompt || "");
  renderEventGatewaySelect();
  setEventWorkingDirectory(state.eventEditorContext.terminal_cwd || defaultEventWorkingDirectory());
  const parts = eventIntervalParts(event?.interval_seconds || 3600, event?.schedule_type || "interval");
  if (eventIntervalValue) eventIntervalValue.value = String(parts.value);
  if (eventIntervalUnit) eventIntervalUnit.value = parts.unit;
  if (eventStatus) eventStatus.value = String(event?.status || "active");
  if (eventAutoApprove) eventAutoApprove.checked = event ? event.auto_approve_confirmations !== false : true;
  if (eventActionType) eventActionType.value = String(event?.action_type || "agent_prompt");
  if (eventScheduleType) eventScheduleType.value = String(event?.schedule_type || "interval");
  if (eventNotificationMessage) eventNotificationMessage.value = String(event?.notification_message || "");
  if (eventNotifySuccess) {
    eventNotifySuccess.checked = Array.isArray(event?.notify_on) && event.notify_on.includes("completed");
  }
  renderEventsList();
  renderEventRuns();
  updateEventControls();
}

function selectEvent(event = null, { loadRuns = true } = {}) {
  state.selectedEventId = String(event?.event_id || "");
  if (event) {
    state.expandedEventIds.add(String(event.event_id || ""));
    openEventDetailsPanel();
  }
  renderEventsList();
  renderEventRuns();
  updateEventControls();
  if (event && loadRuns) {
    void loadSelectedEventRuns(event.event_id);
  }
}

function editSelectedEvent() {
  const event = eventById(state.selectedEventId);
  if (!event) {
    return;
  }
  fillEventEditor(event);
  void loadSelectedEventRuns(event.event_id);
}

function readEventPayload() {
  const settingsContext = { ...agentSettingsContext() };
  delete settingsContext.gateway_id;
  delete settingsContext.gateway_node;
  delete settingsContext.gateway_url;
  delete settingsContext.gateway_endpoints;
  delete settingsContext.node;
  const context = {
    ...state.eventEditorContext,
    ...settingsContext,
    ...eventGatewayContext(),
    agent_mode: currentAgentMode(),
    llm_model: selectedModelValue(),
  };
  if (!eventGatewaySelectedId()) {
    delete context.gateway_id;
    delete context.gateway_node;
    delete context.gateway_url;
    delete context.gateway_endpoints;
    delete context.node;
  }
  const gateway = eventGatewayRecord();
  const cwd = String(eventTerminalCwd?.value || "").trim();
  delete context.terminal_session_id;
  delete context.execute_in_terminal;
  if (cwd) {
    context.terminal_cwd = cwd;
  } else if (!String(context.terminal_cwd || "").trim() && gateway) {
    context.terminal_cwd = String(gateway.terminal_cwd || "").trim();
  }
  const notifyOn = [
    "failed",
    "cancelled",
    "skipped",
    "awaiting_confirmation",
    "awaiting_clarification",
  ];
  if (eventNotifySuccess?.checked === true) {
    notifyOn.unshift("completed");
  }
  const actionType = String(eventActionType?.value || "agent_prompt");
  const notificationMessage = String(eventNotificationMessage?.value || "").trim();
  const prompt = String(eventPrompt?.value || "").trim();
  return {
    title: String(eventTitle?.value || "").trim(),
    prompt: prompt || notificationMessage,
    status: String(eventStatus?.value || "active"),
    schedule_type: String(eventScheduleType?.value || "interval"),
    event_kind: String(state.eventEditorEventKind || "scheduled"),
    interval_seconds: eventIntervalSecondsFromEditor(),
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC",
    next_run_at: state.eventEditorNextRunAt || "",
    context,
    auto_approve_confirmations: eventAutoApprove?.checked !== false,
    action_type: actionType,
    notification_message: notificationMessage || (actionType === "notification" ? prompt : ""),
    notify_on: notifyOn,
  };
}

function renderEventsSummary() {
  if (!eventsStatusSummary) return;
  const active = state.events.filter((item) => item.status === "active").length;
  const paused = state.events.filter((item) => item.status === "paused").length;
  const completed = state.events.filter((item) => item.status === "completed").length;
  const cancelled = state.events.filter((item) => item.status === "cancelled").length;
  const todo = state.events.filter((item) => eventKindValue(item) === "todo").length;
  const items = [
    ["Active", active],
    ["Todo", todo],
    ["Paused", paused],
    ["Done", completed],
    ["Cancelled", cancelled],
  ];
  eventsStatusSummary.classList.toggle("is-disabled", state.agentEventsEnabled === false);
  eventsStatusSummary.replaceChildren();
  for (const [label, value] of items) {
    const card = document.createElement("div");
    card.className = "memory-stat-card";
    if (state.agentEventsEnabled === false) {
      card.title = "Runtime events are off.";
    }
    const number = document.createElement("strong");
    number.textContent = String(Number(value || 0));
    const caption = document.createElement("span");
    caption.textContent = label;
    card.append(number, caption);
    eventsStatusSummary.append(card);
  }
}

function updateEventControls() {
  const selected = eventById(state.selectedEventId);
  const selectedStatus = String(selected?.status || "");
  const enabled = state.agentEventsEnabled !== false;
  if (eventNewButton) eventNewButton.disabled = !enabled;
  if (eventEditButton) eventEditButton.disabled = !enabled || !selected;
  if (eventSaveButton) {
    eventSaveButton.disabled = !enabled;
    eventSaveButton.textContent = "Save";
  }
  if (eventRunNowButton) eventRunNowButton.disabled = !enabled || !selected;
  if (eventPauseButton) {
    eventPauseButton.disabled = !enabled || !selected || selectedStatus === "paused" || selectedStatus === "cancelled";
  }
  if (eventResumeButton) {
    eventResumeButton.disabled = !enabled || !selected || selectedStatus === "active";
  }
  if (eventCancelButton) {
    eventCancelButton.disabled = !enabled || !selected || selectedStatus === "cancelled";
  }
  if (eventDeleteButton) eventDeleteButton.disabled = !enabled || !selected;
}

function upcomingEvents(limit = 5) {
  const nowMs = Date.now();
  return state.events
    .filter((event) => String(event?.status || "active") === "active")
    .filter((event) => eventKindValue(event) !== "todo")
    .map((event) => {
      const nextRunAt = String(event?.next_run_at || "").trim();
      const timestamp = Date.parse(nextRunAt);
      return { event, nextRunAt, timestamp };
    })
    .filter((item) => item.nextRunAt && !Number.isNaN(item.timestamp))
    .sort((left, right) => {
      const leftDelta = Math.max(0, left.timestamp - nowMs);
      const rightDelta = Math.max(0, right.timestamp - nowMs);
      return leftDelta - rightDelta || left.timestamp - right.timestamp;
    })
    .slice(0, Math.max(1, Number(limit || 5)))
    .map((item) => item.event);
}

function todoEvents(limit = 5) {
  return state.events
    .filter((event) => String(event?.status || "active") === "active")
    .filter((event) => eventKindValue(event) === "todo")
    .slice(0, Math.max(1, Number(limit || 5)));
}

function renderQuickTodoEvents() {
  if (!quickTodoEventsList) return;
  quickTodoEventsList.replaceChildren();
  if (state.agentEventsEnabled === false) {
    quickTodoEventsList.append(empty("Events are off."));
    return;
  }
  const items = todoEvents(5);
  if (!items.length) {
    quickTodoEventsList.append(empty("No todo items."));
    return;
  }
  items.forEach((event) => {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "quick-upcoming-event quick-todo-event";
    row.setAttribute("aria-label", `Open ${event.title || event.prompt || "todo"}`);
    row.addEventListener("click", () => {
      selectEvent(event);
      fillEventEditor(event, { openEditor: false });
      setEventsDrawerOpen(true);
      setQuickControlsOpen(false);
    });

    const title = document.createElement("span");
    title.className = "quick-upcoming-event-title";
    title.textContent = event.title || event.notification_message || event.prompt || "Todo";

    const meta = document.createElement("span");
    meta.className = "quick-upcoming-event-meta";
    meta.textContent = "Todo";

    const badge = document.createElement("span");
    badge.className = "quick-upcoming-event-countdown";
    badge.textContent = "No schedule";

    row.append(title, meta, badge);
    quickTodoEventsList.append(row);
  });
}

function renderQuickUpcomingEvents() {
  if (!quickUpcomingEventsList) return;
  quickUpcomingEventsList.replaceChildren();
  if (state.agentEventsEnabled === false) {
    quickUpcomingEventsList.append(empty("Events are off."));
    return;
  }
  const items = upcomingEvents(5);
  if (!items.length) {
    quickUpcomingEventsList.append(empty("No upcoming events."));
    return;
  }
  items.forEach((event) => {
    const row = document.createElement("button");
    row.type = "button";
    row.dataset.nextRunAt = String(event.next_run_at || "");
    row.className = "quick-upcoming-event";
    row.setAttribute("aria-label", `Open ${event.title || event.prompt || "scheduled event"}`);
    row.addEventListener("click", () => {
      selectEvent(event);
      fillEventEditor(event, { openEditor: false });
      setEventsDrawerOpen(true);
      setQuickControlsOpen(false);
    });

    const title = document.createElement("span");
    title.className = "quick-upcoming-event-title";
    title.textContent = event.title || event.notification_message || event.prompt || "Scheduled event";

    const meta = document.createElement("span");
    meta.className = "quick-upcoming-event-meta";
    meta.textContent = event.action_type === "notification" ? "Reminder" : "Agent task";

    const countdown = document.createElement("span");
    countdown.className = "quick-upcoming-event-countdown";
    countdown.dataset.eventCountdown = String(event.next_run_at || "");
    countdown.dataset.eventCountdownMode = "detail";
    refreshEventCountdownElement(countdown);
    applyQuickUpcomingEventHeatStyles(row);

    row.append(title, meta, countdown);
    quickUpcomingEventsList.append(row);
  });
}

function eventStatusClass(status) {
  const normalized = String(status || "active").toLowerCase();
  if (normalized === "active") return "success";
  if (normalized === "completed") return "success";
  if (normalized === "paused") return "warning";
  if (normalized === "cancelled" || normalized === "deleted") return "error";
  return "info";
}

function renderEventsList() {
  const renderRows = (listElement, items, emptyMessage) => {
    if (!listElement) return;
    listElement.replaceChildren();
    if (!items.length) {
      listElement.append(empty(emptyMessage));
      return;
    }
    items.forEach((event) => {
      const eventId = String(event.event_id || "");
      const eventKind = eventKindValue(event);
      const row = document.createElement("details");
      row.className = "event-row";
      row.open = state.expandedEventIds.has(eventId);
      row.classList.toggle("selected", eventId === state.selectedEventId);
      row.dataset.status = String(event.status || "active");
      row.dataset.eventKind = eventKind;
      row.addEventListener("toggle", () => {
        if (row.open) {
          state.expandedEventIds.add(eventId);
        } else {
          state.expandedEventIds.delete(eventId);
        }
      });
      const header = document.createElement("summary");
      header.className = "event-row-header";
      header.addEventListener("click", (clickEvent) => {
        if (clickEvent.target instanceof Element && clickEvent.target.closest(".event-row-control")) {
          return;
        }
        state.selectedEventId = eventId;
        openEventDetailsPanel();
        document.querySelectorAll(".events-list .event-row.selected").forEach((selectedRow) => {
          selectedRow.classList.remove("selected");
        });
        row.classList.add("selected");
        renderEventRuns();
        updateEventControls();
        void loadSelectedEventRuns(eventId);
      });
      const titleGroup = document.createElement("span");
      titleGroup.className = "event-row-title-group";
      const title = document.createElement("strong");
      title.className = "event-row-title";
      title.textContent = event.title || event.prompt || event.event_id;
      const nextBadge = document.createElement("span");
      nextBadge.className = "event-row-next-badge";
      if (eventKind === "todo") {
        nextBadge.textContent = "No schedule";
        nextBadge.dataset.countdownState = "none";
      } else {
        nextBadge.dataset.eventCountdown = String(event.next_run_at || "");
        nextBadge.dataset.eventCountdownMode = "badge";
        refreshEventCountdownElement(nextBadge);
      }
      titleGroup.append(title, nextBadge);
      const actions = document.createElement("span");
      actions.className = "event-row-actions";
      const toggleLabel = document.createElement("label");
      toggleLabel.className = "event-row-toggle event-row-control";
      toggleLabel.title = "Turn this event on or off.";
      toggleLabel.addEventListener("click", (toggleClick) => {
        toggleClick.stopPropagation();
      });
      const toggle = document.createElement("input");
      toggle.type = "checkbox";
      toggle.checked = String(event.status || "active") === "active";
      toggle.setAttribute("aria-label", `Turn ${event.title || "event"} ${toggle.checked ? "off" : "on"}`);
      const toggleText = document.createElement("span");
      toggleText.className = "event-row-toggle-text";
      toggleText.textContent = toggle.checked ? "On" : "Off";
      toggle.addEventListener("change", (toggleChange) => {
        toggleChange.stopPropagation();
        toggle.disabled = true;
        void updateEventStatus(event.event_id, toggle.checked ? "active" : "paused");
      });
      toggleLabel.append(toggle, toggleText);
      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "event-row-delete event-row-control";
      deleteButton.title = "Delete this event.";
      deleteButton.setAttribute("aria-label", `Delete ${event.title || "event"}`);
      deleteButton.disabled = state.agentEventsEnabled === false;
      deleteButton.innerHTML = [
        '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">',
        '<path d="M3 6h18"/>',
        '<path d="M8 6V4h8v2"/>',
        '<path d="M19 6l-1 14H6L5 6"/>',
        '<path d="M10 11v5"/>',
        '<path d="M14 11v5"/>',
        "</svg>",
      ].join("");
      deleteButton.addEventListener("click", (deleteClick) => {
        deleteClick.preventDefault();
        deleteClick.stopPropagation();
        void deleteEvent(event.event_id);
      });
      actions.append(toggleLabel, deleteButton);
      header.append(titleGroup, actions);
      const content = document.createElement("div");
      content.className = "event-row-content";
      const lines = document.createElement("div");
      lines.className = "event-row-lines";
      const dueInRow = ["Due in", eventTimeUntilInfo(event.next_run_at).label, { countdown: true }];
      if (eventKind === "todo") {
        dueInRow[1] = "-";
        dueInRow[2] = { countdown: false };
      }
      [
        ["Action", event.action_type === "notification" ? "notification" : "agent prompt"],
        ["Status", event.status || "active"],
        ["Schedule", eventKind === "todo" ? "No schedule" : eventIntervalLabel(event.interval_seconds, event.schedule_type)],
        ["Next", eventKind === "todo" ? "-" : formatEventTime(event.next_run_at)],
        dueInRow,
        ["Last", formatEventTime(event.last_run_at)],
        ["Gateway", eventGatewayLabelFromContext(event.context)],
        ["Cwd", eventWorkingDirectoryLabel(event)],
      ].forEach(([labelText, valueText, options]) => {
        const line = document.createElement("span");
        line.className = "event-row-line";
        const label = document.createElement("span");
        label.className = "event-row-label";
        label.textContent = labelText;
        const value = document.createElement("span");
        value.className = "event-row-value";
        value.textContent = valueText;
        if (options?.countdown) {
          value.dataset.eventCountdown = String(event.next_run_at || "");
          value.dataset.eventCountdownMode = "detail";
          refreshEventCountdownElement(value);
        }
        line.append(label, value);
        lines.append(line);
      });
      const prompt = document.createElement("span");
      prompt.className = "event-row-prompt";
      prompt.textContent = `Prompt: ${event.prompt || ""}`;
      content.append(lines, prompt);
      row.append(header, content);
      listElement.append(row);
    });
  };
  const scheduledEvents = [];
  const todoEvents = [];
  for (const event of state.events || []) {
    if (eventKindValue(event) === "todo") {
      todoEvents.push(event);
    } else {
      scheduledEvents.push(event);
    }
  }
  renderRows(eventsList, scheduledEvents, "No scheduled events.");
  renderRows(todoEventsList, todoEvents, "No todo items.");
}

function findRenderedRequestAction(requestId) {
  const id = String(requestId || "").trim();
  if (!id) return null;
  const actions = document.querySelectorAll(".confirmation-actions, .clarification-actions");
  for (const action of actions) {
    if (String(action?.dataset?.requestId || "") === id) {
      return action;
    }
  }
  return null;
}

async function openEventRunTrace(run) {
  const requestId = String(run?.request_id || "").trim();
  if (!requestId) return;
  state.requestId = requestId;
  if (requestIdLabel) {
    requestIdLabel.textContent = requestId;
  }
  setEventsDrawerOpen(false);
  setConversationCollapsed(false);
  const existingAction = findRenderedRequestAction(requestId);
  if (existingAction) {
    existingAction.scrollIntoView({ block: "center", behavior: "smooth" });
    return;
  }
  state.confirmationRendered.delete(requestId);
  state.clarificationRendered.delete(requestId);
  await loadFinalTrace(requestId);
}

async function openBlockingEventRunTrace(run) {
  const eventId = String(state.selectedEventId || "");
  const blockedRunId = String(run?.blocked_by_event_run_id || "").trim();
  const blockedRequestId = String(run?.blocked_by_request_id || "").trim();
  const currentRuns = eventId ? (state.eventRuns[eventId] || []) : [];
  const blockingRun = blockedRunId
    ? currentRuns.find((item) => String(item?.event_run_id || "") === blockedRunId)
    : null;
  if (blockingRun?.request_id) {
    await openEventRunTrace(blockingRun);
    return;
  }
  if (blockedRequestId) {
    await openEventRunTrace({ request_id: blockedRequestId });
    return;
  }
  if (eventId) {
    await loadSelectedEventRuns(eventId);
    const refreshedRuns = state.eventRuns[eventId] || [];
    const refreshedBlockingRun = blockedRunId
      ? refreshedRuns.find((item) => String(item?.event_run_id || "") === blockedRunId)
      : null;
    if (refreshedBlockingRun?.request_id) {
      await openEventRunTrace(refreshedBlockingRun);
    }
  }
}

function eventRunCanCancel(run) {
  return ["running", "awaiting_confirmation", "awaiting_clarification"].includes(
    String(run?.status || "").trim()
  );
}

async function cancelEventRun(run) {
  const eventId = String(state.selectedEventId || "");
  const runId = String(run?.event_run_id || "").trim();
  if (!eventId || !runId || !eventRunCanCancel(run)) return;
  try {
    const response = await fetch(
      `/api/agent/events/${encodeURIComponent(eventId)}/runs/${encodeURIComponent(runId)}/cancel`,
      { method: "POST" }
    );
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    if (payload?.event) {
      const index = state.events.findIndex((item) => String(item.event_id || "") === eventId);
      if (index >= 0) {
        state.events[index] = payload.event;
      }
    }
    await loadSelectedEventRuns(eventId);
    renderEvents();
  } catch (error) {
    setStatus(`Event run cancel failed: ${shortStatusError(error)}`, "failed");
    showUiActionError({
      title: "Event run cancel failed",
      message: shortStatusError(error),
      fix: "Refresh the event run history and try canceling the active run again.",
    });
  }
}

function renderEventRuns() {
  if (!eventRuns) return;
  eventRuns.replaceChildren();
  const selectedId = String(state.selectedEventId || "");
  const runs = selectedId ? (state.eventRuns[selectedId] || []) : [];
  if (!selectedId) {
    eventRuns.append(empty("Select an event to see run history."));
    return;
  }
  if (!runs.length) {
    eventRuns.append(empty("No runs yet."));
    return;
  }
  runs.forEach((run, index) => {
    const row = document.createElement("details");
    row.className = "event-run-row";
    if (index === 0) {
      row.open = true;
    }
    const title = document.createElement("summary");
    title.className = "event-run-summary";
    title.textContent = `${run.status || "run"} · ${formatEventTime(run.started_at || run.scheduled_for)}`;
    const content = document.createElement("div");
    content.className = "event-run-content";
    const markdown = String(run.final_response_preview || run.error_preview || `Scheduled ${formatEventTime(run.scheduled_for)}`);
    const body = document.createElement("pre");
    body.className = "event-run-markdown";
    body.textContent = stripAssistantResponseChrome(markdown);
    content.append(body);
    if (run.blocked_by_event_run_id || run.blocked_by_request_id) {
      const blockedHint = document.createElement("span");
      blockedHint.className = "event-run-blocked-hint";
      const status = String(run.blocked_by_status || "open").trim();
      blockedHint.textContent = `Blocked by ${status} run.`;
      const blockedButton = document.createElement("button");
      blockedButton.type = "button";
      blockedButton.className = "event-run-link event-run-button";
      blockedButton.textContent = "Open blocking run";
      blockedButton.addEventListener("click", (eventClick) => {
        eventClick.preventDefault();
        void openBlockingEventRunTrace(run);
      });
      content.append(blockedHint, blockedButton);
    }
    if (eventRunCanCancel(run)) {
      const cancelButton = document.createElement("button");
      cancelButton.type = "button";
      cancelButton.className = "event-run-link event-run-button event-run-cancel-button";
      cancelButton.textContent = "Cancel run";
      cancelButton.addEventListener("click", (eventClick) => {
        eventClick.preventDefault();
        cancelButton.disabled = true;
        void cancelEventRun(run);
      });
      content.append(cancelButton);
    }
    if (run.request_id) {
      const link = document.createElement("a");
      link.className = "event-run-link";
      link.href = `/api/agent/trace/${encodeURIComponent(run.request_id)}`;
      link.textContent = `Trace ${run.request_id}`;
      link.addEventListener("click", (eventClick) => {
        eventClick.preventDefault();
        void openEventRunTrace(run);
      });
      content.append(link);
    }
    row.append(title, content);
    eventRuns.append(row);
  });
}

function renderEvents() {
  renderEventsSummary();
  renderEventsList();
  renderEventRuns();
  renderQuickTodoEvents();
  renderQuickUpcomingEvents();
  updateEventControls();
}

function formatNotificationTime(value) {
  return formatEventTime(value);
}

function notificationKey(notification) {
  return String(notification?.notification_id || notification?.id || "");
}

function notificationToastDedupKey(notification) {
  const id = notificationKey(notification);
  if (id) {
    return `id:${id}`;
  }
  return [
    String(notification?.level || "info"),
    String(notification?.title || "Notification"),
    String(notification?.message || ""),
    String(notification?.source_type || ""),
    notificationRequestId(notification),
  ].map((part) => part.trim()).join("\u001f");
}

function removeNotificationCard(card) {
  const dedupKey = String(card?.dataset?.dedupKey || "").trim();
  if (dedupKey) {
    state.notificationToastDedup.delete(dedupKey);
  }
  card?.remove();
}

function updateNotificationDuplicateCount(card, count) {
  const safeCount = Math.max(1, Number.parseInt(String(count || 1), 10) || 1);
  card.dataset.duplicateCount = String(safeCount);
  const badge = card.querySelector(".notification-duplicate-count");
  if (!badge) {
    return;
  }
  badge.hidden = safeCount <= 1;
  badge.textContent = `x${safeCount}`;
  badge.title = `${safeCount} repeated notification${safeCount === 1 ? "" : "s"}`;
}

function notificationRequestId(notification) {
  const direct = String(notification?.request_id || "").trim();
  if (direct) return direct;
  const metadata = notification?.metadata && typeof notification.metadata === "object"
    ? notification.metadata
    : {};
  return String(metadata.request_id || "").trim();
}

function notificationTaskId(notification) {
  const direct = String(notification?.task_id || notification?.durable_task_id || "").trim();
  if (direct) return direct;
  const metadata = notification?.metadata && typeof notification.metadata === "object"
    ? notification.metadata
    : {};
  return String(metadata.task_id || metadata.durable_task_id || "").trim();
}

function notificationStreamUrl(notification) {
  const direct = String(notification?.stream_url || "").trim();
  if (direct) return direct;
  const metadata = notification?.metadata && typeof notification.metadata === "object"
    ? notification.metadata
    : {};
  return String(metadata.stream_url || "").trim();
}

function shouldSuppressLiveTaskNotificationDelivery(notification) {
  const sourceType = String(notification?.source_type || "").trim();
  if (!["durable_task", "durable_task_local"].includes(sourceType)) {
    return false;
  }
  const requestId = notificationRequestId(notification);
  const activeRequestId = String(state.requestId || "").trim();
  if (requestId && activeRequestId && requestId === activeRequestId) {
    return true;
  }
  const taskId = notificationTaskId(notification);
  const attachedTaskId = String(state.attachedTaskId || "").trim();
  if (taskId && attachedTaskId && taskId === attachedTaskId) {
    return true;
  }
  const attachedTask = attachedTaskForActiveRun();
  return Boolean(attachedTask && taskId && taskId === taskIdValue(attachedTask));
}

function markSuppressedLiveTaskNotificationRead(notification) {
  const id = notificationKey(notification);
  if (!id || String(notification?.status || "unread") !== "unread") {
    return false;
  }
  fetch(`/api/agent/notifications/${encodeURIComponent(id)}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ status: "read" }),
  }).catch(() => {});
  notification.status = "read";
  return true;
}

function notificationDetailChips(notification) {
  const metadata = notification?.metadata && typeof notification.metadata === "object"
    ? notification.metadata
    : {};
  const chips = [];
  const eventStatus = String(metadata.event_status || "").trim();
  if (metadata.completed_successfully === true || eventStatus === "completed") {
    chips.push("Completed successfully");
  }
  if (metadata.auto_approved_confirmation === true || eventStatus === "auto_approved") {
    chips.push("Auto-approved");
    const actionCount = Number(metadata.confirmation_action_count || 0);
    if (actionCount > 0) {
      chips.push(`${actionCount} approval${actionCount === 1 ? "" : "s"}`);
    }
  }
  return chips;
}

function notificationMarkdownText(value) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  if (typeof value === "string") {
    return value.trim();
  }
  try {
    return `\`\`\`json\n${JSON.stringify(value, null, 2)}\n\`\`\``;
  } catch {
    return String(value || "").trim();
  }
}

function notificationMarkdownDedupKey(value) {
  const text = notificationMarkdownText(value);
  if (!text) {
    return "";
  }
  const fenced = /^```(?:[a-z0-9_-]+)?\n([\s\S]*?)\n```$/i.exec(text.trim());
  const comparable = fenced ? fenced[1].trim() : text.trim();
  const jsonKey = streamingCompletionCanonicalJsonKey(comparable);
  if (jsonKey) {
    return jsonKey;
  }
  return comparable.replace(/\s+/g, " ").trim().toLowerCase();
}

function notificationRawSectionPriority(key, label) {
  const normalizedKey = String(key || "").trim().toLowerCase();
  const normalizedLabel = String(label || "").trim().toLowerCase();
  return normalizedKey.startsWith("raw_")
    || normalizedLabel.startsWith("raw ")
    || normalizedLabel === "payload";
}

function notificationRawMarkdownSections(notification) {
  const metadata = notification?.metadata && typeof notification.metadata === "object"
    ? notification.metadata
    : {};
  const fields = [
    ["raw_data_markdown", "Raw data"],
    ["raw_markdown", "Raw data"],
    ["details_markdown", "Details"],
    ["result_markdown", "Result"],
    ["final_response_markdown", "Final answer"],
    ["markdown", "Details"],
    ["raw_data", "Raw data"],
    ["raw_payload", "Raw payload"],
    ["raw_payloads", "Raw payloads"],
    ["payload", "Payload"],
  ];
  const sectionByContent = new Map();
  fields.forEach(([key, label], index) => {
    if (!Object.prototype.hasOwnProperty.call(metadata, key)) {
      return;
    }
    const markdown = notificationMarkdownText(metadata[key]);
    const dedupKey = notificationMarkdownDedupKey(markdown);
    if (!markdown || !dedupKey) {
      return;
    }
    const raw = notificationRawSectionPriority(key, label);
    const existing = sectionByContent.get(dedupKey);
    if (existing && (existing.raw || !raw)) {
      return;
    }
    sectionByContent.set(dedupKey, { label, markdown, dedupKey, raw, index });
  });
  return [...sectionByContent.values()].sort((left, right) => left.index - right.index);
}

function appendNotificationMarkdownSection(parent, label, markdown, { raw = false } = {}) {
  const text = notificationMarkdownText(markdown);
  if (!text) {
    return null;
  }
  const section = document.createElement("section");
  section.className = `notification-card-markdown${raw ? " notification-card-raw-markdown" : ""}`;
  section.dataset.copyText = text;
  if (label) {
    const heading = document.createElement("div");
    heading.className = "notification-card-markdown-label";
    heading.textContent = label;
    section.append(heading);
  }
  const body = document.createElement("div");
  body.className = "markdown-body notification-card-markdown-body";
  body.innerHTML = renderMarkdown(text, { skipStreamingCompletion: true });
  section.append(body);
  parent.append(section);
  return section;
}

function notificationChatUnavailableMessage(requestId, detail = "") {
  const reason = apiErrorMessageFromText(detail);
  const suffix = reason ? `\n\nServer response: ${reason}` : "";
  return (
    `The chat for request ${requestId} is not available anymore. ` +
    "It may have been deleted, expired, or created by another runtime session." +
    suffix
  );
}

function browserNotificationsSupported() {
  return typeof window.Notification === "function";
}

function browserNotificationPermission() {
  if (!browserNotificationsSupported()) {
    return "unsupported";
  }
  return String(window.Notification.permission || "default");
}

function browserNotificationStatusText(detail = "") {
  const status = String(detail || "").trim();
  if (status) {
    return status;
  }
  if (!browserNotificationsSupported()) {
    return "Browser notifications are not supported in this browser.";
  }
  const permission = browserNotificationPermission();
  if (!state.agentSettings?.browser_notifications_enabled) {
    return "Browser notifications are off.";
  }
  if (permission === "granted") {
    return "Browser notifications are enabled for this browser.";
  }
  if (permission === "denied") {
    return "Browser notifications are blocked in browser site settings.";
  }
  return "Browser permission is needed before OS notifications can appear.";
}

function updateBrowserNotificationControls(detail = "") {
  const permission = browserNotificationPermission();
  if (browserNotificationsStatus) {
    browserNotificationsStatus.textContent = browserNotificationStatusText(detail);
    browserNotificationsStatus.dataset.permission = permission;
  }
  if (browserNotificationsPermissionButton) {
    browserNotificationsPermissionButton.disabled =
      !browserNotificationsSupported()
      || !state.agentSettings?.browser_notifications_enabled
      || permission !== "default";
    browserNotificationsPermissionButton.textContent =
      permission === "granted" ? "Allowed" : permission === "denied" ? "Blocked" : "Allow browser notifications";
  }
}

async function requestBrowserNotificationPermission() {
  if (!browserNotificationsSupported()) {
    updateBrowserNotificationControls("Browser notifications are not supported in this browser.");
    return "unsupported";
  }
  if (!state.agentSettings?.browser_notifications_enabled) {
    updateBrowserNotificationControls("Turn on browser notifications first.");
    return browserNotificationPermission();
  }
  let permission = browserNotificationPermission();
  if (permission === "default") {
    try {
      permission = await window.Notification.requestPermission();
    } catch {
      permission = browserNotificationPermission();
    }
  }
  updateBrowserNotificationControls();
  return permission;
}

function shouldShowBrowserNotification(notification) {
  return Boolean(
    state.agentSettings?.browser_notifications_enabled
    && browserNotificationPermission() === "granted"
    && (notificationKey(notification) || String(notification?.source_type || "").trim()),
  );
}

function showBrowserNotification(notification) {
  if (!shouldShowBrowserNotification(notification)) {
    return null;
  }
  const title = String(notification?.title || "OpenFabric notification").trim() || "OpenFabric notification";
  const body = String(notification?.message || "").trim();
  const tag = notificationToastDedupKey(notification);
  try {
    const notice = new window.Notification(title, {
      body,
      tag,
      renotify: true,
      silent: true,
    });
    notice.onclick = () => {
      window.focus();
      const requestId = notificationRequestId(notification);
      if (requestId) {
        void openNotificationRequest(notification, null, { view: "trace" });
      }
      notice.close();
    };
    return notice;
  } catch {
    updateBrowserNotificationControls("Browser notification delivery failed.");
    return null;
  }
}

function setClientTraceOpen(open) {
  if (!state.agentUiClientMode) {
    return;
  }
  state.clientTraceOpen = Boolean(open);
  document.body?.classList?.toggle("client-trace-open", state.clientTraceOpen);
  if (!state.clientTraceOpen) {
    scrollChatToBottom({ force: true, behavior: "smooth" });
  }
}

async function openNotificationRequest(notification, card = null, options = {}) {
  const requestId = notificationRequestId(notification);
  if (!requestId) return;
  const view = String(options.view || "final").trim().toLowerCase();
  const fullTrace = view === "trace" || view === "full_trace";
  if (state.agentUiClientMode) {
    setClientTraceOpen(fullTrace);
  }
  state.requestId = requestId;
  if (requestIdLabel) {
    requestIdLabel.textContent = requestId;
  }
  setConversationCollapsed(false);
  setNotificationsDrawerOpen(false);
  setRunStatus("opening request", "running");
  const progress = showRequestLoadProgress({
    requestId,
    title: fullTrace ? "Loading notification trace" : "Loading notification chat",
    detail: fullTrace ? "Fetching full saved trace..." : "Fetching saved trace...",
  });
  let loaded = false;
  let unavailableDetail = "";
  try {
    loaded = await loadFinalTrace(requestId, {
      renderTraceEvents: fullTrace,
      focusTrace: fullTrace,
      onTracePayload: () => updateRequestLoadProgress(
        progress,
        fullTrace ? "Rendering notification trace..." : "Rendering notification chat...",
      ),
      onTraceUnavailable: (detail) => {
        unavailableDetail = String(detail?.message || detail?.statusText || "").trim();
        updateRequestLoadProgress(progress, "Chat session unavailable.");
      },
    });
    if (!loaded) {
      setRunStatus("failed", "failed");
      addMessage(
        "assistant",
        "Chat unavailable",
        notificationChatUnavailableMessage(requestId, unavailableDetail),
      );
    }
  } catch (error) {
    setRunStatus("failed", "failed");
    addMessage(
      "assistant",
      "Chat unavailable",
      notificationChatUnavailableMessage(requestId, shortStatusError(error)),
    );
  } finally {
    clearRequestLoadProgress(progress, "Request could not be loaded.");
  }
  const id = notificationKey(notification);
  if (id && String(notification?.status || "unread") === "unread") {
    void updateNotificationStatus(id, "read");
  }
  if (card?.classList?.contains("notification-toast")) {
    removeNotificationCard(card);
  }
  const action = fullTrace ? null : findRenderedRequestAction(requestId);
  if (action) {
    action.scrollIntoView({ block: "center", behavior: "smooth" });
  } else if (fullTrace) {
    traceList?.scrollIntoView({ block: "start", behavior: "smooth" });
  } else {
    scrollChatToBottom({ force: true, behavior: "smooth" });
  }
}

function followLiveTaskRequest(requestId, streamUrl = "") {
  const id = String(requestId || "").trim();
  if (!id) return;
  const url = String(streamUrl || streamUrlForRequest(id)).trim();
  state.requestId = id;
  if (requestIdLabel) {
    requestIdLabel.textContent = id;
  }
  setTasksDrawerOpen(false);
  setNotificationsDrawerOpen(false);
  setConversationCollapsed(false);
  setRunStatus("following task", "running");
  setComposerPreparing(false);
  addThinkingIndicator();
  startTraceStream(id, url);
}

function notificationCard(notification, { toast = false } = {}) {
  const card = document.createElement("article");
  card.className = `notification-card${toast ? " notification-toast" : ""}`;
  card.dataset.level = String(notification?.level || "info");
  const header = document.createElement("div");
  header.className = "notification-card-header";
  const titleWrap = document.createElement("div");
  titleWrap.className = "notification-card-title";
  const titleLine = document.createElement("div");
  titleLine.className = "notification-card-title-line";
  const title = document.createElement("strong");
  title.textContent = String(notification?.title || "Notification");
  const duplicateCount = document.createElement("span");
  duplicateCount.className = "notification-duplicate-count";
  duplicateCount.hidden = true;
  titleLine.append(title, duplicateCount);
  const meta = document.createElement("span");
  const status = String(notification?.status || "unread");
  meta.textContent = `${String(notification?.level || "info")} · ${status} · ${formatNotificationTime(notification?.created_at)}`;
  titleWrap.append(titleLine, meta);
  header.append(titleWrap);
  const messageMarkdown = String(notification?.message || "").trim();
  const rawMarkdownSections = toast ? [] : notificationRawMarkdownSections(notification);
  const chips = notificationDetailChips(notification);
  let details = null;
  if (chips.length) {
    details = document.createElement("div");
    details.className = "notification-card-details";
    chips.forEach((chipText) => {
      const chip = document.createElement("span");
      chip.textContent = chipText;
      details.append(chip);
    });
  }
  const actions = document.createElement("div");
  actions.className = "notification-card-actions";
  const id = notificationKey(notification);
  const requestId = notificationRequestId(notification);
  const metadata = notification?.metadata && typeof notification.metadata === "object"
    ? notification.metadata
    : {};
  const followLive = metadata.follow_live === true || metadata.task_follow_live === true;
  if (requestId) {
    if (followLive) {
      const follow = document.createElement("button");
      follow.type = "button";
      follow.className = "notification-open-request notification-follow-live";
      follow.textContent = "Follow live";
      follow.addEventListener("click", () => {
        followLiveTaskRequest(requestId, notificationStreamUrl(notification));
        if (card?.classList?.contains("notification-toast")) {
          removeNotificationCard(card);
        }
      });
      actions.append(follow);
    }
    const openFinal = document.createElement("button");
    openFinal.type = "button";
    openFinal.className = "notification-open-request";
    openFinal.textContent = "Final answer";
    openFinal.addEventListener("click", () => {
      void openNotificationRequest(notification, card, { view: "final" });
    });
    const openTrace = document.createElement("button");
    openTrace.type = "button";
    openTrace.className = "notification-open-request notification-open-trace";
    openTrace.textContent = "Full trace";
    openTrace.addEventListener("click", () => {
      void openNotificationRequest(notification, card, { view: "trace" });
    });
    actions.append(openFinal, openTrace);
  }
  if (id && status === "unread") {
    const read = document.createElement("button");
    read.type = "button";
    read.textContent = "Read";
    read.addEventListener("click", () => {
      void updateNotificationStatus(id, "read");
      removeNotificationCard(card);
    });
    actions.append(read);
  }
  const dismiss = document.createElement("button");
  dismiss.type = "button";
  dismiss.textContent = "Dismiss";
  dismiss.addEventListener("click", () => {
    if (id) {
      void updateNotificationStatus(id, "dismissed");
    }
    removeNotificationCard(card);
  });
  actions.append(dismiss);
  card.append(header);
  const messageDedupKey = notificationMarkdownDedupKey(messageMarkdown);
  const messageDuplicatedByRaw = Boolean(
    messageDedupKey
      && rawMarkdownSections.some((section) => section.raw && section.dedupKey === messageDedupKey),
  );
  if (!messageDuplicatedByRaw) {
    appendNotificationMarkdownSection(
      card,
      rawMarkdownSections.length ? "Message" : "",
      messageMarkdown,
    );
  }
  rawMarkdownSections.forEach((section) => {
    appendNotificationMarkdownSection(card, section.label, section.markdown, { raw: true });
  });
  if (details) {
    card.append(details);
  }
  card.append(actions);
  updateNotificationDuplicateCount(card, Number(notification?.duplicate_count || 1));
  return card;
}

function renderNotificationBadge() {
  const unreadCount = Number(state.notificationCounts?.unread);
  const unread = Number.isFinite(unreadCount) ? unreadCount : 0;
  const unreadText = unread > 99 ? "99+" : String(unread);
  const hasUnread = unread > 0;
  if (notificationsToggle) {
    notificationsToggle.hidden = false;
    notificationsToggle.style.display = "";
  }
  if (notificationsBadge) {
    notificationsBadge.hidden = !hasUnread;
    notificationsBadge.style.display = hasUnread ? "" : "none";
    notificationsBadge.textContent = unreadText;
  }
  if (notificationsTopSummary) {
    notificationsTopSummary.hidden = !hasUnread;
    notificationsTopSummary.style.display = hasUnread ? "" : "none";
    notificationsTopSummary.classList.toggle("notifications-top-summary--alert", hasUnread);
    notificationsTopSummary.setAttribute("aria-label", `Pending notifications: ${unreadText}`);
  }
  if (notificationsTopSummaryCount) {
    notificationsTopSummaryCount.textContent = unreadText;
  }
  if (notificationsImmersiveSummary) {
    notificationsImmersiveSummary.hidden = !hasUnread;
    notificationsImmersiveSummary.style.display = hasUnread ? "" : "none";
    notificationsImmersiveSummary.classList.toggle("notifications-top-summary--alert", hasUnread);
    notificationsImmersiveSummary.setAttribute("aria-label", `Pending notifications: ${unreadText}`);
  }
  if (notificationsImmersiveSummaryCount) {
    notificationsImmersiveSummaryCount.textContent = unreadText;
  }
}

function renderNotifications() {
  renderNotificationBadge();
  if (!notificationsList) return;
  notificationsList.replaceChildren();
  if (!state.notifications.length) {
    notificationsList.append(empty("No notifications."));
    return;
  }
  state.notifications.forEach((notification) => {
    notificationsList.append(notificationCard(notification));
  });
}

function showNotification(notification, { persistMs = null, localOnly = false } = {}) {
  if (!notificationOverlay || !notification) return;
  if (!localOnly && shouldSuppressLiveTaskNotificationDelivery(notification)) {
    markSuppressedLiveTaskNotificationRead(notification);
    return null;
  }
  const dedupKey = notificationToastDedupKey(notification);
  const card = notificationCard(notification, { toast: true });
  card.dataset.dedupKey = dedupKey;
  const level = String(notification.level || "info");
  const sourceType = String(notification.source_type || "");
  const actionType = String(notification.metadata?.action_type || "");
  const sticky = ["warning", "error"].includes(level)
    || sourceType === "scheduled_event_notification"
    || sourceType === "scheduled_event_auto_approved"
    || actionType === "notification";
  const timeout = Number(persistMs ?? (sticky ? 0 : 6500));
  const existing = state.notificationToastDedup.get(dedupKey);
  if (existing?.card?.isConnected) {
    const count = Math.max(1, Number(existing.count || 1)) + 1;
    existing.count = count;
    notificationOverlay.prepend(existing.card);
    updateNotificationDuplicateCount(existing.card, count);
    if (existing.timeoutId) {
      window.clearTimeout(existing.timeoutId);
      existing.timeoutId = null;
    }
    if (timeout > 0) {
      existing.timeoutId = window.setTimeout(() => {
        removeNotificationCard(existing.card);
      }, timeout);
    }
    return existing.card;
  }
  state.notificationToastDedup.set(dedupKey, {
    card,
    count: 1,
    timeoutId: null,
  });
  notificationOverlay.prepend(card);
  if (!localOnly) {
    showBrowserNotification(notification);
    playNotificationSound(notification);
  }
  if (timeout > 0) {
    const record = state.notificationToastDedup.get(dedupKey);
    record.timeoutId = window.setTimeout(() => {
      removeNotificationCard(card);
    }, timeout);
  }
  return card;
}

function resolveUiActionField(field) {
  if (!field) return null;
  if (typeof field === "string") {
    return document.querySelector(field);
  }
  return typeof field.focus === "function" ? field : null;
}

function markUiActionFieldInvalid(field) {
  const target = resolveUiActionField(field);
  if (!target) return;
  target.setAttribute("aria-invalid", "true");
  const clearInvalid = () => target.removeAttribute("aria-invalid");
  target.addEventListener("input", clearInvalid, { once: true });
  target.addEventListener("change", clearInvalid, { once: true });
  target.focus({ preventScroll: false });
}

function showUiActionError({ title = "Action failed", message = "", fix = "", field = null } = {}, options = {}) {
  const cleanTitle = String(title || "Action failed").trim() || "Action failed";
  const cleanMessage = String(message || "The action could not be completed.").trim();
  const cleanFix = String(fix || "").trim();
  markUiActionFieldInvalid(field);
  return showNotification({
    level: "error",
    title: cleanTitle,
    message: cleanFix ? `${cleanMessage} Fix: ${cleanFix}` : cleanMessage,
    source_type: "ui_action_error",
    status: "local",
  }, { persistMs: options.persistMs ?? 9000, localOnly: true });
}

function notificationAudioApi() {
  return window.AudioContext || window.webkitAudioContext;
}

function unlockNotificationAudio() {
  state.notificationAudioUnlocked = true;
  const AudioContextCtor = notificationAudioApi();
  if (!AudioContextCtor || state.notificationAudioContext) {
    return;
  }
  try {
    state.notificationAudioContext = new AudioContextCtor();
    if (state.notificationAudioContext.state === "suspended") {
      state.notificationAudioContext.resume().catch(() => {});
    }
  } catch {
    state.notificationAudioContext = null;
  }
}

function notificationSoundPattern(notification) {
  const variant = normalizeNotificationSoundVariant(state.agentSettings?.notification_sound_variant);
  const level = String(notification?.level || "info").toLowerCase();
  if (variant === "alert" || level === "error") {
    return [
      { frequency: 392, offset: 0, duration: 0.12 },
      { frequency: 294, offset: 0.14, duration: 0.18 },
    ];
  }
  if (variant === "ping" || level === "warning") {
    return [{ frequency: 520, offset: 0, duration: 0.16 }];
  }
  if (variant === "soft") {
    return [
      { frequency: 660, offset: 0, duration: 0.09 },
      { frequency: 880, offset: 0.1, duration: 0.11 },
    ];
  }
  return [
    { frequency: 660, offset: 0, duration: 0.09 },
    { frequency: 990, offset: 0.1, duration: 0.13 },
  ];
}

function playNotificationSound(notification) {
  if (!state.agentSettings?.notification_sound_enabled) {
    return;
  }
  if (!state.notificationAudioUnlocked) {
    return;
  }
  const AudioContextCtor = notificationAudioApi();
  if (!AudioContextCtor) {
    return;
  }
  try {
    const context = state.notificationAudioContext || new AudioContextCtor();
    state.notificationAudioContext = context;
    const play = () => {
      const volume = normalizeNotificationSoundVolume(state.agentSettings?.notification_sound_volume);
      for (const note of notificationSoundPattern(notification)) {
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        const start = context.currentTime + Number(note.offset || 0);
        const stop = start + Number(note.duration || 0.14);
        oscillator.type = "sine";
        oscillator.frequency.value = Number(note.frequency || 660);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(Math.max(0.001, volume * 0.09), start + 0.015);
        gain.gain.exponentialRampToValueAtTime(0.0001, stop);
        oscillator.connect(gain);
        gain.connect(context.destination);
        oscillator.start(start);
        oscillator.stop(stop + 0.01);
      }
    };
    if (context.state === "suspended") {
      context.resume().then(play).catch(() => {});
    } else {
      play();
    }
  } catch {
    // Visual notifications remain authoritative when browser audio is unavailable.
  }
}

function upsertNotifications(notifications, { showUnread = false } = {}) {
  const incoming = Array.isArray(notifications) ? notifications : [];
  const byId = new Map(state.notifications.map((item) => [notificationKey(item), item]));
  let suppressedUnreadCount = 0;
  incoming.forEach((notification) => {
    const id = notificationKey(notification);
    if (id) {
      byId.set(id, notification);
    }
    if (
      showUnread &&
      id &&
      String(notification?.status || "unread") === "unread" &&
      !state.shownNotificationIds.has(id)
    ) {
      if (shouldSuppressLiveTaskNotificationDelivery(notification)) {
        state.shownNotificationIds.add(id);
        if (markSuppressedLiveTaskNotificationRead(notification)) {
          suppressedUnreadCount += 1;
        }
        return;
      }
      state.shownNotificationIds.add(id);
      showNotification(notification);
    }
  });
  state.notifications = Array.from(byId.values()).sort((left, right) => {
    return String(right?.created_at || "").localeCompare(String(left?.created_at || ""));
  });
  if (suppressedUnreadCount > 0) {
    const unread = Number(state.notificationCounts?.unread || 0);
    state.notificationCounts = {
      ...state.notificationCounts,
      unread: Math.max(0, unread - suppressedUnreadCount),
    };
  }
  renderNotifications();
}

async function loadNotifications({ showUnread = true } = {}) {
  try {
    const response = await fetch("/api/agent/notifications?limit=50", { cache: "no-store" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.notificationCounts = payload.counts || {};
    upsertNotifications(payload.notifications || [], { showUnread });
  } catch (error) {
    showNotification({
      level: "error",
      title: "Notifications unavailable",
      message: shortStatusError(error),
    });
  }
}

async function updateNotificationStatus(notificationId, status) {
  const id = String(notificationId || "").trim();
  if (!id) return;
  try {
    const response = await fetch(`/api/agent/notifications/${encodeURIComponent(id)}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status }),
    });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.notificationCounts = payload.counts || state.notificationCounts;
    const updated = payload.notification;
    if (updated) {
      const index = state.notifications.findIndex((item) => notificationKey(item) === id);
      if (String(updated.status || "") === "dismissed") {
        state.notifications = state.notifications.filter((item) => notificationKey(item) !== id);
      } else if (index >= 0) {
        state.notifications[index] = updated;
      }
    }
    renderNotifications();
  } catch (error) {
    showNotification({
      level: "error",
      title: "Notification update failed",
      message: shortStatusError(error),
    });
  }
}

async function markAllNotificationsRead() {
  try {
    const response = await fetch("/api/agent/notifications/mark-all-read", { method: "POST" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.notificationCounts = payload.counts || state.notificationCounts;
    state.notifications = state.notifications.map((item) => ({ ...item, status: "read" }));
    renderNotifications();
  } catch (error) {
    showNotification({
      level: "error",
      title: "Notification update failed",
      message: shortStatusError(error),
    });
  }
}

function taskStatusLabel(status) {
  return String(status || "queued").replace(/_/g, " ");
}

function taskTone(status) {
  const value = String(status || "");
  if (value === "completed") return "success";
  if (["failed", "cancelled"].includes(value)) return "error";
  if (["awaiting_confirmation", "awaiting_clarification", "interrupted"].includes(value)) return "warning";
  if (value === "running") return "success";
  return "info";
}

function taskSourceLabel(task) {
  const source = String(task?.source || "");
  if (source === "chat") return "chat";
  if (source !== "scheduled_event") return "task";
  const sourceEvent = task?.source_event && typeof task.source_event === "object" ? task.source_event : {};
  const status = String(sourceEvent.status || "").trim();
  if (status === "deleted") return "event deleted";
  if (sourceEvent.exists === false || status === "missing") return "event missing";
  return "event";
}

function renderTaskBadge() {
  const active = Number(state.taskCounts?.running || 0)
    + Number(state.taskCounts?.awaiting_confirmation || 0)
    + Number(state.taskCounts?.awaiting_clarification || 0)
    + Number(state.taskCounts?.queued || 0);
  if (tasksBadge) {
    tasksBadge.hidden = active <= 0;
    tasksBadge.textContent = active > 99 ? "99+" : String(active);
  }
}

function taskById(taskId) {
  const id = String(taskId || "").trim();
  return state.tasks.find((task) => String(task?.task_id || "") === id) || null;
}

function taskDisplayName(task) {
  return String(task?.title || task?.prompt || "Untitled task").trim() || "Untitled task";
}

function taskCurrentRequestId(task) {
  return String(task?.current_request_id || task?.latest_request_id || "").trim();
}

function taskIdValue(task) {
  return String(task?.task_id || "").trim();
}

function taskStreamUrl(task) {
  const requestId = taskCurrentRequestId(task);
  return requestId ? streamUrlForRequest(requestId) : "";
}

function taskStreamUrlForRequest(task, requestId) {
  return taskStreamUrl(task) || streamUrlForRequest(requestId);
}

function startDurableTaskTraceStream(task, requestId, payload, options = {}) {
  const safeRequestId = String(requestId || "").trim();
  if (!safeRequestId) {
    return false;
  }
  startTraceStream(safeRequestId, taskStreamUrlForRequest(task, safeRequestId), {
    afterId: lastTraceEventId(payload),
    resetActivity: false,
    ...options,
  });
  return true;
}

function taskAutoApproveExpected(task) {
  const context = task?.context && typeof task.context === "object" ? task.context : {};
  return context.auto_approve_commands === true;
}

function taskMatchesRequestId(task, requestId) {
  const id = String(requestId || "").trim();
  if (!task || !id) {
    return false;
  }
  return (
    String(task?.current_request_id || "").trim() === id ||
    String(task?.latest_request_id || "").trim() === id
  );
}

function taskForRequestId(requestId) {
  const id = String(requestId || "").trim();
  if (!id) {
    return null;
  }
  return state.tasks.find((task) => taskMatchesRequestId(task, id)) || null;
}

function attachedTaskAutoApproveExpectedForRequest(requestId) {
  const id = String(requestId || "").trim();
  const task = taskForRequestId(id);
  if (task) {
    return taskAutoApproveExpected(task);
  }
  const attachedTask = taskById(state.attachedTaskId);
  if (
    attachedTask &&
    id &&
    (taskMatchesRequestId(attachedTask, id) || String(state.requestId || "").trim() === id)
  ) {
    return taskAutoApproveExpected(attachedTask);
  }
  return false;
}

function taskTraceLoadOptions(task, requestId, extra = {}) {
  const taskAutoApprove = taskAutoApproveExpected(task) || attachedTaskAutoApproveExpectedForRequest(requestId);
  return {
    ...extra,
    suppressAutoApprove: taskAutoApprove,
    retireTaskAutoApproval: taskAutoApprove,
  };
}

function scheduleDurableTaskStreamSync(requestId = "", { immediate = false } = {}) {
  const id = String(requestId || "").trim();
  const hasQueuedTasks = Number(state.taskCounts?.queued || 0) > 0;
  const hasAttachedTask = Boolean(String(state.attachedTaskId || "").trim());
  const hasMatchingTask = Boolean(id && taskForRequestId(id));
  if (!hasQueuedTasks && !hasAttachedTask && !hasMatchingTask) {
    return false;
  }
  const delays = immediate ? [0, 250, 1000, 2500] : [250, 1000, 2500];
  for (const delay of delays) {
    window.setTimeout(() => {
      if (state.composerPreparing) {
        return;
      }
      void loadTasks();
    }, delay);
  }
  return true;
}

function taskStatusIsTerminal(status) {
  return ["completed", "failed", "cancelled"].includes(String(status || ""));
}

function rememberTaskRecord(task) {
  const taskId = taskIdValue(task);
  if (!taskId) {
    return null;
  }
  const existingIndex = state.tasks.findIndex((item) => taskIdValue(item) === taskId);
  if (existingIndex >= 0) {
    state.tasks[existingIndex] = task;
  } else {
    state.tasks.unshift(task);
  }
  if (state.selectedTask && taskIdValue(state.selectedTask) === taskId) {
    state.selectedTask = task;
  }
  return task;
}

function attachedTaskForActiveRun() {
  const attachedTaskId = String(state.attachedTaskId || "").trim();
  if (!attachedTaskId) {
    return null;
  }
  if (state.selectedTask && taskIdValue(state.selectedTask) === attachedTaskId) {
    return state.selectedTask;
  }
  return taskById(attachedTaskId);
}

function taskActiveRequestIdForStop(task) {
  if (!task || taskStatusIsTerminal(task?.status)) {
    return "";
  }
  return String(task?.current_request_id || "").trim() || taskCurrentRequestId(task);
}

function visibleRequestIdForStop() {
  const label = String(requestIdLabel?.textContent || "").trim();
  if (!label || label === "Idle") {
    return "";
  }
  return label;
}

async function activeRunStopRequestId() {
  const visibleRequestId = String(state.requestId || "").trim() || visibleRequestIdForStop();
  if (visibleRequestId) {
    return visibleRequestId;
  }
  const attachedTaskId = String(state.attachedTaskId || "").trim();
  if (attachedTaskId) {
    try {
      const response = await fetch(`/api/agent/tasks/${encodeURIComponent(attachedTaskId)}`, {
        cache: "no-store",
      });
      if (response.ok) {
        const payload = await response.json();
        const requestId = taskActiveRequestIdForStop(rememberTaskRecord(payload?.task));
        if (requestId) {
          return requestId;
        }
      }
    } catch {
      // Fall back to the task snapshot already held by the page.
    }
    const localRequestId = taskActiveRequestIdForStop(attachedTaskForActiveRun());
    if (localRequestId) {
      return localRequestId;
    }
  }
  return "";
}

async function fetchTaskTracePayload(requestId) {
  try {
    const response = await fetch(`/api/agent/trace/${encodeURIComponent(requestId)}`, { cache: "no-store" });
    if (!response.ok) {
      return null;
    }
    return response.json();
  } catch {
    return null;
  }
}

async function fetchDurableTaskRecord(taskId) {
  const id = String(taskId || "").trim();
  if (!id) {
    return null;
  }
  try {
    const response = await fetch(`/api/agent/tasks/${encodeURIComponent(id)}`, {
      cache: "no-store",
    });
    if (!response.ok) {
      return null;
    }
    const payload = await response.json();
    return rememberTaskRecord(payload?.task);
  } catch {
    return null;
  }
}

function durableTaskIdFromTracePayload(payload) {
  const events = Array.isArray(payload?.events) ? payload.events : [];
  for (const event of events) {
    const eventType = String(event?.event_type || "");
    if (!eventType.startsWith("durable_task.")) {
      continue;
    }
    const detail = event?.detail && typeof event.detail === "object" ? event.detail : {};
    const taskId = String(detail.task_id || detail.durable_task_id || "").trim();
    if (taskId) {
      return taskId;
    }
  }
  return "";
}

function tracePayloadParentRequestId(payload) {
  const directParentId = String(payload?.parent_request_id || payload?.parentRequestId || "").trim();
  if (directParentId) {
    return directParentId;
  }
  const metadata = payload?.metadata && typeof payload.metadata === "object" ? payload.metadata : {};
  const metadataParentId = String(metadata.parent_request_id || metadata.parentRequestId || "").trim();
  if (metadataParentId) {
    return metadataParentId;
  }
  for (const event of Array.isArray(payload?.events) ? payload.events : []) {
    const detail = eventDetail(event);
    const parentRequestId = String(detail.parent_request_id || detail.parentRequestId || "").trim();
    if (parentRequestId) {
      return parentRequestId;
    }
  }
  return "";
}

function taskAttemptParentRequestId(task, requestId) {
  const taskId = taskIdValue(task);
  const safeRequestId = String(requestId || "").trim();
  if (!taskId || !safeRequestId) {
    return "";
  }
  const attempts = Array.isArray(state.taskAttempts?.[taskId]) ? state.taskAttempts[taskId] : [];
  const match = attempts.find((attempt) => String(attempt?.request_id || "").trim() === safeRequestId);
  return String(match?.parent_request_id || "").trim();
}

function tracePayloadHasAutoApprovalEvent(payload) {
  return (Array.isArray(payload?.events) ? payload.events : []).some((event) => isAutoApprovedTraceEvent(event));
}

function appendAutoApprovedConversationMessagesFromTracePayload(payload) {
  let appended = false;
  for (const event of Array.isArray(payload?.events) ? payload.events : []) {
    if (appendAutoApprovedConversationMessage(event)) {
      appended = true;
    }
  }
  return appended;
}

async function renderParentTraceBeforeContinuation(task, requestId, payload) {
  const safeRequestId = String(requestId || "").trim();
  const parentRequestId = (
    taskAttemptParentRequestId(task, safeRequestId) ||
    tracePayloadParentRequestId(payload)
  );
  if (!parentRequestId || parentRequestId === safeRequestId) {
    return false;
  }
  const autoApproved = taskAutoApproveExpected(task) || tracePayloadHasAutoApprovalEvent(payload);
  await loadFinalTrace(parentRequestId, {
    renderTraceEvents: false,
    retireTaskAutoApproval: true,
    suppressAutoApprove: true,
    suppressTaskContinuationFollow: true,
    confirmationContinuationMessage: autoApproved
      ? "Auto-Approve Commands is on. Continuing with the saved plan..."
      : "The approved run is continuing below.",
  });
  return true;
}

async function restoreDurableTaskContinuationFromTracePayload(parentRequestId, payload, options = {}) {
  const taskId = durableTaskIdFromTracePayload(payload);
  if (!taskId) {
    return false;
  }
  const task = await fetchDurableTaskRecord(taskId);
  const requestId = taskCurrentRequestId(task);
  if (!task || !requestId || requestId === String(parentRequestId || "").trim()) {
    return false;
  }
  const continuedPayload = await fetchTaskTracePayload(requestId);
  if (!continuedPayload) {
    return false;
  }
  clearActiveRequestSnapshot();
  return attachDurableTaskRequest(task, requestId, continuedPayload, {
    ...options,
    parentRequestId: String(parentRequestId || "").trim(),
  });
}

function durableTaskForApprovalContinuation(parentRequestId, childRequestId = "") {
  const parentId = String(parentRequestId || "").trim();
  const childId = String(childRequestId || "").trim();
  const attachedTask = attachedTaskForActiveRun();
  if (attachedTask && state.attachedTaskId) {
    return attachedTask;
  }
  return taskForRequestId(childId) || taskForRequestId(parentId);
}

async function attachDurableApprovalContinuation(parentRequestId, payload, options = {}) {
  const childRequestId = String(payload?.request_id || "").trim();
  if (!childRequestId || !state.attachedTaskId) {
    return false;
  }
  state.durableApprovalAttachingRequestIds.add(childRequestId);
  try {
    let task = durableTaskForApprovalContinuation(parentRequestId, childRequestId);
    if (!task && state.attachedTaskId) {
      task = await fetchDurableTaskRecord(state.attachedTaskId);
    }
    if (!task) {
      return false;
    }
    task = rememberTaskRecord({
      ...task,
      status: "running",
      current_request_id: childRequestId,
      latest_request_id: childRequestId,
      conversation_id: payload?.conversation_id || task?.conversation_id || state.conversationId || "",
    });
    const tracePayload = await fetchTaskTracePayload(childRequestId) || {
      request_id: childRequestId,
      parent_request_id: String(parentRequestId || "").trim(),
      prompt: task?.prompt || "",
      conversation_id: payload?.conversation_id || task?.conversation_id || state.conversationId || "",
      status: "running",
      events: [],
    };
    if (options.autoApproved === true) {
      appendAutoApprovedConversationMessage({
        event_type: "confirmation.auto_approved",
        request_id: childRequestId,
        detail: { parent_request_id: parentRequestId },
      });
    }
    setRunStatus("following task", "running");
    return attachDurableTaskRequest(task, childRequestId, tracePayload, {
      preserveConversation: true,
      parentRequestId,
    });
  } finally {
    state.durableApprovalAttachingRequestIds.delete(childRequestId);
  }
}

function durableTaskAttachShouldPreserveConversation(task, requestId, payload, parentRequestId = "") {
  const safeRequestId = String(requestId || "").trim();
  const parentId = String(
    parentRequestId ||
    tracePayloadParentRequestId(payload) ||
    taskAttemptParentRequestId(task, safeRequestId) ||
    "",
  ).trim();
  if (!parentId || parentId === safeRequestId) {
    return false;
  }
  const activeId = String(state.requestId || "").trim();
  if (activeId && parentId === activeId) {
    return true;
  }
  if (taskIdValue(task) && taskIdValue(task) === String(state.attachedTaskId || "").trim()) {
    return true;
  }
  return state.finalTraceRendered.has(parentId) || state.confirmationRendered.has(parentId);
}

function notifyQueuedTaskForAutoAttach(task, { source = "task" } = {}) {
  const taskId = String(task?.task_id || "").trim();
  if (!taskId || String(task?.status || "") !== "queued") {
    return false;
  }
  const title = taskDisplayName(task);
  const waiting = String(task?.blocker_reason || "").trim();
  const sourceLabel = source === "chat" ? "from chat" : "from the task pane";
  const message = waiting
    ? `${title} is queued ${sourceLabel}. ${waiting} It will run in the background and attach here when it starts.`
    : `${title} is queued ${sourceLabel}. It will run in the background and attach here when it starts.`;
  showNotification({
    level: "info",
    title: "Task queued",
    message,
    source_type: "durable_task_local",
    source_id: `queued:${taskId}`,
    metadata: {
      task_id: taskId,
      task_status: "queued",
    },
  }, { persistMs: 9000 });
  return true;
}

function notifyTaskStartedForAutoAttach(task, requestId) {
  const taskId = String(task?.task_id || "").trim();
  const streamUrl = taskStreamUrl(task) || streamUrlForRequest(requestId);
  showNotification({
    level: "info",
    title: "Task started",
    message: `${taskDisplayName(task)} is running now. You can follow the live trace or open the saved result later.`,
    source_type: "durable_task_local",
    source_id: `started:${taskId || requestId}:${requestId}`,
    request_id: requestId,
    metadata: {
      task_id: taskId,
      task_status: String(task?.status || "running"),
      request_id: requestId,
      stream_url: streamUrl,
      follow_live: true,
    },
  }, { persistMs: 10000 });
}

function taskIsAutoAttachable(task) {
  return ["running", "awaiting_confirmation", "awaiting_clarification"].includes(String(task?.status || ""));
}

function canAutoAttachTaskRequest(requestId) {
  const id = String(requestId || "").trim();
  if (!id) return false;
  const activeId = String(state.requestId || "").trim();
  if (state.source) {
    return false;
  }
  const activeStatus = String(runStatus?.textContent || "").trim().toLowerCase();
  const waitingSnapshot = readActiveRequestSnapshot();
  const replaceableWaitingRequest = Boolean(
    activeId &&
    activeId !== id &&
    [
      "approval needed",
      "input needed",
      "restoring approval",
      "following task",
    ].includes(activeStatus)
  );
  const replaceableWaitingSnapshot = Boolean(
    waitingSnapshot?.request_id &&
    waitingSnapshot.request_id !== id &&
    String(waitingSnapshot.status || "") === "waiting"
  );
  if (composerHasActiveRun() && !replaceableWaitingRequest && !replaceableWaitingSnapshot) {
    return false;
  }
  if (state.autoAttachedTaskRequestIds.has(id) && activeId === id) {
    return false;
  }
  return true;
}

async function attachDurableTaskRequest(task, requestId, payload, { notify = false, preserveConversation = false, parentRequestId = "" } = {}) {
  const safeRequestId = String(requestId || "").trim();
  if (!task || !safeRequestId || !payload) {
    return false;
  }
  const effectiveParentRequestId = String(
    parentRequestId ||
    tracePayloadParentRequestId(payload) ||
    taskAttemptParentRequestId(task, safeRequestId) ||
    "",
  ).trim();
  if (effectiveParentRequestId && !tracePayloadParentRequestId(payload)) {
    payload = {
      ...payload,
      parent_request_id: effectiveParentRequestId,
    };
  }
  const shouldPreserveConversation =
    preserveConversation ||
    durableTaskAttachShouldPreserveConversation(task, safeRequestId, payload, effectiveParentRequestId);
  if (!shouldPreserveConversation) {
    resetView({ clearChat: true, resetConversation: false });
  }
  state.attachedTaskId = taskIdValue(task);
  state.autoAttachedTaskRequestIds.add(safeRequestId);
  state.requestId = safeRequestId;
  state.conversationId = String(payload?.conversation_id || task?.conversation_id || state.conversationId || "").trim() || state.conversationId;
  if (requestIdLabel) {
    requestIdLabel.textContent = safeRequestId;
  }
  setTasksDrawerOpen(false);
  setNotificationsDrawerOpen(false);
  setConversationCollapsed(false);
  if (payload?.prompt && !shouldPreserveConversation) {
    addMessage("user", task?.source === "chat" ? "Queued request" : "Task", payload.prompt);
  }
  const continuationReplay = Boolean(tracePayloadParentRequestId(payload));
  await renderParentTraceBeforeContinuation(task, safeRequestId, payload);
  const taskStatus = String(task?.status || "").trim();
  const traceStatus = String(payload?.status || "").trim();
  if (
    taskStatus === "running" &&
    ["running", "pending", ""].includes(traceStatus) &&
    !tracePayloadInputNeeded(payload)
  ) {
    addThinkingIndicator();
    setRunStatus("following task", "running");
    setStopEnabled(true);
    let loadedTracePayload = payload;
    await loadFinalTrace(
      safeRequestId,
      taskTraceLoadOptions(task, safeRequestId, {
        renderTraceEvents: true,
        prioritizeAutoApproved: continuationReplay || tracePayloadHasAutoApprovalEvent(payload),
        onTracePayload: (tracePayload) => {
          loadedTracePayload = tracePayload || payload;
        },
      }),
    );
    if (!state.streamingAnswerNode) {
      addThinkingIndicator();
    }
    setRunStatus("following task", "running");
    startDurableTaskTraceStream(task, safeRequestId, loadedTracePayload);
  } else {
    setStopEnabled(!taskStatusIsTerminal(taskStatus));
    await loadFinalTrace(
      safeRequestId,
      taskTraceLoadOptions(task, safeRequestId, {
        renderTraceEvents: true,
        prioritizeAutoApproved: continuationReplay || tracePayloadHasAutoApprovalEvent(payload),
      }),
    );
    if (
      taskAutoApproveExpected(task) &&
      (taskStatus === "awaiting_confirmation" || isConfirmationRequired(payload))
    ) {
      retirePendingConfirmationActions("Task auto-approval is continuing this run in the background.");
      setRunStatus("following task", "running");
    }
  }
  if (notify) {
    notifyTaskStartedForAutoAttach(task, safeRequestId);
  }
  return true;
}

async function syncAttachedDurableTaskRequest(tasks) {
  const attachedTaskId = String(state.attachedTaskId || "").trim();
  if (!attachedTaskId || !Array.isArray(tasks) || state.composerPreparing) {
    return false;
  }
  const task = tasks.find((item) => taskIdValue(item) === attachedTaskId);
  const requestId = taskCurrentRequestId(task);
  if (!task || !requestId) {
    return false;
  }
  const taskStatus = String(task?.status || "").trim();
  const activeRequestId = String(state.requestId || "").trim();
  if (
    activeRequestId &&
    state.durableApprovalContinuingParentRequestIds.has(activeRequestId) &&
    taskIdValue(task) === String(state.attachedTaskId || "").trim()
  ) {
    return false;
  }
  if (state.durableApprovalAttachingRequestIds.has(requestId)) {
    return false;
  }
  if (requestId === activeRequestId) {
    if (taskStatusIsTerminal(taskStatus) && !state.terminalTraceRendered.has(requestId)) {
      if (state.source) {
        state.source.close();
        state.source = null;
      }
      setStopEnabled(false);
      await loadFinalTrace(
        requestId,
        taskTraceLoadOptions(task, requestId, {
          renderTraceEvents: true,
        }),
      );
      return true;
    }
    return false;
  }
  if (!taskIsAutoAttachable(task) && !taskStatusIsTerminal(taskStatus)) {
    return false;
  }
  const payload = await fetchTaskTracePayload(requestId);
  if (!payload) {
    return false;
  }
  return attachDurableTaskRequest(task, requestId, payload, { preserveConversation: true });
}

async function autoAttachOpenDurableTask(tasks) {
  if (!Array.isArray(tasks) || state.composerPreparing) {
    return false;
  }
  const task = tasks.find((item) => taskIsAutoAttachable(item) && taskCurrentRequestId(item));
  const requestId = taskCurrentRequestId(task);
  if (!task || !canAutoAttachTaskRequest(requestId)) {
    return false;
  }
  const payload = await fetchTaskTracePayload(requestId);
  if (!payload) {
    return false;
  }
  if (!canAutoAttachTaskRequest(requestId)) {
    return false;
  }
  return attachDurableTaskRequest(task, requestId, payload, { notify: true });
}

function taskCanStart(task) {
  return ["queued", "interrupted"].includes(String(task?.status || ""));
}

function taskCanRetry(task) {
  return Boolean(task) && !["queued", "running", "awaiting_confirmation", "awaiting_clarification"].includes(String(task?.status || ""));
}

function taskCanCancel(task) {
  return ["queued", "running", "awaiting_confirmation", "awaiting_clarification"].includes(String(task?.status || ""));
}

function renderTaskGatewayOptions() {
  if (!taskGateway) return;
  const selected = taskGateway.value || state.selectedGatewayId || "";
  taskGateway.replaceChildren();
  const fallback = document.createElement("option");
  fallback.value = "";
  fallback.textContent = "Default";
  taskGateway.append(fallback);
  (Array.isArray(state.gateways) ? state.gateways : [])
    .filter((gateway) => gateway.enabled !== false)
    .forEach((gateway) => {
      const option = document.createElement("option");
      option.value = gateway.gateway_id || "";
      option.textContent = gatewayDisplayName(gateway);
      taskGateway.append(option);
    });
  taskGateway.value = Array.from(taskGateway.options).some((option) => option.value === selected)
    ? selected
    : "";
}

function syncTaskSelectionClasses() {
  if (!tasksList) return;
  tasksList.querySelectorAll(".task-row").forEach((row) => {
    const selected = String(row.dataset.taskId || "") === String(state.selectedTaskId || "");
    row.classList.toggle("selected", selected);
    if (row instanceof HTMLDetailsElement) {
      if (state.taskDetailsCollapsed) {
        row.open = false;
      } else if (state.taskDetailsExpanded || selected) {
        row.open = true;
      }
    }
  });
}

function selectTask(taskOrId, { load = true } = {}) {
  const task = typeof taskOrId === "string" ? taskById(taskOrId) : taskOrId;
  const taskId = String(task?.task_id || taskOrId || "").trim();
  state.selectedTaskId = taskId;
  state.selectedTask = task || taskById(taskId);
  syncTaskSelectionClasses();
  updateTaskControls();
  renderTaskDetails();
  if (load && taskId) {
    void loadSelectedTaskDetails(taskId);
  }
}

function clearTaskEditor() {
  if (taskTitle) taskTitle.value = "";
  if (taskPrompt) {
    taskPrompt.value = "";
    resetTextareaHeight(taskPrompt);
  }
  if (taskAgentMode) taskAgentMode.value = currentAgentMode() || "llm_operator";
  renderTaskGatewayOptions();
}

function taskRow(task) {
  const latestRequestId = String(task?.latest_request_id || task?.current_request_id || "").trim();
  const liveRequestId = String(task?.current_request_id || "").trim();
  const row = document.createElement("details");
  row.className = "event-row task-row";
  row.dataset.taskId = String(task?.task_id || "");
  row.dataset.status = String(task?.status || "");
  row.open = !state.taskDetailsCollapsed
    && (state.taskDetailsExpanded || String(task?.task_id || "") === String(state.selectedTaskId || ""));
  const header = document.createElement("summary");
  header.className = "event-row-header task-row-header";
  header.addEventListener("click", (clickEvent) => {
    if (clickEvent.target instanceof Element && clickEvent.target.closest(".event-row-control")) {
      return;
    }
    selectTask(task);
  });
  const titleGroup = document.createElement("span");
  titleGroup.className = "event-row-title-group";
  const title = document.createElement("strong");
  title.className = "event-row-title";
  title.textContent = String(task?.title || "Untitled task");
  const badge = document.createElement("span");
  badge.className = "event-row-next-badge task-row-status";
  badge.textContent = taskStatusLabel(task?.status);
  titleGroup.append(title, badge);
  const actions = document.createElement("span");
  actions.className = "event-row-actions task-row-actions";
  const type = document.createElement("span");
  type.className = `event-status-badge ${taskTone(task?.status)}`;
  type.textContent = taskSourceLabel(task);
  actions.append(type);
  const traceLink = document.createElement("a");
  traceLink.className = "event-row-trace event-row-control";
  traceLink.dataset.taskAction = "open";
  traceLink.title = latestRequestId ? "Open latest task trace." : "No task trace yet.";
  traceLink.setAttribute("aria-label", `Open latest trace for ${task?.title || "task"}`);
  traceLink.href = latestRequestId ? `/api/agent/trace/${encodeURIComponent(latestRequestId)}` : "#";
  if (!latestRequestId) {
    traceLink.setAttribute("aria-disabled", "true");
    traceLink.tabIndex = -1;
  }
  traceLink.innerHTML = [
    '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">',
    '<path d="M10 13a5 5 0 0 0 7.07 0l2.12-2.12a5 5 0 0 0-7.07-7.07L10.9 5.03"/>',
    '<path d="M14 11a5 5 0 0 0-7.07 0L4.81 13.12a5 5 0 0 0 7.07 7.07l1.22-1.22"/>',
    "</svg>",
  ].join("");
  traceLink.addEventListener("click", (traceClick) => {
    traceClick.preventDefault();
    traceClick.stopPropagation();
    if (latestRequestId) {
      void taskAction(String(task?.task_id || ""), "open");
    }
  });
  actions.append(traceLink);
  if (liveRequestId) {
    const followButton = document.createElement("button");
    followButton.type = "button";
    followButton.className = "event-row-live event-row-control";
    followButton.dataset.taskAction = "follow";
    followButton.title = "Follow this running task live.";
    followButton.setAttribute("aria-label", `Follow live trace for ${task?.title || "task"}`);
    followButton.innerHTML = [
      '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">',
      '<path d="M5 5v14l14-7z"/>',
      "</svg>",
    ].join("");
    followButton.addEventListener("click", (followClick) => {
      followClick.preventDefault();
      followClick.stopPropagation();
      void taskAction(String(task?.task_id || ""), "follow");
    });
    actions.append(followButton);
  }
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "event-row-cancel event-row-control";
  cancelButton.dataset.taskAction = "cancel";
  cancelButton.title = "Cancel this task.";
  cancelButton.setAttribute("aria-label", `Cancel ${task?.title || "task"}`);
  cancelButton.disabled = !taskCanCancel(task);
  cancelButton.innerHTML = [
    '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">',
    '<path d="M18 6 6 18"/>',
    '<path d="m6 6 12 12"/>',
    "</svg>",
  ].join("");
  cancelButton.addEventListener("click", (cancelClick) => {
    cancelClick.preventDefault();
    cancelClick.stopPropagation();
    void taskAction(String(task?.task_id || ""), "cancel");
  });
  actions.append(cancelButton);
  const archiveButton = document.createElement("button");
  archiveButton.type = "button";
  archiveButton.className = "event-row-archive event-row-control";
  archiveButton.dataset.taskAction = "archive";
  archiveButton.title = "Archive this task.";
  archiveButton.setAttribute("aria-label", `Archive ${task?.title || "task"}`);
  archiveButton.disabled = Boolean(task?.archived_at) || String(task?.status || "") === "archived";
  archiveButton.innerHTML = [
    '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">',
    '<path d="M3 7h18"/>',
    '<path d="M5 7v13h14V7"/>',
    '<path d="M3 3h18v4H3z"/>',
    '<path d="M10 12h4"/>',
    "</svg>",
  ].join("");
  archiveButton.addEventListener("click", (archiveClick) => {
    archiveClick.preventDefault();
    archiveClick.stopPropagation();
    void taskAction(String(task?.task_id || ""), "archive");
  });
  actions.append(archiveButton);
  header.append(titleGroup, actions);
  const content = document.createElement("div");
  content.className = "event-row-content";
  const lines = document.createElement("div");
  lines.className = "event-row-lines";
  [
    ["Status", taskStatusLabel(task?.status)],
    ["Mode", task?.agent_mode || "llm_operator"],
    ["Gateway", task?.gateway_id || "Default"],
    [
      "Source Event",
      task?.source === "scheduled_event"
        ? `${taskSourceLabel(task)}${task?.source_event?.title ? `: ${task.source_event.title}` : ""}`
        : "-",
    ],
    ["Request", latestRequestId || "-", { requestId: latestRequestId }],
    ["Created", formatEventTime(task?.created_at)],
    ["Updated", formatEventTime(task?.updated_at)],
  ].forEach(([labelText, valueText, options]) => {
    const line = document.createElement("span");
    line.className = "event-row-line";
    const label = document.createElement("span");
    label.className = "event-row-label";
    label.textContent = labelText;
    const value = document.createElement("span");
    value.className = "event-row-value";
    if (options?.requestId) {
      const link = document.createElement("a");
      link.className = "event-row-value-link event-row-control";
      link.href = `/api/agent/trace/${encodeURIComponent(options.requestId)}`;
      link.textContent = valueText;
      link.title = "Open latest task trace.";
      link.addEventListener("click", (linkClick) => {
        linkClick.preventDefault();
        linkClick.stopPropagation();
        void openTaskRequestTrace(options.requestId, {
          title: "Loading task trace",
          detail: "Fetching full saved task trace...",
        });
      });
      value.append(link);
    } else {
      value.textContent = valueText;
    }
    line.append(label, value);
    lines.append(line);
  });
  const prompt = document.createElement("p");
  prompt.className = "event-row-prompt task-row-prompt";
  prompt.textContent = `Prompt: ${String(task?.prompt || "")}`;
  const latest = task?.latest_checkpoint;
  const checkpoint = document.createElement("span");
  checkpoint.className = "event-row-prompt task-row-checkpoint";
  checkpoint.textContent = `Latest: ${latest?.summary || latest?.title || task?.blocker_reason || task?.error_preview || task?.final_response_preview || "No checkpoint yet."}`;
  content.append(lines, prompt, checkpoint);
  row.append(header, content);
  return row;
}

function renderTasksSummary() {
  if (!tasksStatusSummary) return;
  const counts = state.taskCounts || {};
  const items = [
    ["Queued", counts.queued || 0],
    ["Running", counts.running || 0],
    ["Needs OK", counts.awaiting_confirmation || 0],
    ["Needs Input", counts.awaiting_clarification || 0],
    ["Done", counts.completed || 0],
    ["Archived", counts.archived || 0],
  ];
  tasksStatusSummary.replaceChildren();
  for (const [label, value] of items) {
    const card = document.createElement("div");
    card.className = "memory-stat-card";
    const number = document.createElement("strong");
    number.textContent = String(Number(value || 0));
    const caption = document.createElement("span");
    caption.textContent = label;
    card.append(number, caption);
    tasksStatusSummary.append(card);
  }
}

function updateTaskControls() {
  const selected = state.selectedTask || taskById(state.selectedTaskId);
  if (taskOpenButton) taskOpenButton.disabled = !selected?.latest_request_id;
  if (taskStartButton) taskStartButton.disabled = !taskCanStart(selected);
  if (taskRetryButton) taskRetryButton.disabled = !taskCanRetry(selected);
  if (taskCancelButton) taskCancelButton.disabled = !taskCanCancel(selected);
  if (taskArchiveButton) taskArchiveButton.disabled = !selected || Boolean(selected?.archived_at);
  if (taskDeleteButton) taskDeleteButton.disabled = !selected;
  if (tasksClearArchivedButton) tasksClearArchivedButton.disabled = Number(state.taskCounts?.archived || 0) <= 0;
}

function taskDetailRow(titleText, bodyText, { open = false, linkText = "", requestId = "" } = {}) {
  const row = document.createElement("details");
  row.className = "event-run-row task-detail-row";
  row.open = !state.taskDetailsCollapsed && (state.taskDetailsExpanded || open);
  const title = document.createElement("summary");
  title.className = "event-run-summary";
  title.textContent = titleText;
  const content = document.createElement("div");
  content.className = "event-run-content";
  const body = document.createElement("pre");
  body.className = "event-run-markdown";
  body.textContent = stripAssistantResponseChrome(bodyText || "");
  content.append(body);
  if (requestId && linkText) {
    const link = document.createElement("a");
    link.className = "event-run-link";
    link.href = `/api/agent/trace/${encodeURIComponent(requestId)}`;
    link.textContent = linkText;
    link.addEventListener("click", (eventClick) => {
      eventClick.preventDefault();
      void openTaskRequestTrace(requestId, {
        title: "Loading task trace",
        detail: "Fetching full saved task trace...",
      });
    });
    content.append(link);
  }
  row.append(title, content);
  return row;
}

function renderTaskDetails() {
  if (!taskDetails) return;
  taskDetails.replaceChildren();
  const selected = state.selectedTask || taskById(state.selectedTaskId);
  if (!selected) {
    taskDetails.append(empty("Select a task to see details."));
    updateTaskControls();
    return;
  }
  const taskId = String(selected.task_id || "");
  const latest = selected.latest_checkpoint;
  taskDetails.append(taskDetailRow(
    `${taskStatusLabel(selected.status)} · ${selected.title || "Untitled task"}`,
    [
      `Prompt: ${selected.prompt || ""}`,
      `Source: ${selected.source || "task_sheet"}`,
      `Mode: ${selected.agent_mode || "llm_operator"}`,
      `Gateway: ${selected.gateway_id || "Default"}`,
      `Latest request: ${selected.latest_request_id || "-"}`,
      `Latest checkpoint: ${latest?.summary || latest?.title || selected.blocker_reason || selected.error_preview || selected.final_response_preview || "No checkpoint yet."}`,
    ].join("\n"),
    { open: true, linkText: selected.latest_request_id ? `Trace ${selected.latest_request_id}` : "", requestId: selected.latest_request_id || "" },
  ));
  const attempts = state.taskAttempts[taskId] || [];
  attempts.slice().reverse().forEach((attempt, index) => {
    taskDetails.append(taskDetailRow(
      `Attempt ${attempt.trigger || "start"} · ${taskStatusLabel(attempt.status)} · ${formatEventTime(attempt.started_at || attempt.created_at)}`,
      [
        attempt.final_response_preview || attempt.error_preview || "No final preview yet.",
        attempt.parent_request_id ? `Parent request: ${attempt.parent_request_id}` : "",
        attempt.request_id ? `Request: ${attempt.request_id}` : "",
      ].filter(Boolean).join("\n"),
      { open: index === 0, linkText: attempt.request_id ? `Trace ${attempt.request_id}` : "", requestId: attempt.request_id || "" },
    ));
  });
  const checkpoints = state.taskCheckpoints[taskId] || [];
  checkpoints.slice(-12).reverse().forEach((checkpoint, index) => {
    taskDetails.append(taskDetailRow(
      `${checkpoint.stage || "checkpoint"} · ${checkpoint.event_type || "event"} · ${formatEventTime(checkpoint.created_at)}`,
      [
        checkpoint.title || "",
        checkpoint.summary || "",
      ].filter(Boolean).join("\n") || "Checkpoint recorded.",
      { open: !attempts.length && index === 0 },
    ));
  });
  updateTaskControls();
}

function renderTasks() {
  renderTaskBadge();
  renderTaskGatewayOptions();
  renderTasksSummary();
  taskFilterButtons.forEach((button) => {
    button.classList.toggle("active", String(button.dataset.taskFilter || "") === state.taskFilter);
  });
  if (!tasksList) return;
  tasksList.replaceChildren();
  if (!state.tasks.length) {
    tasksList.append(empty("No durable tasks."));
    renderTaskDetails();
    return;
  }
  state.tasks.forEach((task) => tasksList.append(taskRow(task)));
  syncTaskSelectionClasses();
  renderTaskDetails();
  syncDrawerCollapseButtons();
}

async function loadSelectedTaskDetails(taskId = state.selectedTaskId) {
  const id = String(taskId || "").trim();
  if (!id) {
    state.selectedTask = null;
    renderTaskDetails();
    return;
  }
  try {
    const [detailResponse, attemptsResponse, checkpointsResponse] = await Promise.all([
      fetch(`/api/agent/tasks/${encodeURIComponent(id)}`, { cache: "no-store" }),
      fetch(`/api/agent/tasks/${encodeURIComponent(id)}/attempts?limit=100`, { cache: "no-store" }),
      fetch(`/api/agent/tasks/${encodeURIComponent(id)}/checkpoints?limit=200`, { cache: "no-store" }),
    ]);
    if (!detailResponse.ok) throw new Error(await detailResponse.text());
    const detailPayload = await detailResponse.json();
    state.selectedTask = detailPayload.task || taskById(id);
    if (attemptsResponse.ok) {
      const payload = await attemptsResponse.json();
      state.taskAttempts[id] = Array.isArray(payload.attempts) ? payload.attempts : [];
    }
    if (checkpointsResponse.ok) {
      const payload = await checkpointsResponse.json();
      state.taskCheckpoints[id] = Array.isArray(payload.checkpoints) ? payload.checkpoints : [];
    }
    syncTaskSelectionClasses();
    renderTaskDetails();
  } catch (error) {
    state.selectedTask = taskById(id);
    renderTaskDetails();
  }
}

async function loadTasks() {
  const params = new URLSearchParams({ limit: "100" });
  if (state.taskFilter) {
    params.set("status", state.taskFilter);
    if (state.taskFilter === "archived") {
      params.set("include_archived", "true");
    }
  }
  try {
    const response = await fetch(`/api/agent/tasks?${params.toString()}`, { cache: "no-store" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.tasks = Array.isArray(payload.tasks) ? payload.tasks : [];
    state.taskCounts = payload.counts || {};
    const attached = await syncAttachedDurableTaskRequest(state.tasks);
    if (!attached) {
      await autoAttachOpenDurableTask(state.tasks);
    }
    syncComposerSubmitButton();
    if (!state.tasks.some((task) => String(task.task_id || "") === String(state.selectedTaskId || ""))) {
      state.selectedTaskId = String(state.tasks[0]?.task_id || "");
      state.selectedTask = state.tasks[0] || null;
    } else {
      state.selectedTask = taskById(state.selectedTaskId) || state.selectedTask;
    }
    renderTasks();
    if (state.selectedTaskId) {
      await loadSelectedTaskDetails(state.selectedTaskId);
    }
  } catch (error) {
    if (tasksList) {
      tasksList.replaceChildren(empty(`Tasks unavailable: ${shortStatusError(error)}`));
    }
  }
}

async function openTaskRequestTrace(
  requestId,
  {
    title = "Loading task trace",
    detail = "Fetching full saved task trace...",
    renderTraceEvents = true,
    focusTrace = true,
  } = {},
) {
  const id = String(requestId || "").trim();
  if (!id) return false;
  state.requestId = id;
  if (requestIdLabel) {
    requestIdLabel.textContent = id;
  }
  setTasksDrawerOpen(false);
  setConversationCollapsed(false);
  setRunStatus("opening task", "running");
  const progress = showRequestLoadProgress({
    requestId: id,
    title,
    detail,
  });
  let loaded = false;
  let unavailableDetail = "";
  try {
    loaded = await loadFinalTrace(id, {
      renderTraceEvents,
      focusTrace,
      onTracePayload: () => updateRequestLoadProgress(
        progress,
        renderTraceEvents ? "Rendering task trace..." : "Rendering task chat...",
      ),
      onTraceUnavailable: (traceDetail) => {
        unavailableDetail = String(traceDetail?.message || traceDetail?.statusText || "").trim();
        updateRequestLoadProgress(progress, "Task trace unavailable.");
      },
    });
    if (!loaded) {
      setRunStatus("failed", "failed");
      addMessage(
        "assistant",
        "Task trace unavailable",
        notificationChatUnavailableMessage(id, unavailableDetail),
      );
    }
  } catch (error) {
    setRunStatus("failed", "failed");
    addMessage(
      "assistant",
      "Task trace unavailable",
      notificationChatUnavailableMessage(id, shortStatusError(error)),
    );
  } finally {
    clearRequestLoadProgress(progress, "Task trace could not be loaded.");
  }
  return loaded;
}

async function createDurableTask({ startNow = true } = {}) {
  const prompt = String(taskPrompt?.value || "").trim();
  if (!prompt) {
    showNotification({ level: "warning", title: "Task prompt required", message: "Enter a prompt before creating a task." });
    return;
  }
  const gatewayId = String(taskGateway?.value || "").trim();
  const body = {
    prompt,
    title: String(taskTitle?.value || "").trim(),
    agent_mode: String(taskAgentMode?.value || currentAgentMode() || "llm_operator"),
    gateway_id: gatewayId,
    conversation_id: state.conversationId || "",
    context: agentSettingsContext(),
    llm_model: selectedModelValue(),
    start_now: Boolean(startNow),
  };
  if (gatewayId) {
    body.context.gateway_id = gatewayId;
  }
  try {
    const response = await fetch("/api/agent/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    taskPrompt.value = "";
    if (taskTitle) taskTitle.value = "";
    if (payload.request_id && payload.stream_url) {
      state.requestId = payload.request_id;
      state.conversationId = payload.conversation_id || state.conversationId;
      startTraceStream(payload.request_id, payload.stream_url);
    } else if (payload.task?.task_id && String(payload.task?.status || "") === "queued") {
      notifyQueuedTaskForAutoAttach(payload.task, { source: "task" });
    }
    if (payload.task?.task_id) {
      state.selectedTaskId = String(payload.task.task_id);
      state.selectedTask = payload.task;
    }
    await loadTasks();
    setTasksDrawerOpen(true);
  } catch (error) {
    showNotification({ level: "error", title: "Task creation failed", message: shortStatusError(error) });
  }
}

async function queueComposerPromptAsTask({ prompt, requestBody, routingPreview, attachStarted = false }) {
  const context = {
    ...(requestBody.context || {}),
    durable_task_create_source: "chat",
    agent_mode: requestBody.agent_mode,
    llm_model: requestBody.llm_model,
  };
  const gatewayId = String(
    routingPreview?.gateway?.gateway_id ||
      context.gateway_id ||
      state.selectedGatewayId ||
      "",
  ).trim();
  if (gatewayId) {
    context.gateway_id = gatewayId;
  }
  const body = {
    prompt,
    title: "",
    agent_mode: requestBody.agent_mode,
    gateway_id: gatewayId,
    conversation_id: requestBody.conversation_id || state.conversationId || "",
    context,
    llm_model: requestBody.llm_model,
    start_now: false,
  };
  const response = await fetch("/api/agent/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    throw new Error(await response.text());
  }
  const payload = await response.json();
  if (payload.task?.task_id) {
    state.selectedTaskId = String(payload.task.task_id);
    state.selectedTask = payload.task;
  }
  if (attachStarted && payload.request_id && payload.stream_url) {
    state.requestId = payload.request_id;
    state.conversationId = payload.conversation_id || state.conversationId;
    state.requestGatewayRouting.set(payload.request_id, routingPreview?.metadata || {});
    applyContextWindowTokens(payload.llm_context_window_tokens);
    startTraceStream(payload.request_id, payload.stream_url);
  } else if (payload.task?.task_id && String(payload.task?.status || "") === "queued") {
    notifyQueuedTaskForAutoAttach(payload.task, { source: "chat" });
    if (attachStarted) {
      removeThinkingIndicator();
      setRunStatus("queued", "pending");
      setComposerPreparing(false);
    }
  } else if (payload.request_id) {
    showNotification({
      level: "info",
      title: "Task created",
      message: `${taskDisplayName(payload.task)} started as a durable task and will attach when the current view is free.`,
      source_type: "durable_task_local",
      source_id: `created:${payload.task?.task_id || payload.request_id}`,
      request_id: payload.request_id,
      metadata: {
        task_id: String(payload.task?.task_id || ""),
        task_status: String(payload.task?.status || payload.status || "running"),
        request_id: payload.request_id,
        stream_url: payload.stream_url || streamUrlForRequest(payload.request_id),
      },
    }, { persistMs: 9000 });
  }
  await loadTasks();
  return payload;
}

async function submitComposerPromptLive({ requestBody, routingPreview, requestScopedAutoApprove = false }) {
  const response = await fetch("/api/agent/request", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(requestBody),
  });
  if (!response.ok) {
    throw new Error(await response.text());
  }
  const payload = await response.json();
  if (payload.conversation_id) {
    state.conversationId = payload.conversation_id;
  }
  applyContextWindowTokens(payload.llm_context_window_tokens);
  if (payload.request_id) {
    state.requestId = payload.request_id;
    state.requestGatewayRouting.set(payload.request_id, routingPreview?.metadata || payload.gateway_routing || {});
    if (requestScopedAutoApprove) {
      state.requestAutoApproveIds.add(payload.request_id);
    }
  }
  startTraceStream(payload.request_id, payload.stream_url);
  return payload;
}

async function taskAction(taskId, action) {
  const id = String(taskId || "").trim();
  if (!id) return;
  if (action === "open") {
    const task = state.selectedTask?.task_id === id ? state.selectedTask : taskById(id);
    const requestId = String(task?.latest_request_id || task?.current_request_id || "").trim();
    if (requestId) {
      await openTaskRequestTrace(requestId);
    }
    return;
  }
  if (action === "follow") {
    const task = state.selectedTask?.task_id === id ? state.selectedTask : taskById(id);
    const requestId = String(task?.current_request_id || task?.latest_request_id || "").trim();
    if (requestId) {
      followLiveTaskRequest(requestId, taskStreamUrl(task));
    }
    return;
  }
  if (action === "delete") {
    await deleteTask(id);
    return;
  }
  try {
    const response = await fetch(`/api/agent/tasks/${encodeURIComponent(id)}/${action}`, { method: "POST" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    if (payload.task?.task_id) {
      state.selectedTaskId = String(payload.task.task_id);
      state.selectedTask = payload.task;
    }
    if (payload.request_id && payload.stream_url) {
      state.requestId = payload.request_id;
      state.conversationId = payload.conversation_id || state.conversationId;
      startTraceStream(payload.request_id, payload.stream_url);
    } else if (payload.task?.task_id && String(payload.task?.status || "") === "queued") {
      notifyQueuedTaskForAutoAttach(payload.task, { source: "task" });
    }
    await loadTasks();
  } catch (error) {
    showNotification({ level: "error", title: "Task update failed", message: shortStatusError(error) });
  }
}

async function deleteTask(taskId) {
  const id = String(taskId || "").trim();
  if (!id) return;
  if (!window.confirm("Delete this task and its saved attempts/checkpoints?")) {
    return;
  }
  try {
    const response = await fetch(`/api/agent/tasks/${encodeURIComponent(id)}`, { method: "DELETE" });
    if (!response.ok) throw new Error(await response.text());
    if (state.selectedTaskId === id) {
      state.selectedTaskId = "";
      state.selectedTask = null;
    }
    await loadTasks();
  } catch (error) {
    showNotification({ level: "error", title: "Task delete failed", message: shortStatusError(error) });
  }
}

async function clearArchivedTasks() {
  const archivedCount = Number(state.taskCounts?.archived || 0);
  if (archivedCount <= 0) return;
  if (!window.confirm(`Delete ${archivedCount} archived task${archivedCount === 1 ? "" : "s"} permanently?`)) {
    return;
  }
  try {
    const response = await fetch("/api/agent/tasks?status=archived&limit=500&include_archived=true", {
      method: "DELETE",
    });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.selectedTaskId = "";
    state.selectedTask = null;
    await loadTasks();
    showNotification({
      level: "success",
      title: "Archived tasks cleared",
      message: `Deleted ${Number(payload.deleted || 0)} archived task${Number(payload.deleted || 0) === 1 ? "" : "s"}.`,
    });
  } catch (error) {
    showNotification({ level: "error", title: "Task cleanup failed", message: shortStatusError(error) });
  }
}

function monitorStatusLabel(status) {
  return String(status || "queued").replace(/_/g, " ");
}

function monitorTone(status) {
  const value = String(status || "");
  if (["completed", "running"].includes(value)) return "success";
  if (["failed", "cancelled"].includes(value)) return "error";
  if (["triggered", "paused", "interrupted"].includes(value)) return "warning";
  return "info";
}

function renderMonitorBadge() {
  const active = Number(state.monitorCounts?.queued || 0)
    + Number(state.monitorCounts?.running || 0)
    + Number(state.monitorCounts?.paused || 0)
    + Number(state.monitorCounts?.triggered || 0);
  if (monitorsBadge) {
    monitorsBadge.hidden = active <= 0;
    monitorsBadge.textContent = active > 99 ? "99+" : String(active);
  }
}

function monitorById(monitorId) {
  const id = String(monitorId || "").trim();
  return state.monitors.find((monitor) => String(monitor?.monitor_id || "") === id) || null;
}

function monitorCanStart(monitor) {
  return Boolean(monitor) && !["running", "triggered", "archived"].includes(String(monitor?.status || ""));
}

function monitorCanPause(monitor) {
  return ["queued", "running"].includes(String(monitor?.status || ""));
}

function monitorCanCancel(monitor) {
  return ["queued", "running", "paused"].includes(String(monitor?.status || ""));
}

function renderMonitorGatewayOptions() {
  if (!monitorGateway) return;
  const selected = monitorGateway.value || state.selectedGatewayId || "";
  monitorGateway.replaceChildren();
  const fallback = document.createElement("option");
  fallback.value = "";
  fallback.textContent = "Default";
  monitorGateway.append(fallback);
  (Array.isArray(state.gateways) ? state.gateways : [])
    .filter((gateway) => gateway.enabled !== false)
    .forEach((gateway) => {
      const option = document.createElement("option");
      option.value = gateway.gateway_id || "";
      option.textContent = gatewayDisplayName(gateway);
      monitorGateway.append(option);
    });
  monitorGateway.value = Array.from(monitorGateway.options).some((option) => option.value === selected)
    ? selected
    : "";
}

function syncMonitorSelectionClasses() {
  if (!monitorsList) return;
  monitorsList.querySelectorAll(".monitor-row").forEach((row) => {
    const selected = String(row.dataset.monitorId || "") === String(state.selectedMonitorId || "");
    row.classList.toggle("selected", selected);
    if (row instanceof HTMLDetailsElement) {
      if (state.monitorDetailsCollapsed) {
        row.open = false;
      } else if (state.monitorDetailsExpanded || selected) {
        row.open = true;
      }
    }
  });
}

function selectMonitor(monitorOrId, { load = true, stream = true } = {}) {
  const monitor = typeof monitorOrId === "string" ? monitorById(monitorOrId) : monitorOrId;
  const monitorId = String(monitor?.monitor_id || monitorOrId || "").trim();
  state.selectedMonitorId = monitorId;
  state.selectedMonitor = monitor || monitorById(monitorId);
  syncMonitorSelectionClasses();
  updateMonitorControls();
  renderMonitorDetails();
  if (load && monitorId) {
    void loadSelectedMonitorDetails(monitorId, { stream });
  }
}

function clearMonitorEditor() {
  if (monitorTitle) monitorTitle.value = "";
  if (monitorCommand) {
    monitorCommand.value = "";
    resetTextareaHeight(monitorCommand);
  }
  if (monitorMode) monitorMode.value = "sample_command";
  if (monitorIntervalSeconds) monitorIntervalSeconds.value = "5";
  if (monitorDurationSeconds) monitorDurationSeconds.value = "300";
  if (monitorCondition) monitorCondition.value = "";
  if (monitorActionPrompt) {
    monitorActionPrompt.value = "";
    resetTextareaHeight(monitorActionPrompt);
  }
  if (monitorAgentMode) monitorAgentMode.value = currentAgentMode() || "llm_operator";
  renderMonitorGatewayOptions();
}

function monitorLatestOutput(monitor) {
  const latest = monitor?.latest_observation;
  return String(
    latest?.output_preview
      || latest?.stdout
      || latest?.stderr
      || monitor?.trigger_reason
      || monitor?.error_preview
      || monitor?.final_summary
      || "",
  );
}

function monitorRow(monitor) {
  const row = document.createElement("details");
  row.className = "event-row monitor-row";
  row.dataset.monitorId = String(monitor?.monitor_id || "");
  row.dataset.status = String(monitor?.status || "");
  row.open = !state.monitorDetailsCollapsed
    && (state.monitorDetailsExpanded || String(monitor?.monitor_id || "") === String(state.selectedMonitorId || ""));
  const header = document.createElement("summary");
  header.className = "event-row-header monitor-row-header";
  header.addEventListener("click", (clickEvent) => {
    if (clickEvent.target instanceof Element && clickEvent.target.closest(".event-row-control")) {
      return;
    }
    selectMonitor(monitor);
  });
  const titleGroup = document.createElement("span");
  titleGroup.className = "event-row-title-group";
  const title = document.createElement("strong");
  title.className = "event-row-title";
  title.textContent = String(monitor?.title || "Untitled monitor");
  const badge = document.createElement("span");
  badge.className = "event-row-next-badge monitor-row-status";
  badge.textContent = monitorStatusLabel(monitor?.status);
  titleGroup.append(title, badge);
  const actions = document.createElement("span");
  actions.className = "event-row-actions monitor-row-actions";
  const type = document.createElement("span");
  type.className = `event-status-badge ${monitorTone(monitor?.status)}`;
  type.textContent = String(monitor?.mode || "sample_command").replace(/_/g, " ");
  actions.append(type);
  if (String(monitor?.planner_rationale || "").trim()) {
    const planned = document.createElement("span");
    planned.className = "event-status-badge info";
    planned.textContent = "LLM planned";
    actions.append(planned);
  }
  if (["llm_judged", "hybrid"].includes(String(monitor?.trigger_mode || ""))) {
    const judged = document.createElement("span");
    judged.className = "event-status-badge warning";
    judged.textContent = "LLM judged";
    actions.append(judged);
  }
  header.append(titleGroup, actions);
  const content = document.createElement("div");
  content.className = "event-row-content";
  const lines = document.createElement("div");
  lines.className = "event-row-lines";
  [
    ["Status", monitorStatusLabel(monitor?.status)],
    ["Gateway", monitor?.gateway_id || "Default"],
    ["Terminal", monitor?.terminal_session_id || "-"],
    ["Every", `${Number(monitor?.interval_seconds || 5)}s`],
    ["Duration", `${Number(monitor?.duration_seconds || 300)}s`],
    ["Updated", formatEventTime(monitor?.updated_at)],
  ].forEach(([labelText, valueText]) => {
    const line = document.createElement("span");
    line.className = "event-row-line";
    const label = document.createElement("span");
    label.className = "event-row-label";
    label.textContent = labelText;
    const value = document.createElement("span");
    value.className = "event-row-value";
    value.textContent = valueText;
    line.append(label, value);
    lines.append(line);
  });
  const command = document.createElement("p");
  command.className = "event-row-prompt monitor-row-command";
  command.textContent = `Command: ${String(monitor?.command || "")}`;
  const latest = document.createElement("span");
  latest.className = "event-row-prompt monitor-row-latest";
  latest.textContent = `Latest: ${monitorLatestOutput(monitor) || "No observations yet."}`;
  content.append(lines, command, latest);
  row.append(header, content);
  return row;
}

function renderMonitorsSummary() {
  if (!monitorsStatusSummary) return;
  const counts = state.monitorCounts || {};
  const items = [
    ["Queued", counts.queued || 0],
    ["Running", counts.running || 0],
    ["Triggered", counts.triggered || 0],
    ["Paused", counts.paused || 0],
    ["Done", counts.completed || 0],
  ];
  monitorsStatusSummary.replaceChildren();
  for (const [label, value] of items) {
    const card = document.createElement("div");
    card.className = "memory-stat-card";
    const number = document.createElement("strong");
    number.textContent = String(Number(value || 0));
    const caption = document.createElement("span");
    caption.textContent = label;
    card.append(number, caption);
    monitorsStatusSummary.append(card);
  }
}

function updateMonitorControls() {
  const selected = state.selectedMonitor || monitorById(state.selectedMonitorId);
  if (monitorStartButton) monitorStartButton.disabled = !monitorCanStart(selected);
  if (monitorPauseButton) monitorPauseButton.disabled = !monitorCanPause(selected);
  if (monitorCancelButton) monitorCancelButton.disabled = !monitorCanCancel(selected);
  if (monitorArchiveButton) monitorArchiveButton.disabled = !selected;
  if (monitorOpenTaskButton) monitorOpenTaskButton.disabled = !selected?.triggered_task_id;
}

function monitorDetailRow(titleText, bodyText, { open = false } = {}) {
  const row = document.createElement("details");
  row.className = "event-run-row monitor-detail-row";
  row.open = !state.monitorDetailsCollapsed && (state.monitorDetailsExpanded || open);
  const title = document.createElement("summary");
  title.className = "event-run-summary";
  title.textContent = titleText;
  const content = document.createElement("div");
  content.className = "event-run-content";
  const body = document.createElement("pre");
  body.className = "event-run-markdown";
  body.textContent = bodyText || "";
  content.append(body);
  row.append(title, content);
  return row;
}

function renderMonitorDetails() {
  if (!monitorDetails) return;
  monitorDetails.replaceChildren();
  const selected = state.selectedMonitor || monitorById(state.selectedMonitorId);
  if (!selected) {
    monitorDetails.append(empty("Select a monitor to see details."));
    updateMonitorControls();
    return;
  }
  const monitorId = String(selected.monitor_id || "");
  monitorDetails.append(monitorDetailRow(
    `${monitorStatusLabel(selected.status)} · ${selected.title || "Untitled monitor"}`,
    [
      `Mode: ${String(selected.mode || "sample_command").replace(/_/g, " ")}`,
      `Command: ${selected.command || ""}`,
      `Trigger mode: ${String(selected.trigger_mode || "deterministic").replace(/_/g, " ")}`,
      `Condition: ${selected.condition || "completion only"}`,
      `Natural condition: ${selected.natural_language_condition || "-"}`,
      `Judge: ${selected.latest_judge_summary || "-"}`,
      `Action prompt: ${selected.action_prompt || "-"}`,
      `Planner: ${selected.planner_rationale || "-"}`,
      `Risk notes: ${selected.risk_notes || "-"}`,
      `Gateway: ${selected.gateway_id || "Default"}`,
      `Background terminal: ${selected.terminal_session_id || "-"}`,
      `Trigger: ${selected.trigger_reason || "-"}`,
      `Task: ${selected.triggered_task_id || "-"}`,
    ].join("\n"),
    { open: true },
  ));
  const observations = state.monitorObservations[monitorId] || [];
  observations.slice(-20).reverse().forEach((observation, index) => {
    monitorDetails.append(monitorDetailRow(
      `${observation.kind || "sample"} · ${observation.status || "ok"} · ${formatEventTime(observation.created_at)}`,
      [
        observation.match_reason || "",
        observation.output_preview || observation.stdout || observation.stderr || "",
      ].filter(Boolean).join("\n") || "Observation recorded.",
      { open: index === 0 },
    ));
  });
  updateMonitorControls();
}

function renderMonitors() {
  renderMonitorBadge();
  renderMonitorGatewayOptions();
  renderMonitorsSummary();
  monitorFilterButtons.forEach((button) => {
    button.classList.toggle("active", String(button.dataset.monitorFilter || "") === state.monitorFilter);
  });
  if (!monitorsList) return;
  monitorsList.replaceChildren();
  if (!state.monitors.length) {
    monitorsList.append(empty("No monitors yet."));
    renderMonitorDetails();
    return;
  }
  state.monitors.forEach((monitor) => monitorsList.append(monitorRow(monitor)));
  syncMonitorSelectionClasses();
  renderMonitorDetails();
  syncDrawerCollapseButtons();
}

function closeMonitorStream() {
  if (state.monitorStream) {
    state.monitorStream.close();
  }
  state.monitorStream = null;
  state.monitorStreamId = "";
}

function openMonitorStream(monitorId) {
  const id = String(monitorId || "").trim();
  if (!id || state.monitorStreamId === id) return;
  closeMonitorStream();
  if (!window.EventSource) return;
  const source = new EventSource(`/api/agent/monitors/${encodeURIComponent(id)}/stream`);
  state.monitorStream = source;
  state.monitorStreamId = id;
  const refresh = () => {
    void loadSelectedMonitorDetails(id, { stream: false });
    void loadMonitors({ preserveSelection: true });
  };
  source.addEventListener("status", refresh);
  source.addEventListener("observation", refresh);
  source.addEventListener("error", () => {
    closeMonitorStream();
  });
}

async function loadSelectedMonitorDetails(monitorId = state.selectedMonitorId, { stream = true } = {}) {
  const id = String(monitorId || "").trim();
  if (!id) {
    state.selectedMonitor = null;
    renderMonitorDetails();
    return;
  }
  try {
    const [detailResponse, observationsResponse] = await Promise.all([
      fetch(`/api/agent/monitors/${encodeURIComponent(id)}`, { cache: "no-store" }),
      fetch(`/api/agent/monitors/${encodeURIComponent(id)}/observations?limit=200`, { cache: "no-store" }),
    ]);
    if (!detailResponse.ok) throw new Error(await detailResponse.text());
    const detailPayload = await detailResponse.json();
    state.selectedMonitor = detailPayload.monitor || monitorById(id);
    if (observationsResponse.ok) {
      const payload = await observationsResponse.json();
      state.monitorObservations[id] = Array.isArray(payload.observations) ? payload.observations : [];
    }
    syncMonitorSelectionClasses();
    renderMonitorDetails();
    if (stream && ["queued", "running", "paused"].includes(String(state.selectedMonitor?.status || ""))) {
      openMonitorStream(id);
    }
  } catch (error) {
    state.selectedMonitor = monitorById(id);
    renderMonitorDetails();
  }
}

async function loadMonitors({ preserveSelection = false } = {}) {
  const params = new URLSearchParams({ limit: "100" });
  if (state.monitorFilter) {
    params.set("status", state.monitorFilter);
  }
  try {
    const response = await fetch(`/api/agent/monitors?${params.toString()}`, { cache: "no-store" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.monitors = Array.isArray(payload.monitors) ? payload.monitors : [];
    state.monitorCounts = payload.counts || {};
    if (!preserveSelection || !state.monitors.some((monitor) => String(monitor.monitor_id || "") === String(state.selectedMonitorId || ""))) {
      state.selectedMonitorId = String(state.monitors[0]?.monitor_id || "");
      state.selectedMonitor = state.monitors[0] || null;
    } else {
      state.selectedMonitor = monitorById(state.selectedMonitorId) || state.selectedMonitor;
    }
    renderMonitors();
    if (state.selectedMonitorId) {
      await loadSelectedMonitorDetails(state.selectedMonitorId);
    }
  } catch (error) {
    if (monitorsList) {
      monitorsList.replaceChildren(empty(`Monitors unavailable: ${shortStatusError(error)}`));
    }
  }
}

async function createMonitor({ startNow = true, draft = null } = {}) {
  const source = draft || {};
  const command = String(source.command ?? monitorCommand?.value ?? "").trim();
  if (!command) {
    showNotification({ level: "warning", title: "Monitor command required", message: "Enter a command before creating a monitor." });
    return null;
  }
  const gatewayId = String(source.gateway_id ?? monitorGateway?.value ?? state.selectedGatewayId ?? "").trim();
  const body = {
    prompt: String(source.prompt || command),
    title: String(source.title ?? monitorTitle?.value ?? "").trim(),
    mode: String(source.mode || monitorMode?.value || "sample_command"),
    command,
    interval_seconds: Number(source.interval_seconds || monitorIntervalSeconds?.value || 5),
    duration_seconds: Number(source.duration_seconds || monitorDurationSeconds?.value || 300),
    condition: String(source.condition ?? monitorCondition?.value ?? "").trim(),
    natural_language_condition: String(source.natural_language_condition ?? "").trim(),
    trigger_mode: String(source.trigger_mode || "deterministic"),
    action_prompt: String(source.action_prompt ?? monitorActionPrompt?.value ?? "").trim(),
    planner_rationale: String(source.planner_rationale || "").trim(),
    risk_notes: String(source.risk_notes || "").trim(),
    judge_interval_seconds: Number(source.judge_interval_seconds || 5),
    agent_mode: String(source.agent_mode || monitorAgentMode?.value || currentAgentMode() || "llm_operator"),
    gateway_id: gatewayId,
    conversation_id: state.conversationId || "",
    context: source.context || agentSettingsContext(),
    start_now: Boolean(startNow),
  };
  if (gatewayId) {
    body.context = { ...(body.context || {}), gateway_id: gatewayId };
  }
  try {
    const response = await fetch("/api/agent/monitors", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    if (!draft) {
      clearMonitorEditor();
    }
    if (payload.monitor?.monitor_id) {
      state.selectedMonitorId = String(payload.monitor.monitor_id);
      state.selectedMonitor = payload.monitor;
    }
    await loadMonitors({ preserveSelection: true });
    setMonitorsDrawerOpen(true);
    return payload.monitor || null;
  } catch (error) {
    showNotification({ level: "error", title: "Monitor creation failed", message: shortStatusError(error) });
    return null;
  }
}

async function monitorAction(monitorId, action) {
  const id = String(monitorId || "").trim();
  if (!id) return;
  if (action === "open-task") {
    const monitor = state.selectedMonitor?.monitor_id === id ? state.selectedMonitor : monitorById(id);
    const taskId = String(monitor?.triggered_task_id || "").trim();
    if (taskId) {
      setMonitorsDrawerOpen(false);
      state.selectedTaskId = taskId;
      await loadTasks();
      setTasksDrawerOpen(true);
    }
    return;
  }
  try {
    const response = await fetch(`/api/agent/monitors/${encodeURIComponent(id)}/${action}`, { method: "POST" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    if (payload.monitor?.monitor_id) {
      state.selectedMonitorId = String(payload.monitor.monitor_id);
      state.selectedMonitor = payload.monitor;
    }
    await loadMonitors({ preserveSelection: true });
  } catch (error) {
    showNotification({ level: "error", title: "Monitor update failed", message: shortStatusError(error) });
  }
}

function looksLikeMonitorPrompt(prompt) {
  const text = String(prompt || "").trim().toLowerCase();
  return /^\/monitor\b/.test(text)
    || /\b(monitor|watch|observe|alert me|tell me if|notify me if)\b/.test(text)
    || /\b(nvidia-smi|free ram|gpu memory|disk space|tail\s+-f)\b/.test(text);
}

async function maybeDraftMonitor(prompt, requestBody) {
  if (!looksLikeMonitorPrompt(prompt)) {
    return false;
  }
  try {
    const response = await fetch("/api/agent/monitors/draft", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt,
        context: requestBody.context || {},
        agent_mode: requestBody.agent_mode || "llm_operator",
        llm_model: requestBody.llm_model || "auto",
      }),
    });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    const draftResponse = payload.draft || payload;
    if (!draftResponse.is_monitor_request) {
      return false;
    }
    const draft = Array.isArray(draftResponse.drafts) ? draftResponse.drafts[0] : null;
    const missing = Array.isArray(draftResponse.missing_details) ? draftResponse.missing_details : [];
    if (!draft || missing.length || !String(draft.command || "").trim()) {
      removeThinkingIndicator();
      addMessage(
        "assistant",
        "Monitor needs detail",
        `I need ${missing.join(", ") || "a command or condition"} before starting that monitor.`,
      );
      setRunStatus("monitor needs detail", "warning");
      setMonitorsDrawerOpen(true);
      return true;
    }
    const gatewayId = String(requestBody.context?.gateway_id || state.selectedGatewayId || "").trim();
    await createMonitor({
      startNow: true,
      draft: {
        ...draft,
        prompt,
        agent_mode: requestBody.agent_mode || "llm_operator",
        gateway_id: gatewayId,
        conversation_id: state.conversationId || "",
        context: requestBody.context || {},
      },
    });
    removeThinkingIndicator();
    addMessage("assistant", "Monitor started", `${draft.title || "Monitor"} is running in a background terminal.`);
    setRunStatus("monitor started", "done");
    return true;
  } catch (error) {
    removeThinkingIndicator();
    addMessage("assistant", "Monitor failed", shortStatusError(error));
    setRunStatus("monitor failed", "failed");
    return true;
  }
}

async function loadSelectedEventRuns(eventId = state.selectedEventId) {
  const id = String(eventId || "").trim();
  if (!id) return;
  try {
    const response = await fetch(`/api/agent/events/${encodeURIComponent(id)}/runs?limit=100`, {
      cache: "no-store",
    });
    if (!response.ok) return;
    const payload = await response.json();
    if (String(state.selectedEventId || "") !== id) return;
    state.eventRuns[id] = Array.isArray(payload.runs) ? payload.runs : [];
    renderEventRuns();
  } catch {
    // Recent runs from the list endpoint are still useful if the full history refresh fails.
  }
}

async function loadEvents() {
  try {
    const response = await fetch("/api/agent/events", { cache: "no-store" });
    if (!response.ok) throw new Error(await response.text());
    const payload = await response.json();
    state.agentEventsEnabled = payload.enabled !== false;
    if (settingEventsEnabled) {
      settingEventsEnabled.checked = state.agentEventsEnabled;
    }
    state.events = Array.isArray(payload.events) ? payload.events : [];
    state.eventRuns = payload.runs && typeof payload.runs === "object" ? payload.runs : {};
    const liveEventIds = new Set(state.events.map((item) => String(item.event_id || "")).filter(Boolean));
    state.expandedEventIds.forEach((eventId) => {
      if (!liveEventIds.has(eventId)) {
        state.expandedEventIds.delete(eventId);
      }
    });
    if (state.selectedEventId && !eventById(state.selectedEventId)) {
      state.selectedEventId = "";
    }
    if (state.editingEventId && !eventById(state.editingEventId)) {
      state.editingEventId = "";
    }
    renderEvents();
  } catch (error) {
    if (eventsStatusSummary) {
      eventsStatusSummary.textContent = `Events unavailable: ${shortStatusError(error)}`;
    }
    showUiActionError({
      title: "Events unavailable",
      message: shortStatusError(error),
      fix: "Check the agent server connection, then refresh events again.",
    });
  }
}

function applyEventDraft(draft) {
  state.editingEventId = "";
  state.eventEditorContext = draft && draft.context && typeof draft.context === "object"
    ? { ...draft.context }
    : {};
  state.eventEditorEventKind = eventKindValue(draft);
  state.eventEditorNextRunAt = String(draft?.next_run_at || "").trim();
  openEventEditorPanel();
  if (state.eventEditorEventKind === "todo") {
    openEventSection(todoEventListCard);
  }
  if (eventTitle) eventTitle.value = String(draft?.title || "");
  if (eventPrompt) {
    const draftPrompt = String(draft?.prompt || "");
    const hasTypeinSummary = Array.isArray(state.eventEditorContext.operator_user_macro_summaries)
      && state.eventEditorContext.operator_user_macro_summaries.some(
        (item) => String(item?.kind || "").toLowerCase() === "typein",
      );
    eventPrompt.value = hasTypeinSummary && !/(^|\s)\/?typein\s*"/i.test(draftPrompt)
      ? `${draftPrompt} /typein "[redacted]"`
      : draftPrompt;
  }
  setEventWorkingDirectory(state.eventEditorContext.terminal_cwd || defaultEventWorkingDirectory());
  const parts = eventIntervalParts(draft?.interval_seconds || 3600, draft?.schedule_type || "interval");
  if (eventIntervalValue) eventIntervalValue.value = String(parts.value);
  if (eventIntervalUnit) eventIntervalUnit.value = parts.unit;
  if (eventStatus) eventStatus.value = "active";
  if (eventAutoApprove) eventAutoApprove.checked = draft?.auto_approve_confirmations !== false;
  if (eventActionType) eventActionType.value = String(draft?.action_type || "agent_prompt");
  if (eventScheduleType) eventScheduleType.value = String(draft?.schedule_type || "interval");
  if (eventNotificationMessage) {
    eventNotificationMessage.value = String(draft?.notification_message || "");
  }
  if (eventNotifySuccess) {
    eventNotifySuccess.checked = Array.isArray(draft?.notify_on) && draft.notify_on.includes("completed");
  }
  renderEventsList();
  updateEventControls();
}

async function saveEventFromEditor() {
  const payload = readEventPayload();
  if (!payload.prompt) {
    if (eventsStatusSummary) eventsStatusSummary.textContent = "Event prompt is required.";
    showUiActionError({
      title: "Event prompt required",
      message: "The event was not saved because it has no prompt or notification message.",
      fix: "Enter the prompt to run, or add a notification message for reminder-only events.",
      field: eventPrompt || eventNotificationMessage,
    });
    return;
  }
  const editingId = String(state.editingEventId || "").trim();
  const requestPayload = editingId ? { ...payload } : payload;
  if (editingId) {
    delete requestPayload.schedule_type;
  }
  try {
    const response = await fetch(
      editingId ? `/api/agent/events/${encodeURIComponent(editingId)}` : "/api/agent/events",
      {
        method: editingId ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(requestPayload),
      },
    );
    if (!response.ok) {
      const message = await response.text();
      if (eventsStatusSummary) eventsStatusSummary.textContent = message;
      showUiActionError({
        title: editingId ? "Event update failed" : "Event save failed",
        message: shortStatusError(message),
        fix: "Review the event title, prompt, schedule, and gateway, then save again.",
      });
      return;
    }
    const body = await response.json();
    if (body.event) {
      state.selectedEventId = body.event.event_id;
      state.editingEventId = body.event.event_id;
    }
    await loadEvents();
    const selected = eventById(state.selectedEventId);
    if (selected) {
      fillEventEditor(selected);
    }
  } catch (error) {
    const message = shortStatusError(error);
    if (eventsStatusSummary) eventsStatusSummary.textContent = message;
    showUiActionError({
      title: editingId ? "Event update failed" : "Event save failed",
      message,
      fix: "Check the event details and try saving again.",
    });
  }
}

async function updateEventStatus(eventId, status) {
  const id = String(eventId || "").trim();
  if (!id) return;
  try {
    const response = await fetch(`/api/agent/events/${encodeURIComponent(id)}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status }),
    });
    if (!response.ok) {
      const message = await response.text();
      if (eventsStatusSummary) eventsStatusSummary.textContent = message;
      showUiActionError({
        title: "Event update failed",
        message: shortStatusError(message),
        fix: "Refresh events and try changing the event status again.",
      });
      return;
    }
    await loadEvents();
    const selected = eventById(id);
    if (selected) {
      selectEvent(selected);
      if (state.editingEventId === id) {
        fillEventEditor(selected, { openEditor: false });
      }
    }
  } catch (error) {
    const message = shortStatusError(error);
    if (eventsStatusSummary) eventsStatusSummary.textContent = message;
    showUiActionError({
      title: "Event update failed",
      message,
      fix: "Refresh events and try changing the event status again.",
    });
  }
}

async function updateSelectedEventStatus(status) {
  await updateEventStatus(state.selectedEventId, status);
}

async function deleteSelectedEvent() {
  const id = String(state.selectedEventId || "").trim();
  if (!id) {
    showUiActionError({
      title: "No event selected",
      message: "There is no selected event to delete.",
      fix: "Select an event from the list before deleting.",
      field: eventsList || todoEventsList,
    });
    return;
  }
  await deleteEvent(id);
}

async function deleteEvent(eventId) {
  const id = String(eventId || "").trim();
  if (!id) return;
  try {
    const response = await fetch(`/api/agent/events/${encodeURIComponent(id)}`, { method: "DELETE" });
    if (!response.ok) {
      const message = await response.text();
      if (eventsStatusSummary) eventsStatusSummary.textContent = message;
      showUiActionError({
        title: "Event delete failed",
        message: shortStatusError(message),
        fix: "Refresh events and try deleting the event again.",
      });
      return;
    }
    if (state.selectedEventId === id || state.editingEventId === id) {
      state.selectedEventId = "";
      state.editingEventId = "";
      clearEventEditor();
    }
    await loadEvents();
  } catch (error) {
    const message = shortStatusError(error);
    if (eventsStatusSummary) eventsStatusSummary.textContent = message;
    showUiActionError({
      title: "Event delete failed",
      message,
      fix: "Refresh events and try deleting the event again.",
    });
  }
}

async function triggerSelectedEvent() {
  const id = String(state.selectedEventId || "").trim();
  if (!id) return;
  const response = await fetch(`/api/agent/events/${encodeURIComponent(id)}/trigger`, { method: "POST" });
  if (!response.ok) {
    if (eventsStatusSummary) eventsStatusSummary.textContent = await response.text();
    return;
  }
  const payload = await response.json();
  if (payload.request_id && payload.stream_url) {
    setEventsDrawerOpen(false);
    addMessage("assistant", "Scheduled event", `Running event ${payload.event?.title || id}.`);
    addThinkingIndicator();
    startTraceStream(payload.request_id, payload.stream_url);
  } else if (payload.notification) {
    const notification = Array.isArray(payload.notifications) ? payload.notifications[0] : null;
    if (notification) {
      upsertNotifications([notification], { showUnread: true });
    } else {
      showNotification({
        level: "info",
        title: payload.event?.title || "Notification delivered",
        message: "The scheduled notification was delivered.",
      });
    }
  }
  await loadEvents();
  await loadNotifications();
}

function appendEventDraftMessage(draftResponse) {
  removeThinkingIndicator();
  state.eventDrafts = Array.isArray(draftResponse?.drafts) ? draftResponse.drafts : [];
  const message = addMessage(
    "assistant",
    "Event draft",
    "I drafted scheduled event settings. Review and save before anything runs.",
  );
  const container = document.createElement("div");
  container.className = "event-draft-list";
  state.eventDrafts.forEach((draft, index) => {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "event-draft-row";
    const body = document.createElement("div");
    const title = document.createElement("strong");
    title.textContent = draft.title || `Draft ${index + 1}`;
    const meta = document.createElement("span");
    const draftSchedule = eventKindValue(draft) === "todo"
      ? "Todo (no schedule)"
      : draft.schedule_summary || eventIntervalLabel(draft.interval_seconds, draft.schedule_type);
    meta.textContent = `${draftSchedule} · ${draft.prompt || ""}`;
    body.append(title, meta);
    row.addEventListener("click", () => {
      applyEventDraft(draft);
      setEventsDrawerOpen(true);
    });
    row.append(body);
    container.append(row);
  });
  message.append(container);
  if (state.eventDrafts[0]) {
    applyEventDraft(state.eventDrafts[0]);
  }
  setEventsDrawerOpen(true);
}

async function maybeDraftScheduledEvents(prompt, requestBody) {
  if (state.agentEventsEnabled === false) {
    return false;
  }
  const browserTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  const requestContext = {
    ...(requestBody.context || {}),
    browser_timezone: browserTimezone,
  };
  if (!String(requestContext.timezone || "").trim()) {
    requestContext.timezone = browserTimezone;
  }
  try {
    const response = await fetchWithLlmActivity("/api/agent/events/from-prompt", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt,
        context: requestContext,
        agent_mode: requestBody.agent_mode || "standard",
        llm_model: requestBody.llm_model || "auto",
      }),
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    if (payload.is_schedule_request && Number(payload.created_count || 0) > 0) {
      removeThinkingIndicator();
      addMessage("assistant", "Event saved", String(payload.message || "Scheduled event saved."));
      setRunStatus("event saved", "done");
      await loadEvents();
      return true;
    }
    if (payload.is_schedule_request) {
      removeThinkingIndicator();
      addMessage(
        "assistant",
        "Event needs detail",
        String(payload.message || "I need more detail before saving this scheduled event."),
      );
      setRunStatus("event needs detail", "warning");
      return true;
    }
  } catch (error) {
    console.warn("Event recognition skipped:", error);
  }
  return false;
}

function parameterCsvArray(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function parameterByKey(key) {
  const normalized = String(key || "").trim().toLowerCase();
  return state.parameterEntries.find((entry) => String(entry?.key || "").toLowerCase() === normalized)
    || state.parameterEntries.find((entry) => String(entry?.normalized_key || "").toLowerCase() === normalized)
    || null;
}

function parameterValueContainsMask(value) {
  if (value === "••••") return true;
  if (Array.isArray(value)) return value.some(parameterValueContainsMask);
  if (value && typeof value === "object") {
    return Object.values(value).some(parameterValueContainsMask);
  }
  return false;
}

function openFullParameterEditor(key = "") {
  const selected = String(key || state.selectedParameterKey || parameterKeyInput?.value || "").trim();
  const url = selected
    ? `/parameter-editor?key=${encodeURIComponent(selected)}`
    : "/parameter-editor";
  window.open(url, "_blank", "noopener,noreferrer");
}

function openFullMemoryEditor(memoryId = "") {
  const selected = String(memoryId || state.selectedMemoryId || "").trim();
  const url = selected
    ? `/prompt-editor?mode=memories&key=${encodeURIComponent(selected)}`
    : "/prompt-editor?mode=memories";
  window.open(url, "_blank", "noopener,noreferrer");
}

function clearParameterEditor() {
  state.selectedParameterKey = "";
  state.parameterDraftContext = null;
  if (parameterKeyInput) parameterKeyInput.value = "";
  if (parameterDescriptionInput) parameterDescriptionInput.value = "";
  if (parameterValueJson) parameterValueJson.value = "{\n  \n}";
  if (parameterAliasesInput) parameterAliasesInput.value = "";
  if (parameterTagsInput) parameterTagsInput.value = "";
  if (parameterSensitiveInput) parameterSensitiveInput.checked = true;
  if (parameterAudit) parameterAudit.textContent = "";
  renderParametersList();
}

function parameterFieldPaths(schema, prefix = "") {
  if (!schema || typeof schema !== "object" || Array.isArray(schema)) {
    return prefix ? [prefix] : [];
  }
  const paths = [];
  for (const [key, value] of Object.entries(schema)) {
    const next = prefix ? `${prefix}.${key}` : key;
    if (value && typeof value === "object" && !Array.isArray(value)) {
      paths.push(...parameterFieldPaths(value, next));
    } else {
      paths.push(next);
    }
  }
  return paths;
}

function populateParameterEditor(entry, options = {}) {
  if (!entry || typeof entry !== "object") return;
  state.selectedParameterKey = String(entry.normalized_key || entry.key || "");
  state.parameterDraftContext = null;
  if (parameterKeyInput) parameterKeyInput.value = String(entry.key || "");
  if (parameterDescriptionInput) parameterDescriptionInput.value = String(entry.description || "");
  const value = options.valueJsonOverride && typeof options.valueJsonOverride === "object"
    ? options.valueJsonOverride
    : (entry.masked_value_json && typeof entry.masked_value_json === "object" ? entry.masked_value_json : {});
  if (parameterValueJson) parameterValueJson.value = JSON.stringify(value, null, 2);
  if (parameterAliasesInput) parameterAliasesInput.value = Array.isArray(entry.aliases) ? entry.aliases.join(", ") : "";
  if (parameterTagsInput) parameterTagsInput.value = Array.isArray(entry.tags) ? entry.tags.join(", ") : "";
  if (parameterSensitiveInput) parameterSensitiveInput.checked = entry.sensitive !== false;
  renderParametersList();
  void loadParameterAudit(entry.normalized_key || entry.key || "");
}

function readParameterEditorPayload({ update = false } = {}) {
  const key = String(parameterKeyInput?.value || "").trim();
  const description = String(parameterDescriptionInput?.value || "").trim();
  const aliases = parameterCsvArray(parameterAliasesInput?.value);
  const tags = parameterCsvArray(parameterTagsInput?.value);
  let valueJson = {};
  try {
    valueJson = JSON.parse(String(parameterValueJson?.value || "{}"));
  } catch {
    addMessage("assistant", "Parameter Store", "Value JSON must parse as an object before saving.");
    showUiActionError({
      title: "Parameter JSON invalid",
      message: "The parameter was not saved because the value JSON could not be parsed.",
      fix: "Correct the JSON object in the value field, then save again.",
      field: parameterValueJson,
    });
    return null;
  }
  if (!valueJson || typeof valueJson !== "object" || Array.isArray(valueJson)) {
    addMessage("assistant", "Parameter Store", "Value JSON must be an object.");
    showUiActionError({
      title: "Parameter value must be an object",
      message: "The parameter was not saved because the value is not a JSON object.",
      fix: "Use an object such as { \"token\": \"...\" }, then save again.",
      field: parameterValueJson,
    });
    return null;
  }
  const payload = {
    key,
    description,
    aliases,
    tags,
    sensitive: parameterSensitiveInput?.checked !== false,
  };
  if (!update || !parameterValueContainsMask(valueJson)) {
    payload.value_json = valueJson;
  }
  return payload;
}

function renderParametersStats() {
  if (!parametersStats) return;
  const stats = state.parameterStats || {
    total: state.parameterEntries.length,
    filtered: state.parameterEntries.length,
    sensitive: state.parameterEntries.filter((entry) => entry.sensitive !== false).length,
    total_uses: state.parameterEntries.reduce((total, entry) => total + Number(entry.use_count || 0), 0),
  };
  const items = [
    ["Total", stats.total],
    ["Shown", stats.filtered],
    ["Sensitive", stats.sensitive],
    ["Uses", stats.total_uses],
  ];
  parametersStats.replaceChildren();
  for (const [label, value] of items) {
    const card = document.createElement("div");
    card.className = "memory-stat-card";
    const number = document.createElement("strong");
    number.textContent = String(Number(value || 0));
    const caption = document.createElement("span");
    caption.textContent = label;
    card.append(number, caption);
    parametersStats.append(card);
  }
}

function renderParametersList() {
  renderParametersStats();
  if (parameterEntryPicker) {
    const selected = state.selectedParameterKey || "";
    parameterEntryPicker.replaceChildren();
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = state.parameterEntries.length ? "Select a parameter" : "No parameters";
    parameterEntryPicker.append(placeholder);
    for (const entry of state.parameterEntries) {
      const option = document.createElement("option");
      option.value = entry.normalized_key || entry.key || "";
      option.textContent = entry.key || entry.normalized_key || "parameter";
      parameterEntryPicker.append(option);
    }
    parameterEntryPicker.value = selected;
  }
}

async function loadParameters() {
  const params = new URLSearchParams();
  const q = String(parametersSearch?.value || "").trim();
  if (q) params.set("q", q);
  const response = await fetch(`/api/agent/parameters?${params.toString()}`, { cache: "no-store" });
  if (!response.ok) {
    state.parameterEntries = [];
    state.parameterStats = null;
    renderParametersList();
    return;
  }
  const payload = await response.json();
  state.parameterEntries = Array.isArray(payload.entries) ? payload.entries : [];
  state.parameterStats = payload.stats && typeof payload.stats === "object" ? payload.stats : null;
  renderParametersList();
}

async function loadParameterAudit(key) {
  if (!parameterAudit) return;
  if (!key) {
    parameterAudit.textContent = "";
    return;
  }
  const response = await fetch(`/api/agent/parameters/${encodeURIComponent(key)}?include_audit=true`, {
    cache: "no-store",
  });
  if (!response.ok) {
    parameterAudit.textContent = "Audit unavailable.";
    return;
  }
  const payload = await response.json();
  parameterAudit.textContent = JSON.stringify(payload.audit_events || [], null, 2);
}

async function saveParameterEntry() {
  const selected = String(state.selectedParameterKey || "");
  const payload = readParameterEditorPayload({ update: Boolean(selected) });
  if (!payload) return;
  if (!payload.key) {
    showUiActionError({
      title: "Parameter key required",
      message: "The parameter was not saved because the key is missing.",
      fix: "Enter a parameter key, then save again.",
      field: parameterKeyInput,
    });
    return;
  }
  if (!selected && !payload.value_json) {
    addMessage("assistant", "Parameter Store", "New parameters need a non-empty JSON object.");
    showUiActionError({
      title: "Parameter value required",
      message: "New parameters need a value_json object.",
      fix: "Enter a non-empty JSON object in the value field, then save again.",
      field: parameterValueJson,
    });
    return;
  }
  try {
    const response = await fetch(
      selected
        ? `/api/agent/parameters/${encodeURIComponent(selected)}`
        : "/api/agent/parameters",
      {
        method: selected ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      },
    );
    if (!response.ok) {
      const message = await response.text();
      addMessage("assistant", "Parameter Store", message);
      showUiActionError({
        title: selected ? "Parameter update failed" : "Parameter save failed",
        message: shortStatusError(message),
        fix: "Review the key and value JSON, then save again.",
      });
      return;
    }
    const result = await response.json();
    populateParameterEditor(result.entry);
    invalidatePromptParameterShortcuts();
    await loadParameters();
  } catch (error) {
    const message = shortStatusError(error);
    addMessage("assistant", "Parameter Store", message);
    showUiActionError({
      title: selected ? "Parameter update failed" : "Parameter save failed",
      message,
      fix: "Check the parameter fields and try saving again.",
    });
  }
}

async function deleteSelectedParameter() {
  const key = String(state.selectedParameterKey || parameterKeyInput?.value || "").trim();
  if (!key) {
    showUiActionError({
      title: "No parameter selected",
      message: "There is no parameter selected to delete.",
      fix: "Select a parameter or enter its key before deleting.",
      field: parameterEntryPicker || parameterKeyInput,
    });
    return;
  }
  try {
    const response = await fetch(`/api/agent/parameters/${encodeURIComponent(key)}`, {
      method: "DELETE",
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    clearParameterEditor();
    invalidatePromptParameterShortcuts();
    await loadParameters();
  } catch (error) {
    showUiActionError({
      title: "Parameter delete failed",
      message: shortStatusError(error),
      fix: "Refresh the parameter list and try deleting again.",
    });
  }
}

async function revealSelectedParameter() {
  const key = String(state.selectedParameterKey || parameterKeyInput?.value || "").trim();
  if (!key) {
    showUiActionError({
      title: "No parameter selected",
      message: "There is no parameter selected to reveal.",
      fix: "Select a parameter or enter its key before revealing the value.",
      field: parameterEntryPicker || parameterKeyInput,
    });
    return;
  }
  try {
    const response = await fetch(`/api/agent/parameters/${encodeURIComponent(key)}/reveal`, {
      method: "POST",
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    populateParameterEditor(payload.entry, { valueJsonOverride: payload.value_json });
  } catch (error) {
    addMessage("assistant", "Parameter Store", "Reveal failed.");
    showUiActionError({
      title: "Parameter reveal failed",
      message: shortStatusError(error),
      fix: "Refresh the parameter list and try revealing the value again.",
    });
  }
}

function looksLikeParameterStorePrompt(prompt) {
  const text = String(prompt || "");
  return looksLikeParameterStoreSetPrompt(text)
    || /\b(?:parameter\s+store|param\s+store|parameters\s+store)\b/i.test(text)
    || /\b(?:from|in)\s+(?:the\s+)?(?:parameter\s+)?store\b/i.test(text)
    || /\b(?:stored|saved)\s+(?:in|under)\b/i.test(text)
    || /^\/(?:parameter|param|store)\b/i.test(String(prompt || ""));
}

function looksLikeParameterStoreSetPrompt(prompt) {
  const text = String(prompt || "");
  const writeVerbMatch = /\b(store|save|keep|stash)\b[\s\S]{0,180}\b(?:parameter|param|credential|password|passphrase|secret|token|connection(?:\s+string)?|database|db|datasource|config|key|info|information)\b/ig;
  let match;
  let hasWriteVerb = false;
  while ((match = writeVerbMatch.exec(text)) !== null) {
    const verb = String(match[1] || "").toLowerCase();
    const prefix = text.slice(Math.max(0, match.index - 16), match.index).toLowerCase();
    if (verb === "store" && /(?:parameter|param)\s+$/.test(prefix)) {
      continue;
    }
    hasWriteVerb = true;
    break;
  }
  return /^\/(?:parameter|param|store)\b/i.test(text)
    || hasWriteVerb
    || /\b(?:store|save)\s+(?:as|to|in|into|under)\s+(?:the\s+)?(?:parameter\s+)?store\b/i.test(text)
    || /\badd\b[\s\S]{0,120}\b(?:credential|password|passphrase|secret|token|connection(?:\s+string)?|database|db|datasource|config\s+(?:value|json|entry)|parameter\s+(?:called|named|key|entry)|param\s+(?:called|named|key|entry))\b/i.test(text)
    || /\b(?:create|set|update)\b[\s\S]{0,120}\b(?:parameter|param|credential|password|secret|token)\b[\s\S]{0,80}\b(?:store|value|json|key)\b/i.test(text);
}

function applyParameterDraft(draft) {
  if (!draft || typeof draft !== "object") return;
  clearParameterEditor();
  state.parameterDraftContext = draft;
  if (parameterKeyInput) parameterKeyInput.value = String(draft.key || "");
  if (parameterDescriptionInput) parameterDescriptionInput.value = String(draft.description || "");
  const value = draft.value && typeof draft.value === "object" && !Array.isArray(draft.value) ? draft.value : {};
  if (parameterValueJson) parameterValueJson.value = JSON.stringify(value, null, 2);
  if (parameterAliasesInput) parameterAliasesInput.value = Array.isArray(draft.aliases) ? draft.aliases.join(", ") : "";
  if (parameterTagsInput) parameterTagsInput.value = Array.isArray(draft.tags) ? draft.tags.join(", ") : "";
  if (parameterSensitiveInput) parameterSensitiveInput.checked = draft.sensitive !== false;
}

async function maybeDraftParameterStore(prompt, requestBody) {
  if (!looksLikeParameterStorePrompt(prompt)) {
    return false;
  }
  try {
    const response = await fetch("/api/agent/parameters/draft", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt,
        context: requestBody?.context || {},
        agent_mode: requestBody?.agent_mode || "llm_operator",
        llm_model: requestBody?.llm_model || "",
      }),
    });
    if (!response.ok) {
      return false;
    }
    const payload = await response.json();
    if (!payload.is_parameter_request) {
      return false;
    }
    removeThinkingIndicator();
    const draft = Array.isArray(payload.drafts) && payload.drafts.length ? payload.drafts[0] : null;
    if (draft) {
      applyParameterDraft(draft);
      setParametersDrawerOpen(true);
      addMessage("assistant", "Parameter draft ready", "Review the extracted parameter entry, edit if needed, then save it.");
      setRunStatus("parameter draft", "done");
      return true;
    }
    addMessage("assistant", "Parameter needs detail", "I need a key and a JSON object before saving this parameter.");
    setRunStatus("parameter needs detail", "warning");
    return true;
  } catch (error) {
    if (!looksLikeParameterStoreSetPrompt(prompt)) {
      return false;
    }
    removeThinkingIndicator();
    addMessage("assistant", "Parameter draft failed", shortStatusError(error));
    setRunStatus("parameter failed", "failed");
    return true;
  }
}

function looksLikeDiscoverDbPrompt(prompt) {
  return /^\/discoverdb\b/i.test(String(prompt || "").trim());
}

function redactDiscoverDbPrompt(prompt) {
  return String(prompt || "")
    .replace(/\b(password\s*=\s*)(?:"[^"]*"|'[^']*'|\S+)/ig, "$1[redacted]")
    .replace(/\b(user\s*=\s*)(?:"[^"]*"|'[^']*'|\S+)/ig, "$1[redacted]");
}

function discoverDbPreviewMarkdown(payload) {
  const discovered = Array.isArray(payload?.discovered) ? payload.discovered : [];
  const createDrafts = discovered.filter((draft) => String(draft?.operation || "create").toLowerCase() !== "update");
  const updateDrafts = discovered.filter((draft) => String(draft?.operation || "").toLowerCase() === "update");
  const skipped = Array.isArray(payload?.skipped_existing) ? payload.skipped_existing : [];
  const warnings = Array.isArray(payload?.warnings) ? payload.warnings : [];
  const lines = [];
  if (createDrafts.length) {
    lines.push(`Found ${createDrafts.length} new database profile${createDrafts.length === 1 ? "" : "s"} ready to save:`);
    createDrafts.forEach((draft) => {
      const dbname = draft?.value_json?.dbname || draft?.key || "database";
      lines.push(`- ${draft?.key || dbname} (${dbname})`);
    });
  }
  if (updateDrafts.length) {
    if (lines.length) lines.push("");
    lines.push(`Found ${updateDrafts.length} existing profile refresh${updateDrafts.length === 1 ? "" : "es"} ready to save:`);
    updateDrafts.forEach((draft) => {
      const dbname = draft?.value_json?.dbname || draft?.key || "database";
      lines.push(`- ${draft?.key || dbname} (${dbname})`);
    });
  }
  if (!createDrafts.length && !updateDrafts.length) {
    lines.push("No database profile changes were discovered.");
  } else {
    lines.push("");
    lines.push("Schema and relation metadata will be refreshed when saved.");
  }
  if (skipped.length) {
    lines.push("");
    lines.push(`Skipped ${skipped.length} existing profile${skipped.length === 1 ? "" : "s"}:`);
    skipped.forEach((item) => {
      lines.push(`- ${item?.key || item?.normalized_key || "existing profile"}`);
    });
  }
  if (warnings.length) {
    lines.push("");
    lines.push("Warnings:");
    warnings.forEach((warning) => lines.push(`- ${warning}`));
  }
  return lines.join("\n");
}

function appendDiscoverDbCommitAction(message, payload) {
  const drafts = Array.isArray(payload?.discovered) ? payload.discovered : [];
  if (!drafts.length || !message) {
    return;
  }
  const button = document.createElement("button");
  button.type = "button";
  button.className = "message-inline-action";
  button.textContent = `Save ${drafts.length} DB profile${drafts.length === 1 ? "" : "s"}`;
  button.addEventListener("click", async () => {
    button.disabled = true;
    button.textContent = "Saving...";
    try {
      const response = await fetch("/api/agent/databases/discover/commit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ drafts }),
      });
      if (!response.ok) {
        throw new Error(await response.text());
      }
      const result = await response.json();
      const created = Array.isArray(result?.created) ? result.created : [];
      const updated = Array.isArray(result?.updated) ? result.updated : [];
      const skipped = Array.isArray(result?.skipped_existing) ? result.skipped_existing : [];
      const errors = Array.isArray(result?.errors) ? result.errors : [];
      if (result?.status === "error") {
        throw new Error(errors.join("\n") || result?.error || "Database profile save failed.");
      }
      const lines = [
        `Saved ${created.length} new database profile${created.length === 1 ? "" : "s"}.`,
      ];
      if (updated.length) {
        lines.push(`Refreshed ${updated.length} existing profile${updated.length === 1 ? "" : "s"}.`);
      }
      if (skipped.length) {
        lines.push(`Skipped ${skipped.length} existing profile${skipped.length === 1 ? "" : "s"}.`);
      }
      if (errors.length) {
        lines.push("");
        lines.push("Errors:");
        errors.forEach((error) => lines.push(`- ${error}`));
      }
      addMessage("assistant", "Database profiles saved", lines.join("\n"));
      invalidatePromptParameterShortcuts();
      await loadParameters();
      setParametersDrawerOpen(true);
      setRunStatus("database profiles saved", errors.length ? "warning" : "done");
      button.textContent = "Saved";
    } catch (error) {
      button.disabled = false;
      button.textContent = `Save ${drafts.length} DB profile${drafts.length === 1 ? "" : "s"}`;
      addMessage("assistant", "Database profile save failed", shortStatusError(error));
      setRunStatus("database save failed", "failed");
    }
  });
  message.append(button);
}

async function maybeDiscoverDbFromChat(prompt) {
  if (!looksLikeDiscoverDbPrompt(prompt)) {
    return false;
  }
  try {
    const response = await fetch("/api/agent/databases/discover", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ prompt }),
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const payload = await response.json();
    removeThinkingIndicator();
    if (payload?.status !== "preview") {
      const errors = Array.isArray(payload?.errors) ? payload.errors.join("\n") : "";
      addMessage("assistant", "Database discovery failed", errors || payload?.error || "Discovery failed.");
      setRunStatus("database discovery failed", "failed");
      return true;
    }
    const message = addMessage("assistant", "Database discovery preview", discoverDbPreviewMarkdown(payload));
    appendDiscoverDbCommitAction(message, payload);
    setRunStatus("database discovery preview", "done");
    return true;
  } catch (error) {
    removeThinkingIndicator();
    addMessage("assistant", "Database discovery failed", shortStatusError(error));
    setRunStatus("database discovery failed", "failed");
    return true;
  }
}

function memoryTagsArray(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function memoryExamplesArray(value) {
  return String(value || "")
    .split(/\r?\n/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function memoryEntryById(memoryId) {
  return (
    state.memoryEntries.find((entry) => entry.memory_id === memoryId)
    || state.memoryPickerEntries.find((entry) => entry.memory_id === memoryId)
    || null
  );
}

function clearMemoryEditor() {
  state.selectedMemoryId = null;
  state.selectedMemoryRequestId = String(state.requestId || "");
  state.memoryDraftContext = null;
  if (memoryInstruction) memoryInstruction.value = "";
  if (memorySummary) memorySummary.value = "";
  if (memoryKind) memoryKind.value = "task_memory";
  if (memoryScope) memoryScope.value = "global";
  if (memoryModelName) memoryModelName.value = String(state.activeModelName || "").trim();
  if (memoryModelFamily) memoryModelFamily.value = "";
  if (memoryTaskType) memoryTaskType.value = "";
  if (memoryToolType) memoryToolType.value = "";
  if (memoryIntentType) memoryIntentType.value = "";
  if (memoryValidatorErrorType) memoryValidatorErrorType.value = "";
  if (memorySafeExamples) memorySafeExamples.value = "";
  if (memoryBlockedExamples) memoryBlockedExamples.value = "";
  if (memoryTags) memoryTags.value = "";
  if (memoryAudit) memoryAudit.textContent = "";
  renderMemoryList();
}

function readMemoryPayload() {
  return {
    instruction: String(memoryInstruction?.value || "").trim(),
    summary: String(memorySummary?.value || "").trim(),
    status: "active",
    memory_kind: String(memoryKind?.value || "task_memory"),
    scope: String(memoryScope?.value || "global"),
    model_name: String(memoryModelName?.value || "").trim(),
    model_family: String(memoryModelFamily?.value || "").trim(),
    task_type: String(memoryTaskType?.value || "").trim(),
    tool_type: String(memoryToolType?.value || "").trim(),
    intent_type: String(memoryIntentType?.value || "").trim(),
    validator_error_type: String(memoryValidatorErrorType?.value || "").trim(),
    safe_examples: memoryExamplesArray(memorySafeExamples?.value),
    blocked_examples: memoryExamplesArray(memoryBlockedExamples?.value),
    tags: memoryTagsArray(memoryTags?.value),
    provenance: "manual",
    request_id: String(state.selectedMemoryRequestId || state.requestId || ""),
    rationale: "User-authored memory from the Agent UI.",
  };
}

function readMemoryUpdatePayload() {
  const payload = readMemoryPayload();
  return {
    instruction: payload.instruction,
    summary: payload.summary,
    memory_kind: payload.memory_kind,
    scope: payload.scope,
    model_name: payload.model_name,
    model_family: payload.model_family,
    task_type: payload.task_type,
    tool_type: payload.tool_type,
    intent_type: payload.intent_type,
    validator_error_type: payload.validator_error_type,
    safe_examples: payload.safe_examples,
    blocked_examples: payload.blocked_examples,
    tags: payload.tags,
    rationale: payload.rationale,
  };
}

function populateMemoryEditor(entry) {
  state.selectedMemoryId = entry?.memory_id || null;
  state.selectedMemoryRequestId = entry?.request_id || "";
  state.memoryDraftContext = null;
  if (memoryInstruction) memoryInstruction.value = entry?.instruction || "";
  if (memorySummary) memorySummary.value = entry?.summary || "";
  if (memoryKind) memoryKind.value = entry?.memory_kind || "task_memory";
  if (memoryScope) memoryScope.value = entry?.scope || "global";
  if (memoryModelName) memoryModelName.value = entry?.model_name || "";
  if (memoryModelFamily) memoryModelFamily.value = entry?.model_family || "";
  if (memoryTaskType) memoryTaskType.value = entry?.task_type || "";
  if (memoryToolType) memoryToolType.value = entry?.tool_type || "";
  if (memoryIntentType) memoryIntentType.value = entry?.intent_type || "";
  if (memoryValidatorErrorType) memoryValidatorErrorType.value = entry?.validator_error_type || "";
  if (memorySafeExamples) memorySafeExamples.value = Array.isArray(entry?.safe_examples) ? entry.safe_examples.join("\n") : "";
  if (memoryBlockedExamples) memoryBlockedExamples.value = Array.isArray(entry?.blocked_examples) ? entry.blocked_examples.join("\n") : "";
  if (memoryTags) memoryTags.value = Array.isArray(entry?.tags) ? entry.tags.join(", ") : "";
  renderMemoryList();
  void loadMemoryAudit(entry?.memory_id || "");
}

function memoryStatsPayload() {
  const fallback = {
    total: state.memoryEntries.length,
    filtered: state.memoryEntries.length,
    picker: state.memoryPickerEntries.length,
    active: 0,
    proposed: 0,
    retired: 0,
    pending_proposals: state.memoryProposals.length,
    total_uses: 0,
  };
  for (const entry of state.memoryEntries) {
    const status = String(entry?.status || "");
    if (status in fallback) {
      fallback[status] += 1;
    }
    fallback.total_uses += Number(entry?.use_count || 0);
  }
  return state.memoryStats && typeof state.memoryStats === "object"
    ? { ...fallback, ...state.memoryStats }
    : fallback;
}

function renderMemoryStats() {
  if (!memoryStats) return;
  const stats = memoryStatsPayload();
  const items = [
    ["Active", stats.active],
    ["Shown", stats.filtered],
    ["Retired", stats.retired],
    ["Uses", stats.total_uses],
  ];
  memoryStats.replaceChildren();
  for (const [label, value] of items) {
    const card = document.createElement("div");
    card.className = "memory-stat-card";
    const number = document.createElement("strong");
    number.textContent = String(Number(value || 0));
    const caption = document.createElement("span");
    caption.textContent = label;
    card.append(number, caption);
    memoryStats.append(card);
  }
}

function renderMemoryPicker() {
  if (!memoryEntryPicker) return;
  memoryEntryPicker.replaceChildren();
  const pickerEntries = state.memoryPickerEntries.length
    ? state.memoryPickerEntries
    : state.memoryEntries;
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = pickerEntries.length
    ? `Select a memory... (${pickerEntries.length})`
    : "No memories match this view";
  memoryEntryPicker.append(placeholder);
  for (const entry of pickerEntries) {
    const option = document.createElement("option");
    option.value = entry.memory_id || "";
    option.textContent = entry.summary || entry.instruction || "Untitled memory";
    memoryEntryPicker.append(option);
  }
  memoryEntryPicker.value = state.selectedMemoryId || "";
}

function renderMemoryList() {
  renderMemoryStats();
  renderMemoryPicker();
  if (!memoryList) return;
  memoryList.replaceChildren();
  if (!state.memoryEntries.length) {
    const emptyNode = document.createElement("div");
    emptyNode.className = "empty-state";
    emptyNode.textContent = "No memories match this filter.";
    memoryList.append(emptyNode);
    return;
  }
  state.memoryEntries.forEach((entry) => {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "memory-row";
    if (entry.memory_id === state.selectedMemoryId) row.classList.add("selected");
    const title = document.createElement("strong");
    title.textContent = entry.summary || entry.instruction || "Untitled memory";
    const meta = document.createElement("span");
    meta.textContent = [
      entry.memory_kind || "task_memory",
      entry.status,
      entry.scope,
      entry.model_name || entry.model_family || "global",
      entry.validator_error_type,
      (entry.tags || []).join(", "),
    ].filter(Boolean).join(" · ");
    row.append(title, meta);
    row.addEventListener("click", () => populateMemoryEditor(entry));
    memoryList.append(row);
  });
}

function renderMemoryProposals() {
  if (!memoryProposals) return;
  memoryProposals.replaceChildren();
  if (!state.memoryProposals.length) {
    const emptyNode = document.createElement("div");
    emptyNode.className = "empty-state";
    emptyNode.textContent = "No pending memory proposals.";
    memoryProposals.append(emptyNode);
    return;
  }
  state.memoryProposals.forEach((proposal) => {
    const row = document.createElement("div");
    row.className = "memory-proposal-row";
    const text = document.createElement("div");
    const instruction = proposal?.draft?.instruction || proposal.rationale || proposal.proposal_type;
    const kind = proposal?.draft?.memory_kind || "task_memory";
    text.textContent = `${proposal.proposal_type} · ${kind}: ${instruction}`;
    const apply = document.createElement("button");
    apply.className = "settings-action-button";
    apply.type = "button";
    apply.textContent = "Apply";
    apply.addEventListener("click", () => applyMemoryProposal(proposal.proposal_id));
    row.append(text, apply);
    memoryProposals.append(row);
  });
}

async function loadMemory() {
  const params = new URLSearchParams();
  const status = String(memoryStatusFilter?.value || "active");
  const q = String(memorySearch?.value || "").trim();
  const kind = String(memoryKindFilter?.value || "").trim();
  const scope = String(memoryScopeFilter?.value || "").trim();
  const modelFamily = String(memoryModelFamilyFilter?.value || "").trim();
  const taskType = String(memoryTaskFilter?.value || "").trim();
  const toolType = String(memoryToolFilter?.value || "").trim();
  const intentType = String(memoryIntentFilter?.value || "").trim();
  const validatorErrorType = String(memoryValidatorErrorFilter?.value || "").trim();
  const tag = String(memoryTagFilter?.value || "").trim();
  if (status) params.set("status", status);
  if (q) params.set("q", q);
  if (kind) params.set("memory_kind", kind);
  if (scope) params.set("scope", scope);
  if (modelFamily) params.set("model_family", modelFamily);
  if (taskType) params.set("task_type", taskType);
  if (toolType) params.set("tool_type", toolType);
  if (intentType) params.set("intent_type", intentType);
  if (validatorErrorType) params.set("validator_error_type", validatorErrorType);
  if (tag) params.set("tag", tag);
  const response = await fetch(`/api/agent/memory?${params.toString()}`, { cache: "no-store" });
  if (!response.ok) {
    state.memoryEntries = [];
    state.memoryPickerEntries = [];
    state.memoryProposals = [];
    state.memoryStats = null;
    renderMemoryList();
    renderMemoryProposals();
    return;
  }
  const payload = await response.json();
  state.memoryEntries = Array.isArray(payload.entries) ? payload.entries : [];
  state.memoryPickerEntries = Array.isArray(payload.picker_entries)
    ? payload.picker_entries
    : state.memoryEntries;
  state.memoryProposals = Array.isArray(payload.proposals) ? payload.proposals : [];
  state.memoryStats = payload.stats && typeof payload.stats === "object" ? payload.stats : null;
  renderMemoryList();
  renderMemoryProposals();
}

async function loadMemoryAudit(memoryId) {
  if (!memoryAudit) return;
  if (!memoryId) {
    memoryAudit.textContent = "";
    return;
  }
  const response = await fetch(`/api/agent/memory/${encodeURIComponent(memoryId)}/audit`, {
    cache: "no-store",
  });
  if (!response.ok) {
    memoryAudit.textContent = "Audit unavailable.";
    return;
  }
  const payload = await response.json();
  memoryAudit.textContent = JSON.stringify(payload.events || [], null, 2);
}

async function saveMemoryEntry() {
  const selectedId = state.selectedMemoryId;
  const payload = selectedId ? readMemoryUpdatePayload() : readMemoryPayload();
  if (!payload.instruction) {
    showUiActionError({
      title: "Memory instruction required",
      message: "The memory was not saved because the instruction is empty.",
      fix: "Enter the instruction or lesson the agent should remember, then save again.",
      field: memoryInstruction,
    });
    return;
  }
  try {
    const response = await fetch(
      selectedId
        ? `/api/agent/memory/${encodeURIComponent(selectedId)}`
        : "/api/agent/memory",
      {
        method: selectedId ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      },
    );
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const result = await response.json();
    populateMemoryEditor(result.entry);
    await loadMemory();
  } catch (error) {
    showUiActionError({
      title: selectedId ? "Memory update failed" : "Memory save failed",
      message: shortStatusError(error),
      fix: "Review the memory instruction and metadata, then save again.",
    });
  }
}

async function setSelectedMemoryStatus(action) {
  if (!state.selectedMemoryId) {
    showUiActionError({
      title: "No memory selected",
      message: "There is no selected memory to update.",
      fix: "Select a memory entry before changing its status.",
      field: memoryEntryPicker,
    });
    return;
  }
  try {
    const response = await fetch(
      `/api/agent/memory/${encodeURIComponent(state.selectedMemoryId)}/${action}`,
      { method: "POST" },
    );
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const result = await response.json();
    populateMemoryEditor(result.entry);
    await loadMemory();
  } catch (error) {
    showUiActionError({
      title: "Memory update failed",
      message: shortStatusError(error),
      fix: "Refresh memories and try the status change again.",
    });
  }
}

async function proposeMemoryFromFeedback(feedbackTarget = "memory") {
  const feedback = String(memoryFeedback?.value || "").trim();
  if (!feedback) {
    showUiActionError({
      title: "Feedback note required",
      message: "No feedback was submitted because the note is empty.",
      fix: "Add feedback explaining what should be remembered, then digest again.",
      field: memoryFeedback,
    });
    return;
  }
  const draftContext = state.memoryDraftContext && typeof state.memoryDraftContext === "object"
    ? state.memoryDraftContext
    : {};
  if (memoryProposals) {
    memoryProposals.textContent = feedbackTarget === "validation_policy"
      ? "Digesting validation policy..."
      : "Digesting feedback...";
  }
  try {
    const response = await postMemoryFeedbackJson(
      "/api/agent/memory/feedback",
      {
        feedback,
        feedback_target: feedbackTarget,
        ...memoryFeedbackEndpointContext(),
        prompt: String(draftContext.prompt || ""),
        request_id: state.selectedMemoryRequestId || draftContext.request_id || state.requestId || "",
        model_name: memoryModelName?.value || draftContext.model_name || state.engineModelName || state.activeModelName || "",
        task_type: memoryTaskType?.value || "",
        tool_type: memoryToolType?.value || "",
        intent_type: memoryIntentType?.value || "",
        validator_error_type: memoryValidatorErrorType?.value || "",
      },
    );
    if (!response.ok) {
      const message = await response.text();
      if (memoryProposals) memoryProposals.textContent = "Feedback proposal failed.";
      showUiActionError({
        title: "Feedback proposal failed",
        message: shortStatusError(message),
        fix: "Edit the feedback note and try digesting it again.",
      });
      return;
    }
    if (memoryFeedback) memoryFeedback.value = "";
    await loadMemory();
  } catch (error) {
    if (memoryProposals) {
      memoryProposals.textContent = `Feedback proposal failed: ${shortStatusError(error)}`;
    }
    showUiActionError({
      title: "Feedback proposal failed",
      message: shortStatusError(error),
      fix: "Edit the feedback note and try digesting it again.",
    });
  }
}

function applyMemoryDraft(draft) {
  if (!draft || typeof draft !== "object") return;
  if (memoryInstruction && draft.instruction) memoryInstruction.value = String(draft.instruction || "");
  if (memorySummary && draft.summary) memorySummary.value = String(draft.summary || "");
  if (memoryKind && draft.memory_kind) memoryKind.value = String(draft.memory_kind || "task_memory");
  if (memoryScope && draft.scope) memoryScope.value = String(draft.scope || "global");
  if (memoryModelName && draft.model_name) memoryModelName.value = String(draft.model_name || "");
  if (memoryModelFamily && draft.model_family) memoryModelFamily.value = String(draft.model_family || "");
  if (memoryTaskType && draft.task_type) memoryTaskType.value = String(draft.task_type || "");
  if (memoryToolType && draft.tool_type) memoryToolType.value = String(draft.tool_type || "");
  if (memoryIntentType && draft.intent_type) memoryIntentType.value = String(draft.intent_type || "");
  if (memoryValidatorErrorType && draft.validator_error_type) memoryValidatorErrorType.value = String(draft.validator_error_type || "");
  if (memorySafeExamples && Array.isArray(draft.safe_examples)) memorySafeExamples.value = draft.safe_examples.join("\n");
  if (memoryBlockedExamples && Array.isArray(draft.blocked_examples)) memoryBlockedExamples.value = draft.blocked_examples.join("\n");
  if (memoryTags && Array.isArray(draft.tags)) memoryTags.value = draft.tags.join(", ");
}

async function hydrateMemoryDraftFromContext(context) {
  const payload = {
    prompt: String(context?.prompt || ""),
    final_response: String(context?.final_response || ""),
    request_id: String(context?.request_id || ""),
    model_name: String(context?.model_name || state.engineModelName || state.activeModelName || ""),
  };
  if (!payload.prompt && !payload.final_response && !payload.request_id) {
    return;
  }
  try {
    const response = await fetchWithLlmActivity("/api/agent/memory/context", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!response.ok) {
      return;
    }
    const result = await response.json();
    applyMemoryDraft(result.draft || {});
  } catch {
    // Memory editing remains useful even when the LLM prefill endpoint is unavailable.
  }
}

function openMemoryForResponseContext(context) {
  const safeContext = {
    request_id: String(context?.request_id || state.requestId || ""),
    prompt: String(context?.prompt || ""),
    final_response: String(context?.final_response || ""),
    model_name: String(context?.model_name || state.engineModelName || state.activeModelName || ""),
  };
  setMemoryDrawerOpen(true);
  clearMemoryEditor();
  state.selectedMemoryRequestId = safeContext.request_id;
  state.memoryDraftContext = safeContext;
  if (memoryModelName && safeContext.model_name) {
    memoryModelName.value = safeContext.model_name;
  }
  if (memoryFeedback) {
    memoryFeedback.value = "";
    memoryFeedback.placeholder = "Add your correction, preference, or lesson for the agent to remember...";
    memoryFeedback.focus();
  }
  void hydrateMemoryDraftFromContext(safeContext);
}

function hasUsefulMemoryContext(context) {
  const hasUsefulContext = Boolean(
    context && String(context.request_id || context.prompt || context.final_response || "").trim(),
  );
  return hasUsefulContext;
}

function normalizeAppliedMemory(value) {
  if (!value || typeof value !== "object") return null;
  const ids = Array.isArray(value.memory_ids)
    ? value.memory_ids.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  const matches = Array.isArray(value.matches) ? value.matches : [];
  const directives = Array.isArray(value.directives) ? value.directives : [];
  const count = Math.max(0, Number.parseInt(value.memory_count ?? ids.length, 10) || ids.length);
  const rawUseCounts = value.memory_use_counts && typeof value.memory_use_counts === "object"
    ? value.memory_use_counts
    : {};
  const memoryUseCounts = {};
  let countedUses = 0;
  Object.entries(rawUseCounts).forEach(([memoryId, useCount]) => {
    const id = String(memoryId || "").trim();
    const parsed = Math.max(0, Number.parseInt(useCount, 10) || 0);
    if (!id || parsed <= 0) return;
    memoryUseCounts[id] = parsed;
    countedUses += parsed;
  });
  const providedUseCount = Math.max(
    0,
    Number.parseInt(value.memory_use_count ?? value.memory_usage_count ?? countedUses, 10) || countedUses,
  );
  if (count <= 0 && !ids.length && providedUseCount <= 0) return null;
  return {
    memory_count: Math.max(count, ids.length),
    memory_ids: ids,
    memory_use_count: providedUseCount,
    memory_use_counts: memoryUseCounts,
    matches,
    directives,
  };
}

function appliedMemoryFromTracePayload(payload) {
  let applied = null;
  for (const event of Array.isArray(payload?.events) ? payload.events : []) {
    const eventType = String(event?.event_type || "");
    if (String(event?.stage || "") !== "memory_check" && eventType !== "operator.validation.adjudicated") {
      continue;
    }
    const detail = event?.detail && typeof event.detail === "object" ? event.detail : {};
    const candidate = normalizeAppliedMemory({
      memory_count: detail.memory_count,
      memory_ids: detail.memory_ids,
      memory_use_count: detail.memory_use_count,
      memory_use_counts: detail.memory_use_counts,
      matches: detail.matches,
      directives: detail.directives,
    });
    if (candidate) {
      applied = candidate;
    }
  }
  return applied;
}

function setConversationMemoryApplied(appliedMemory) {
  const applied = normalizeAppliedMemory(appliedMemory);
  state.latestAppliedMemory = applied;
  const renderMemoryLabel = (value) => {
    if (!value) return "🧠";
    const itemCount = value.memory_count;
    const useCountValue = value.memory_use_count;
    if (useCountValue > 0) return `🧠 ${useCountValue}x`;
    return itemCount > 1 ? `🧠 ${itemCount}` : "🧠";
  };
  const hideHeaderBadge = () => {
    if (!conversationMemoryAppliedBadge) return;
    conversationMemoryAppliedBadge.textContent = "🧠";
    conversationMemoryAppliedBadge.title = "Previous memory applied to this request";
    conversationMemoryAppliedBadge.setAttribute("aria-label", "Previous memory applied to this request");
    conversationMemoryAppliedBadge.hidden = true;
    conversationMemoryAppliedBadge.setAttribute("aria-hidden", "true");
  };
  if (!applied) {
    hideHeaderBadge();
    if (conversationMemoryButton) {
      conversationMemoryButton.textContent = "Modify memory";
      conversationMemoryButton.title = "Modify memory";
      conversationMemoryButton.classList.remove("memory-applied");
    }
    return;
  }
  const count = applied.memory_count;
  const useCount = applied.memory_use_count;
  const directiveCount = Array.isArray(applied.directives) ? applied.directives.length : 0;
  const matchReasonPreview = Array.isArray(applied.matches)
    ? applied.matches.flatMap((match) => Array.isArray(match?.match_reasons) ? match.match_reasons : []).slice(0, 5)
    : [];
  const label = [
    `Previous memory applied to this request${count > 1 ? ` (${count} items)` : ""}`,
    useCount > 0 ? `Applied ${useCount} time${useCount === 1 ? "" : "s"}.` : "",
    directiveCount > 0 ? `${directiveCount} planner directive${directiveCount === 1 ? "" : "s"}.` : "",
    matchReasonPreview.length ? `Matched by ${matchReasonPreview.join(", ")}.` : "",
  ].filter(Boolean).join(". ");
  const badgeText = renderMemoryLabel(applied);
  hideHeaderBadge();
  if (conversationMemoryButton) {
    conversationMemoryButton.textContent = `${badgeText} Memory`;
    conversationMemoryButton.title = `${label} Modify memory.`;
    conversationMemoryButton.classList.add("memory-applied");
  }
}

function memoryAppliedNoteText(appliedMemory) {
  const applied = normalizeAppliedMemory(appliedMemory);
  if (!applied) return "";
  const count = applied.memory_count;
  const useCount = applied.memory_use_count;
  return `Previous memory applied to this request${count > 1 ? ` (${count} items)` : ""}${
    useCount > 0 ? `; applied ${useCount} time${useCount === 1 ? "" : "s"}` : ""
  }.`;
}

function appendAppliedMemoryNote(message, memoryContext) {
  const noteText = memoryAppliedNoteText(memoryContext?.applied_memory);
  if (!noteText) return;
  setResponseFooterLine(message, "memory", noteText, "memory-applied-note");
}

function updateAppliedMemoryFromEvent(event) {
  const eventType = String(event?.event_type || "");
  if (String(event?.stage || "") !== "memory_check" && eventType !== "operator.validation.adjudicated") return;
  const applied = normalizeAppliedMemory({
    memory_count: event?.detail?.memory_count,
    memory_ids: event?.detail?.memory_ids,
    memory_use_count: event?.detail?.memory_use_count,
    memory_use_counts: event?.detail?.memory_use_counts,
    matches: event?.detail?.matches,
    directives: event?.detail?.directives,
  });
  if (applied) {
    setConversationMemoryApplied(applied);
  }
}

function appliedMemoryEventKey(event, applied) {
  return [
    String(event?.request_id || state.requestId || "request"),
    String(event?.event_type || ""),
    String(event?.stage || ""),
    String(event?.event_id || event?.id || ""),
    String((applied?.memory_ids || []).join(",")),
    String(applied?.memory_count || 0),
    String(applied?.memory_use_count || 0),
  ].join("::");
}

function appendAppliedMemoryConversationMessage(event) {
  if (!chatLog) return;
  const eventType = String(event?.event_type || "");
  if (String(event?.stage || "") !== "memory_check" && eventType !== "operator.validation.adjudicated") return;
  const applied = normalizeAppliedMemory({
    memory_count: event?.detail?.memory_count,
    memory_ids: event?.detail?.memory_ids,
    memory_use_count: event?.detail?.memory_use_count,
    memory_use_counts: event?.detail?.memory_use_counts,
    matches: event?.detail?.matches,
    directives: event?.detail?.directives,
  });
  if (!applied) return;
  const key = appliedMemoryEventKey(event, applied);
  if (state.appliedMemoryNoticeRendered.has(key)) {
    return;
  }
  state.appliedMemoryNoticeRendered.add(key);

  const count = applied.memory_count;
  const useCount = applied.memory_use_count;
  const directiveCount = Array.isArray(applied.directives) ? applied.directives.length : 0;
  const itemCount = count || 1;
  const parts = [
    `${itemCount} item${itemCount === 1 ? "" : "s"}`,
    useCount > 0 ? `${useCount} use${useCount === 1 ? "" : "s"}` : "",
    directiveCount > 0 ? `${directiveCount} directive${directiveCount === 1 ? "" : "s"}` : "",
  ].filter(Boolean);
  const target = inlineNoticeTargetForRequest(event?.request_id || state.requestId);
  appendMessageInlineBadge(target, {
    key: `memory-applied:${key}`,
    label: itemCount > 1 ? `M${itemCount}` : "M",
    title: `Memory applied: ${parts.join(", ")}.`,
    className: "memory-applied-inline-badge",
  });
}

function cacheHitTypeFromEventType(eventType) {
  if (eventType === "operator.cache.hit") return "plan";
  if (eventType === "operator.computation_cache.hit") return "computation";
  if (eventType === "operator.lrdirect.hit") return "computation";
  return "";
}

function normalizeAppliedCache(value) {
  if (!value || typeof value !== "object") return null;
  const planIds = Array.isArray(value.plan_cache_ids)
    ? value.plan_cache_ids.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  const computationIds = Array.isArray(value.computation_cache_ids)
    ? value.computation_cache_ids.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  const planHitCount = Math.max(
    planIds.length,
    Math.max(0, Number.parseInt(value.plan_hit_count, 10) || 0),
  );
  const computationHitCount = Math.max(
    computationIds.length,
    Math.max(0, Number.parseInt(value.computation_hit_count, 10) || 0),
  );
  const hitCount = Math.max(
    planHitCount + computationHitCount,
    Math.max(0, Number.parseInt(value.hit_count, 10) || 0),
  );
  if (hitCount <= 0) return null;
  return {
    hit_count: hitCount,
    plan_hit_count: planHitCount,
    computation_hit_count: computationHitCount,
    plan_cache_ids: planIds,
    computation_cache_ids: computationIds,
  };
}

function appliedCacheFromTracePayload(payload) {
  const planIds = new Set();
  const computationIds = new Set();
  let fallbackPlanHits = 0;
  let fallbackComputationHits = 0;
  for (const event of Array.isArray(payload?.events) ? payload.events : []) {
    const hitType = cacheHitTypeFromEventType(String(event?.event_type || ""));
    if (!hitType) continue;
    const detail = event?.detail && typeof event.detail === "object" ? event.detail : {};
    const cacheId = String(detail.cache_id || event.event_id || event.id || "").trim();
    if (hitType === "plan") {
      if (cacheId) planIds.add(cacheId);
      else fallbackPlanHits += 1;
    } else if (hitType === "computation") {
      if (cacheId) computationIds.add(cacheId);
      else fallbackComputationHits += 1;
    }
  }
  return normalizeAppliedCache({
    plan_cache_ids: [...planIds],
    computation_cache_ids: [...computationIds],
    plan_hit_count: planIds.size + fallbackPlanHits,
    computation_hit_count: computationIds.size + fallbackComputationHits,
  });
}

function setConversationCacheApplied(appliedCache) {
  const applied = normalizeAppliedCache(appliedCache);
  state.latestAppliedCache = applied;
  if (!conversationCacheAppliedBadge) return;
  if (!applied) {
    conversationCacheAppliedBadge.textContent = "cachehit";
    conversationCacheAppliedBadge.title = "Cache used for this request";
    conversationCacheAppliedBadge.setAttribute("aria-label", "Cache used for this request");
    conversationCacheAppliedBadge.hidden = true;
    conversationCacheAppliedBadge.setAttribute("aria-hidden", "true");
    return;
  }
  const hitCount = applied.hit_count;
  const label = [
    `Cache used for this request ${hitCount} time${hitCount === 1 ? "" : "s"}`,
    applied.plan_hit_count > 0
      ? `plan ${applied.plan_hit_count}`
      : "",
    applied.computation_hit_count > 0
      ? `computation ${applied.computation_hit_count}`
      : "",
  ].filter(Boolean).join("; ");
  conversationCacheAppliedBadge.textContent = hitCount > 1 ? `cachehit ${hitCount}x` : "cachehit 1x";
  conversationCacheAppliedBadge.title = label;
  conversationCacheAppliedBadge.setAttribute("aria-label", label);
  conversationCacheAppliedBadge.hidden = false;
  conversationCacheAppliedBadge.setAttribute("aria-hidden", "false");
}

function updateAppliedCacheFromEvent(event) {
  const hitType = cacheHitTypeFromEventType(String(event?.event_type || ""));
  if (!hitType) return;
  const current = normalizeAppliedCache(state.latestAppliedCache) || {
    hit_count: 0,
    plan_hit_count: 0,
    computation_hit_count: 0,
    plan_cache_ids: [],
    computation_cache_ids: [],
  };
  const detail = event?.detail && typeof event.detail === "object" ? event.detail : {};
  const cacheId = String(detail.cache_id || event?.event_id || event?.id || "").trim();
  const nextPlanIds = new Set(current.plan_cache_ids || []);
  const nextComputationIds = new Set(current.computation_cache_ids || []);
  if (hitType === "plan") {
    if (cacheId) nextPlanIds.add(cacheId);
  } else if (hitType === "computation") {
    if (cacheId) nextComputationIds.add(cacheId);
  }
  setConversationCacheApplied({
    plan_cache_ids: [...nextPlanIds],
    computation_cache_ids: [...nextComputationIds],
    plan_hit_count: nextPlanIds.size,
    computation_hit_count: nextComputationIds.size,
  });
}

function setLatestMemoryContext(context) {
  state.latestMemoryContext = hasUsefulMemoryContext(context) ? { ...context } : null;
  if (conversationMemoryButton) {
    conversationMemoryButton.hidden = !state.latestMemoryContext;
    conversationMemoryButton.disabled = !state.latestMemoryContext;
    conversationMemoryButton.setAttribute("aria-hidden", String(!state.latestMemoryContext));
  }
  setConversationMemoryApplied(state.latestMemoryContext?.applied_memory || null);
}

function memoryContextForConfirmation(message, requestId) {
  const existing = message?._memoryContext && typeof message._memoryContext === "object"
    ? message._memoryContext
    : {};
  return {
    request_id: String(existing.request_id || requestId || state.requestId || ""),
    prompt: String(existing.prompt || ""),
    final_response: String(existing.final_response || message?.innerText || ""),
    model_name: String(existing.model_name || state.engineModelName || state.activeModelName || ""),
  };
}

function buildRunFeedbackObject(context, outcome) {
  const applied = normalizeAppliedMemory(context?.applied_memory);
  return {
    feedback_kind: "post_run",
    outcome: String(outcome || "unclear"),
    request_id: String(context?.request_id || state.requestId || ""),
    run_status: String(context?.run_status || ""),
    prompt: String(context?.prompt || ""),
    final_response: String(context?.final_response || "").slice(0, 12000),
    error: String(context?.error || ""),
    model_name: String(context?.model_name || state.engineModelName || state.activeModelName || ""),
    applied_memory_ids: applied?.memory_ids || [],
    applied_memory_count: applied?.memory_count || 0,
    applied_memory_use_count: applied?.memory_use_count || 0,
  };
}

function isStructuredSchemaFailure(context) {
  const text = [
    context?.error,
    context?.final_response,
    context?.run_status,
  ].map((value) => String(value || "").toLowerCase()).join("\n");
  if (!text) return false;
  return (
    text.includes("schema_validation_error") ||
    text.includes("structured llm response did not match") ||
    text.includes("promptclassificationproposal") ||
    (text.includes("field required") && text.includes("extra inputs are not permitted"))
  );
}

function memoryFeedbackEndpointContext() {
  return {
    llm_model: selectedModelValue(),
    llm_base_url: normalizeAgentSettings(state.agentSettings).llm_base_url,
  };
}

function apiErrorDetailText(detail) {
  if (detail === null || detail === undefined) {
    return "";
  }
  if (typeof detail === "string") {
    return detail.trim();
  }
  if (Array.isArray(detail)) {
    return detail
      .map((item) => apiErrorDetailText(item))
      .filter(Boolean)
      .join("\n");
  }
  if (typeof detail === "object") {
    const message = detail.message || detail.msg || detail.error || detail.detail;
    if (message) {
      const prefix = Array.isArray(detail.loc) && detail.loc.length
        ? `${detail.loc.join(".")}: `
        : "";
      return `${prefix}${apiErrorDetailText(message)}`.trim();
    }
    return Object.entries(detail)
      .map(([key, value]) => {
        const text = apiErrorDetailText(value);
        return text ? `${humanizeIdentifier(key)}: ${text}` : "";
      })
      .filter(Boolean)
      .join("\n");
  }
  return String(detail).trim();
}

function apiErrorMessageFromText(text) {
  const raw = String(text || "").trim();
  if (!raw) {
    return "";
  }
  try {
    const payload = JSON.parse(raw);
    if (payload && typeof payload === "object" && !Array.isArray(payload)) {
      return apiErrorDetailText(payload.detail || payload.message || payload.error || payload);
    }
    return apiErrorDetailText(payload);
  } catch {
    return raw;
  }
}

async function responseErrorMessage(response, fallback = "Request failed.") {
  const message = apiErrorMessageFromText(await response.text());
  return message || fallback;
}

function shortStatusError(error) {
  const message = apiErrorMessageFromText(error?.message || error || "unknown error");
  return message ? message.slice(0, 180) : "unknown error";
}

function renderLlmActivityIndicator() {
  if (!llmActivityIndicator) return;
  const count = Math.max(0, Number.parseInt(state.activeLlmCallCount, 10) || 0);
  const active = count > 0;
  const unreachable = state.llmReachable === false;
  llmActivityIndicator.classList.toggle("active", active);
  llmActivityIndicator.classList.toggle("unreachable", unreachable);
  llmActivityIndicator.dataset.active = String(active);
  llmActivityIndicator.dataset.reachable = String(!unreachable);
  llmActivityIndicator.textContent = active && count > 1 ? `LLM ${count}` : "LLM";
  const label = unreachable
    ? `LLM unreachable${state.llmReachabilityDetail ? `: ${state.llmReachabilityDetail}` : ""}`
    : active
    ? `${count} active outbound LLM call${count === 1 ? "" : "s"}`
    : "LLM idle";
  llmActivityIndicator.title = label;
  llmActivityIndicator.setAttribute("aria-label", label);
  syncBadgeMirror(llmActivityIndicator, immersiveLlmActivityIndicator, "immersive-llm-activity-indicator");
}

function beginLlmActivity() {
  state.activeLlmCallCount = Math.max(0, Number.parseInt(state.activeLlmCallCount, 10) || 0) + 1;
  renderLlmActivityIndicator();
}

function endLlmActivity() {
  state.activeLlmCallCount = Math.max(0, (Number.parseInt(state.activeLlmCallCount, 10) || 0) - 1);
  renderLlmActivityIndicator();
}

function resetLlmActivity() {
  state.activeLlmCallCount = 0;
  renderLlmActivityIndicator();
}

function updateLlmActivityFromEvent(event) {
  const eventType = String(event?.event_type || "");
  if (eventType === "llm.request") {
    beginLlmActivity();
  } else if (eventType === "llm.response" || eventType === "llm.error") {
    endLlmActivity();
  }
}

const LEARNING_RUNTIME_PULSE_MS = 5200;

function learningRuntimeCountLabel(count, noun, pluralNoun = `${noun}s`) {
  const safeCount = Math.max(0, Number.parseInt(count, 10) || 0);
  return `${safeCount} ${safeCount === 1 ? noun : pluralNoun}`;
}

function renderLearningRuntimeIndicator() {
  if (!learningRuntimeIndicator) return;
  const active = state.learningRuntimeActive === true;
  const rawStatus = active ? String(state.learningRuntimeStatus || "idle") : "idle";
  const directSeen = active && state.learningRuntimeDirectSeen === true;
  const status = directSeen ? "direct" : rawStatus;
  const retrievedCount = Math.max(0, Number.parseInt(state.learningRuntimeRetrievedCount, 10) || 0);
  const usedCount = Math.max(0, Number.parseInt(state.learningRuntimeUsedCount, 10) || 0);
  const learnedCount = Math.max(0, Number.parseInt(state.learningRuntimeLearnedCount, 10) || 0);
  const visibleCount =
    status === "used" || status === "direct"
      ? usedCount
      : status === "learning"
        ? learnedCount
        : status === "retrieved"
          ? retrievedCount
          : 0;
  const badgePrefix = status === "direct" ? "LRD" : "LR";
  learningRuntimeIndicator.classList.toggle("active", active);
  learningRuntimeIndicator.classList.toggle("retrieved", status === "retrieved");
  learningRuntimeIndicator.classList.toggle("learning", status === "learning");
  learningRuntimeIndicator.classList.toggle("used", status === "used");
  learningRuntimeIndicator.classList.toggle("direct", status === "direct");
  learningRuntimeIndicator.dataset.active = String(active);
  learningRuntimeIndicator.dataset.status = status;
  learningRuntimeIndicator.textContent = active && visibleCount > 0 ? `${badgePrefix} ${visibleCount}` : badgePrefix;
  let label = "Learned runtime idle";
  if (active && status === "direct") {
    label = `LR Direct used ${learningRuntimeCountLabel(
      usedCount,
      "exact-step cache entry",
      "exact-step cache entries"
    )}; retrieved ${learningRuntimeCountLabel(retrievedCount, "candidate")}`;
  } else if (active && status === "used") {
    label = `Learned runtime used ${learningRuntimeCountLabel(
      usedCount,
      "cache entry",
      "cache entries"
    )}; retrieved ${learningRuntimeCountLabel(retrievedCount, "candidate")}`;
  } else if (active && status === "retrieved") {
    label = `Learned runtime retrieved ${learningRuntimeCountLabel(retrievedCount, "candidate")}`;
  } else if (active && status === "learning") {
    label = `Learned runtime learned ${learningRuntimeCountLabel(
      learnedCount,
      "cache entry",
      "cache entries"
    )}; retrieved ${learningRuntimeCountLabel(retrievedCount, "candidate")}`;
  } else if (active) {
    label = `Learned runtime active: ${state.learningRuntimeLastLabel || "learning signal"}`;
  }
  learningRuntimeIndicator.title = label;
  learningRuntimeIndicator.setAttribute("aria-label", label);
  syncBadgeMirror(
    learningRuntimeIndicator,
    immersiveLearningRuntimeIndicator,
    "immersive-learning-runtime-indicator"
  );
}

function resetLearningRuntimeActivity() {
  if (state.learningRuntimePulseTimer) {
    window.clearTimeout(state.learningRuntimePulseTimer);
  }
  state.learningRuntimePulseTimer = null;
  state.learningRuntimeActive = false;
  state.learningRuntimeStatus = "idle";
  state.learningRuntimeDirectSeen = false;
  state.learningRuntimeRetrievedCount = 0;
  state.learningRuntimeUsedCount = 0;
  state.learningRuntimeLearnedCount = 0;
  state.learningRuntimeLastLabel = "";
  state.learningRuntimePulseStartedAtMs = 0;
  renderLearningRuntimeIndicator();
}

function scheduleLearningRuntimePulseReset(pulseStartedAtMs) {
  if (state.learningRuntimePulseTimer) {
    window.clearTimeout(state.learningRuntimePulseTimer);
  }
  state.learningRuntimePulseTimer = window.setTimeout(() => {
    state.learningRuntimePulseTimer = null;
    if (state.learningRuntimePulseStartedAtMs !== pulseStartedAtMs) {
      return;
    }
    if (state.source) {
      scheduleLearningRuntimePulseReset(pulseStartedAtMs);
      return;
    }
    if (state.learningRuntimeDirectSeen === true) {
      return;
    }
    resetLearningRuntimeActivity();
  }, LEARNING_RUNTIME_PULSE_MS);
}

function pulseLearningRuntimeActivity(signal) {
  if (!learningRuntimeIndicator) return;
  if (state.learningRuntimePulseTimer) {
    window.clearTimeout(state.learningRuntimePulseTimer);
  }
  const kind = String(signal?.kind || "").trim();
  const increment = Math.max(1, Number.parseInt(signal?.count, 10) || 1);
  state.learningRuntimeActive = true;
  state.learningRuntimePulseStartedAtMs = Date.now();
  if (kind === "direct") {
    state.learningRuntimeDirectSeen = true;
    state.learningRuntimeStatus = "direct";
    state.learningRuntimeUsedCount =
      Math.max(0, Number.parseInt(state.learningRuntimeUsedCount, 10) || 0) + increment;
  } else if (kind === "used") {
    state.learningRuntimeStatus = state.learningRuntimeDirectSeen === true ? "direct" : "used";
    state.learningRuntimeUsedCount =
      Math.max(0, Number.parseInt(state.learningRuntimeUsedCount, 10) || 0) + increment;
  } else if (kind === "retrieved") {
    if (
      state.learningRuntimeStatus !== "used" &&
      state.learningRuntimeStatus !== "direct" &&
      state.learningRuntimeStatus !== "learning"
    ) {
      state.learningRuntimeStatus = "retrieved";
    }
    state.learningRuntimeRetrievedCount =
      Math.max(0, Number.parseInt(state.learningRuntimeRetrievedCount, 10) || 0) + increment;
  } else if (kind === "learning") {
    if (state.learningRuntimeStatus !== "used" && state.learningRuntimeStatus !== "direct") {
      state.learningRuntimeStatus = "learning";
    }
    state.learningRuntimeLearnedCount =
      Math.max(0, Number.parseInt(state.learningRuntimeLearnedCount, 10) || 0) + increment;
  } else {
    state.learningRuntimeStatus = "idle";
  }
  state.learningRuntimeLastLabel = String(signal?.label || "learning signal");
  renderLearningRuntimeIndicator();
  scheduleLearningRuntimePulseReset(state.learningRuntimePulseStartedAtMs);
}

function learningRuntimeCandidateCount(detail) {
  const directCount = Number(detail?.candidate_count);
  if (Number.isFinite(directCount) && directCount > 0) {
    return Math.floor(directCount);
  }
  const rejectedCount = Number(detail?.checked_candidate_count ?? detail?.rejected_candidate_count);
  if (Number.isFinite(rejectedCount) && rejectedCount > 0) {
    return Math.floor(rejectedCount);
  }
  const commandCount = Number(detail?.command_candidate_count);
  const pythonCount = Number(detail?.python_candidate_count);
  const combinedCount =
    (Number.isFinite(commandCount) && commandCount > 0 ? Math.floor(commandCount) : 0) +
    (Number.isFinite(pythonCount) && pythonCount > 0 ? Math.floor(pythonCount) : 0);
  if (combinedCount > 0) {
    return combinedCount;
  }
  return Array.isArray(detail?.candidates) ? detail.candidates.length : 0;
}

function learningRuntimeWriteSucceeded(event, detail) {
  const level = String(event?.level || "").trim().toLowerCase();
  const title = String(event?.title || "").trim().toLowerCase();
  const status = String(detail?.status || "").trim().toLowerCase();
  if (level === "warning" || level === "error") return false;
  if (title.includes("skipped") || title.includes("failed") || title.includes("rejected")) return false;
  if (status === "failure" || status === "failed" || status === "error") return false;
  return true;
}

function learningRuntimeIsLrEx(detail) {
  const lrMode = String(detail?.lr_mode || "").trim().toLowerCase().replace("-", "_");
  const cacheType = String(detail?.cache_type || "").trim();
  return lrMode === "lr_ex" || cacheType === "payload_command_template";
}

function learningRuntimeSignal(event) {
  const eventType = String(event?.event_type || "");
  const detail = eventDetail(event);
  const decision = String(detail.decision || "").trim();
  const title = String(event?.title || "").toLowerCase();
  const candidateCount = learningRuntimeCandidateCount(detail);
  if (
    candidateCount > 0 &&
    (eventType === "operator.cache.lookup" ||
      eventType === "operator.command_template_cache.lookup" ||
      eventType === "operator.computation_cache.lookup" ||
      eventType === "operator.lrt.lookup" ||
      eventType === "operator.lrdirect.lookup")
  ) {
    return {
      kind: "retrieved",
      count: candidateCount,
      label: "retrieved learned runtime cache candidates",
    };
  }
  if (
    eventType === "operator.validation.accepted" &&
    (detail.cache_id || detail.command_template_id)
  ) {
    if (detail.bypassed_llm === true) {
      return null;
    }
    return { kind: "used", count: 1, label: "used learned runtime cache" };
  }
  if (eventType === "operator.conversation.plan_proposed" && detail.cache_id) {
    return { kind: "used", count: 1, label: "used learned runtime cache" };
  }
  if (eventType === "operator.lrdirect.hit") {
    return { kind: "direct", count: 1, label: "used LR Direct exact-step cache" };
  }
  if (eventType === "operator.lrt.hit") {
    return { kind: "used", count: 1, label: "used LR-T task structure" };
  }
  if (
    eventType === "operator.computation_cache.hit" &&
    detail.cache_id &&
    !decision &&
    title.includes("accepted")
  ) {
    return { kind: "used", count: 1, label: "used learned runtime computation cache" };
  }
  if (
    eventType === "operator.command_template_cache.write" ||
    eventType === "operator.cache.write" ||
    eventType === "operator.computation_cache.write" ||
    eventType === "operator.lrnt.write" ||
    eventType === "operator.lrdirect.write"
  ) {
    if (!learningRuntimeWriteSucceeded(event, detail)) {
      return null;
    }
    return { kind: "learning", count: 1, label: "learned runtime cache entry" };
  }
  if (
    eventType === "learning.lesson.learned" ||
    eventType === "learning.lesson.proposed" ||
    eventType === "learning.proposal.applied" ||
    eventType === "learning.proposal.auto_approved" ||
    eventType === "operator.memory_digest.proposed" ||
    eventType === "operator.command_template_cache.hit" ||
    eventType === "operator.cache.hit" ||
    eventType === "operator.computation_cache.write"
  ) {
    return null;
  }
  return null;
}

function updateLearningRuntimeActivityFromEvent(event) {
  const signal = learningRuntimeSignal(event);
  if (signal) {
    pulseLearningRuntimeActivity(signal);
  }
}

function learningRuntimeLearnedLabel(event, detail) {
  const eventType = String(event?.event_type || "");
  const cacheType = String(detail?.cache_type || "").trim();
  if (learningRuntimeIsLrEx(detail)) {
    return "LR-EX payload-aware command template";
  }
  if (eventType === "operator.lrnt.write") {
    return "LRN learned";
  }
  if (eventType === "operator.lrdirect.write") {
    if (cacheType === "command_template") {
      return "LRN learned";
    }
    if (cacheType === "computation") {
      return "LRN learned";
    }
    return "LRN learned";
  }
  if (eventType === "operator.command_template_cache.write") {
    return "reusable command template";
  }
  if (eventType === "operator.computation_cache.write") {
    return "reusable computation";
  }
  if (eventType === "operator.cache.write") {
    return "reusable plan cache entry";
  }
  return "learned runtime cache entry";
}

function learningRuntimeLearnedEventKey(event) {
  const detail = eventDetail(event);
  return [
    String(event?.request_id || state.requestId || "request"),
    String(event?.event_type || ""),
    String(
      detail.template_id ||
        detail.command_template_id ||
        detail.cache_id ||
        detail.computation_cache_id ||
        detail.entry_id ||
        detail.exact_step_key ||
        event?.event_id ||
        "",
    ),
  ].join("::");
}

function appendLearningRuntimeLearnedConversationMessage(event) {
  const signal = learningRuntimeSignal(event);
  if (!signal || signal.kind !== "learning" || !chatLog) {
    return;
  }
  const detail = eventDetail(event);
  const key = learningRuntimeLearnedEventKey(event);
  if (state.learningRuntimeNoticeRendered.has(key)) {
    return;
  }
  state.learningRuntimeNoticeRendered.add(key);

  const learned = learningRuntimeLearnedLabel(event, detail);
  const cacheId = String(
    detail.template_id ||
      detail.command_template_id ||
      detail.cache_id ||
      detail.computation_cache_id ||
      detail.entry_id ||
      "",
  ).trim();
  const target = inlineNoticeTargetForRequest(event?.request_id || state.requestId, { preferStreaming: true });
  const badgeLabel =
    String(event?.event_type || "") === "operator.lrnt.write"
      ? "LRN"
      : learningRuntimeIsLrEx(detail)
        ? "LRN-EX"
        : "LRN";
  appendMessageInlineBadge(target, {
    key: `lr-learned:${key}`,
    label: badgeLabel,
    title: `Learned this: ${learned}${cacheId ? ` (${cacheId})` : ""}.`,
    className: "learning-runtime-learned-inline-badge",
  });
}

function learningRuntimeAppliedSignal(event) {
  const eventType = String(event?.event_type || "");
  const detail = eventDetail(event);
  const decision = String(detail.decision || "").trim();
  const title = String(event?.title || "").trim().toLowerCase();
  const signal = learningRuntimeSignal(event);
  if (signal && (signal.kind === "used" || signal.kind === "direct")) {
    return signal;
  }
  if (
    eventType === "operator.computation_cache.hit" &&
    title.includes("accepted")
  ) {
    return { kind: "used", count: 1, label: "used learned runtime computation cache" };
  }
  return null;
}

function learningRuntimeAppliedLabel(event, signal) {
  const eventType = String(event?.event_type || "");
  const detail = eventDetail(event);
  if (learningRuntimeIsLrEx(detail)) {
    return "LR-EX payload-aware command template";
  }
  if (eventType === "operator.lrt.hit") {
    return "LR-T applied";
  }
  if (eventType === "operator.lrdirect.hit") {
    return "LR-D applied";
  }
  if (eventType === "operator.command_template_cache.hit") {
    return "learned command template";
  }
  if (eventType === "operator.computation_cache.hit") {
    return "learned computation cache";
  }
  if (eventType === "operator.cache.hit" || eventType === "operator.conversation.plan_proposed") {
    return "learned plan cache";
  }
  if (eventType === "operator.validation.accepted" && detail.command_template_id) {
    return "learned command template";
  }
  if (eventType === "operator.validation.accepted" && detail.cache_id) {
    return "learned runtime cache";
  }
  return String(signal?.label || "learned runtime cache");
}

function learningRuntimeAppliedEventKey(event) {
  const detail = eventDetail(event);
  return [
    String(event?.request_id || state.requestId || "request"),
    String(event?.event_type || ""),
    String(
      detail.template_id ||
        detail.command_template_id ||
        detail.selected_template_id ||
        detail.cache_id ||
        detail.computation_cache_id ||
        detail.entry_id ||
        detail.exact_step_key ||
        event?.event_id ||
        "",
    ),
  ].join("::");
}

function learnedCorrectionArtifactRefFromAppliedEvent(event, signal) {
  if (!signal) return null;
  const eventType = String(event?.event_type || "");
  const detail = eventDetail(event);
  let artifactKind = "";
  let artifactId = "";
  const cacheType = String(detail.cache_type || "").trim().toLowerCase();
  if (eventType === "operator.lrt.hit") {
    artifactKind = "lr_t";
    artifactId = String(detail.entry_id || detail.cache_id || "").trim();
  } else if (eventType === "operator.lrdirect.hit") {
    if (cacheType === "computation" || detail.computation_cache_id) {
      artifactKind = "computation_cache";
      artifactId = String(detail.computation_cache_id || detail.cache_id || "").trim();
    } else {
      artifactKind = learningRuntimeIsLrEx(detail) ? "lr_ex" : "lr_d";
      artifactId = String(detail.template_id || detail.command_template_id || detail.selected_template_id || "").trim();
    }
  } else if (eventType === "operator.command_template_cache.hit") {
    artifactKind = learningRuntimeIsLrEx(detail) ? "lr_ex" : "command_template";
    artifactId = String(detail.template_id || detail.command_template_id || detail.selected_template_id || "").trim();
  } else if (eventType === "operator.computation_cache.hit") {
    artifactKind = "computation_cache";
    artifactId = String(detail.computation_cache_id || detail.cache_id || "").trim();
  } else if (eventType === "operator.cache.hit" || eventType === "operator.conversation.plan_proposed") {
    artifactKind = "plan_cache";
    artifactId = String(detail.plan_cache_id || detail.cache_id || "").trim();
  } else if (eventType === "operator.validation.accepted" && detail.command_template_id) {
    artifactKind = learningRuntimeIsLrEx(detail) ? "lr_ex" : "command_template";
    artifactId = String(detail.command_template_id || detail.template_id || "").trim();
  } else if (eventType === "operator.validation.accepted" && detail.cache_id) {
    artifactKind = cacheType === "computation" ? "computation_cache" : "plan_cache";
    artifactId = String(detail.cache_id || "").trim();
  }
  if (!artifactKind || !artifactId) {
    return null;
  }
  return {
    artifact_kind: artifactKind,
    artifact_id: artifactId,
    request_id: String(event?.request_id || state.requestId || "").trim(),
    action_id: String(detail.action_id || detail.selected_action_id || "").trim(),
    event_type: eventType,
    exact_step_key: String(detail.exact_step_key || "").trim(),
  };
}

function appendLearningRuntimeAppliedConversationMessage(event) {
  const signal = learningRuntimeAppliedSignal(event);
  if (!signal || !chatLog) {
    return;
  }
  const detail = eventDetail(event);
  const key = learningRuntimeAppliedEventKey(event);
  if (state.learningRuntimeAppliedNoticeRendered.has(key)) {
    return;
  }
  state.learningRuntimeAppliedNoticeRendered.add(key);

  const applied = learningRuntimeAppliedLabel(event, signal);
  const cacheId = String(
    detail.template_id ||
      detail.command_template_id ||
      detail.selected_template_id ||
      detail.cache_id ||
      detail.computation_cache_id ||
      detail.entry_id ||
      "",
  ).trim();
  const target = inlineNoticeTargetForRequest(event?.request_id || state.requestId, { preferStreaming: true });
  const artifactRef = learnedCorrectionArtifactRefFromAppliedEvent(event, signal);
  if (artifactRef) {
    state.learningRuntimeCorrectionTargets.set(key, artifactRef);
  }
  const badgeLabel =
    String(event?.event_type || "") === "operator.lrt.hit"
      ? "LR-T"
      : learningRuntimeIsLrEx(detail)
        ? "LR-EX"
        : signal.kind === "direct"
          ? "LRD"
          : "LR";
  appendMessageInlineBadge(target, {
    key: `lr-applied:${key}`,
    label: badgeLabel,
    title: artifactRef
      ? `LR applied: ${applied}${cacheId ? ` (${cacheId})` : ""}. Modify auto-learnt action.`
      : `LR applied: ${applied}${cacheId ? ` (${cacheId})` : ""}.`,
    className: "learning-runtime-applied-inline-badge",
    dataset: artifactRef ? {
      correctionArtifactKind: artifactRef.artifact_kind,
      correctionArtifactId: artifactRef.artifact_id,
    } : null,
    onClick: artifactRef
      ? (clickEvent) => {
          clickEvent.preventDefault();
          void openStepCorrectionEditor(artifactRef, clickEvent.currentTarget);
        }
      : null,
  });
}

async function postStepCorrectionJson(path, payload) {
  return fetchWithLlmActivity(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
}

function stepCorrectionDefaultMode(snapshot) {
  const modes = Array.isArray(snapshot?.correction_modes) ? snapshot.correction_modes : [];
  return modes.find((mode) => mode !== "instruction") || modes[0] || "instruction";
}

function stepCorrectionModeLabel(mode) {
  switch (String(mode || "")) {
    case "command":
      return "Correct command";
    case "code":
      return "Correct Python";
    case "plan":
      return "Edit plan JSON";
    case "lr_tasks":
      return "Edit LR-T steps";
    default:
      return "Instruction only";
  }
}

function stepCorrectionPrettyJson(value, fallback = {}) {
  try {
    return JSON.stringify(value ?? fallback, null, 2);
  } catch {
    return JSON.stringify(fallback, null, 2);
  }
}

function stepCorrectionParseJson(text, fallback, label, status) {
  const raw = String(text || "").trim();
  if (!raw) return fallback;
  try {
    return JSON.parse(raw);
  } catch (error) {
    if (status) {
      status.textContent = `${label} JSON is invalid: ${shortStatusError(error)}`;
    }
    return null;
  }
}

function stepCorrectionField(labelText, control) {
  const label = document.createElement("label");
  label.textContent = labelText;
  label.append(control);
  return label;
}

function stepCorrectionTextarea(value = "", rows = 4, placeholder = "") {
  const textarea = document.createElement("textarea");
  textarea.rows = rows;
  textarea.value = String(value || "");
  textarea.placeholder = placeholder;
  return textarea;
}

function setStepCorrectionEditorDisabled(editor, disabled) {
  editor?.querySelectorAll("button, textarea, select, input").forEach((control) => {
    control.disabled = Boolean(disabled);
  });
}

function stepCorrectionTaskRow(task = {}, index = 0) {
  const row = document.createElement("div");
  row.className = "step-correction-task-row";
  row._taskBase = task && typeof task === "object" ? { ...task } : {};

  const idInput = document.createElement("input");
  idInput.type = "text";
  idInput.value = String(task.id || `task_${index + 1}`);

  const verbSelect = document.createElement("select");
  [
    "read",
    "list",
    "search",
    "create",
    "update",
    "delete",
    "transform",
    "analyze",
    "calculate",
    "count",
    "filter",
    "sort",
    "summarize",
    "compare",
    "execute",
    "render",
    "unknown",
  ].forEach((verb) => {
    const option = document.createElement("option");
    option.value = verb;
    option.textContent = verb;
    verbSelect.append(option);
  });
  verbSelect.value = String(task.semantic_verb || "unknown");

  const objectInput = document.createElement("input");
  objectInput.type = "text";
  objectInput.value = String(task.object_type || "artifact");

  const riskSelect = document.createElement("select");
  ["low", "medium", "high", "critical"].forEach((risk) => {
    const option = document.createElement("option");
    option.value = risk;
    option.textContent = risk;
    riskSelect.append(option);
  });
  riskSelect.value = String(task.risk_level || "low");

  const description = stepCorrectionTextarea(
    task.description || "",
    2,
    "Describe the corrected task step.",
  );
  const dependencies = document.createElement("input");
  dependencies.type = "text";
  dependencies.value = Array.isArray(task.dependencies)
    ? task.dependencies.join(", ")
    : String(task.dependencies || "");

  const remove = document.createElement("button");
  remove.type = "button";
  remove.className = "settings-action-button step-correction-remove-task";
  remove.textContent = "Remove";
  remove.addEventListener("click", () => row.remove());

  row.append(
    stepCorrectionField("Step id", idInput),
    stepCorrectionField("Verb", verbSelect),
    stepCorrectionField("Object", objectInput),
    stepCorrectionField("Risk", riskSelect),
    stepCorrectionField("Description", description),
    stepCorrectionField("Depends on", dependencies),
    remove,
  );
  row._taskControls = { idInput, verbSelect, objectInput, riskSelect, description, dependencies };
  return row;
}

function collectStepCorrectionTasks(list, status) {
  const rows = Array.from(list?.querySelectorAll(".step-correction-task-row") || []);
  const tasks = [];
  for (const [index, row] of rows.entries()) {
    const controls = row._taskControls || {};
    const base = row._taskBase && typeof row._taskBase === "object" ? row._taskBase : {};
    const id = String(controls.idInput?.value || `task_${index + 1}`).trim();
    const description = String(controls.description?.value || "").trim();
    if (!description) {
      if (status) status.textContent = `Task ${id || index + 1} needs a description.`;
      return null;
    }
    tasks.push({
      ...base,
      id,
      description,
      semantic_verb: String(controls.verbSelect?.value || base.semantic_verb || "unknown"),
      object_type: String(controls.objectInput?.value || base.object_type || "artifact").trim() || "artifact",
      intent_confidence: Number.isFinite(Number(base.intent_confidence)) ? Number(base.intent_confidence) : 0.8,
      constraints: base.constraints && typeof base.constraints === "object" ? base.constraints : {},
      dependencies: String(controls.dependencies?.value || "")
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean),
      raw_evidence: base.raw_evidence || null,
      requires_confirmation: Boolean(base.requires_confirmation),
      risk_level: String(controls.riskSelect?.value || base.risk_level || "low"),
      operation_intent: base.operation_intent || null,
      side_effect_type: base.side_effect_type || null,
      dependency_hints: Array.isArray(base.dependency_hints) ? base.dependency_hints : [],
    });
  }
  if (!tasks.length && status) {
    status.textContent = "Add at least one LR-T step.";
    return null;
  }
  return tasks;
}

function stepCorrectionResolvedArtifactRef(snapshot, originalRef) {
  return {
    ...(snapshot?.artifact_ref || {}),
    ...(originalRef || {}),
    artifact_kind: String(snapshot?.artifact_ref?.artifact_kind || originalRef?.artifact_kind || ""),
    artifact_id: String(snapshot?.artifact_ref?.artifact_id || originalRef?.artifact_id || ""),
    request_id: String(originalRef?.request_id || snapshot?.artifact_ref?.request_id || state.requestId || ""),
    action_id: String(originalRef?.action_id || snapshot?.artifact_ref?.action_id || ""),
    event_type: String(originalRef?.event_type || snapshot?.artifact_ref?.event_type || ""),
    exact_step_key: String(originalRef?.exact_step_key || snapshot?.artifact_ref?.exact_step_key || ""),
  };
}

function buildStepCorrectionPayload(editor, snapshot, originalRef, status) {
  const mode = String(editor?._stepCorrectionMode?.value || "instruction");
  const artifactRef = stepCorrectionResolvedArtifactRef(snapshot, originalRef);
  const payload = {
    artifact_ref: artifactRef,
    correction_kind: mode,
    instruction: String(editor?._stepCorrectionInstruction?.value || "").trim(),
    rationale: "",
  };
  if (mode === "command") {
    payload.corrected_command = String(editor?._stepCorrectionCommand?.value || "").trim();
  } else if (mode === "code") {
    payload.corrected_code = String(editor?._stepCorrectionCode?.value || "").trim();
  } else if (mode === "plan") {
    const plan = stepCorrectionParseJson(
      editor?._stepCorrectionPlan?.value,
      {},
      "Plan",
      status,
    );
    if (!plan) return null;
    payload.plan = plan;
  } else if (mode === "lr_tasks") {
    const tasks = collectStepCorrectionTasks(editor?._stepCorrectionTaskList, status);
    if (!tasks) return null;
    const globalConstraints = stepCorrectionParseJson(
      editor?._stepCorrectionGlobalConstraints?.value,
      {},
      "Global constraints",
      status,
    );
    if (globalConstraints === null) return null;
    payload.lr_tasks = tasks;
    payload.global_constraints = globalConstraints;
  }
  return payload;
}

function buildStepDeletionPayload(snapshot, originalRef) {
  return {
    artifact_ref: stepCorrectionResolvedArtifactRef(snapshot, originalRef),
    reason: "User deleted this auto-learnt artifact from the correction window.",
  };
}

function setStepCorrectionMode(editor, mode) {
  const selected = String(mode || "instruction");
  editor.querySelectorAll("[data-step-correction-panel]").forEach((panel) => {
    panel.hidden = String(panel.dataset.stepCorrectionPanel || "") !== selected;
  });
}

function renderStepCorrectionResult(editor, payload) {
  const status = editor?._stepCorrectionStatus;
  if (!status) return;
  const replacements = payload?.replacement_ids && typeof payload.replacement_ids === "object"
    ? Object.entries(payload.replacement_ids).map(([kind, id]) => `${humanizeIdentifier(kind)} ${id}`)
    : [];
  const quarantined = Array.isArray(payload?.quarantined_ids) ? payload.quarantined_ids.length : 0;
  const failed = Array.isArray(payload?.marked_failed_ids) ? payload.marked_failed_ids.length : 0;
  const parts = ["Saved correction."];
  if (replacements.length) parts.push(`Replacement: ${replacements.join(", ")}.`);
  if (quarantined) parts.push(`Quarantined ${quarantined}.`);
  if (failed) parts.push(`Marked failed ${failed}.`);
  if (Array.isArray(payload?.warnings) && payload.warnings.length) {
    parts.push(payload.warnings.join(" "));
  }
  status.textContent = parts.join(" ");
  const requestId = String(payload?.artifact_ref?.request_id || "").trim();
  const notes = String(payload?.retry_notes || "").trim();
  if (requestId && notes) {
    state.stepCorrectionRetryNotesByRequest.set(requestId, notes);
  }
  const existingRetry = editor.querySelector(".step-correction-retry-button");
  if (existingRetry) existingRetry.remove();
  if (payload?.retry_available && requestId) {
    const retry = document.createElement("button");
    retry.type = "button";
    retry.className = "settings-action-button step-correction-retry-button";
    retry.textContent = "Continue from failure";
    retry.title = "Retry the failed run using the saved correction notes.";
    retry.addEventListener("click", () => {
      void handleContinueFromFailure(requestId, retry, notes);
    });
    editor.querySelector(".step-correction-editor-actions")?.prepend(retry);
  }
}

function renderStepDeletionResult(editor, payload) {
  const status = editor?._stepCorrectionStatus;
  if (!status) return;
  const deleted = Array.isArray(payload?.deleted_ids) ? payload.deleted_ids : [];
  const selected = String(payload?.artifact_ref?.artifact_id || deleted[0] || "selected learned step");
  const parts = [`Deleted learnt step ${selected}.`];
  if (deleted.length > 1) {
    parts.push(`Deleted ${deleted.length} rows.`);
  }
  if (Array.isArray(payload?.warnings) && payload.warnings.length) {
    parts.push(payload.warnings.join(" "));
  }
  status.textContent = parts.join(" ");
}

function renderStepCorrectionEditor(message, snapshot, originalRef) {
  if (!message) return null;
  const existing = message.querySelector(":scope > .step-correction-editor");
  if (existing) {
    existing.remove();
  }
  const editable = snapshot?.editable && typeof snapshot.editable === "object" ? snapshot.editable : {};
  const modes = Array.isArray(snapshot?.correction_modes) && snapshot.correction_modes.length
    ? snapshot.correction_modes
    : ["instruction"];
  const defaultMode = stepCorrectionDefaultMode(snapshot);
  const editor = document.createElement("div");
  editor.className = "step-correction-editor";
  editor.dataset.artifactKind = String(snapshot?.artifact_ref?.artifact_kind || originalRef?.artifact_kind || "");
  editor.dataset.artifactId = String(snapshot?.artifact_ref?.artifact_id || originalRef?.artifact_id || "");

  const heading = document.createElement("div");
  heading.className = "step-correction-editor-heading";
  const title = document.createElement("strong");
  title.textContent = "Modify auto-learnt action";
  const meta = document.createElement("span");
  meta.textContent = [
    String(snapshot?.artifact_ref?.artifact_kind || originalRef?.artifact_kind || ""),
    String(snapshot?.artifact_ref?.artifact_id || originalRef?.artifact_id || ""),
  ].filter(Boolean).join(" ");
  heading.append(title, meta);

  const modeSelect = document.createElement("select");
  modeSelect.className = "step-correction-mode";
  modes.forEach((mode) => {
    const option = document.createElement("option");
    option.value = mode;
    option.textContent = stepCorrectionModeLabel(mode);
    modeSelect.append(option);
  });
  modeSelect.value = defaultMode;
  editor._stepCorrectionMode = modeSelect;

  const modeRow = document.createElement("div");
  modeRow.className = "step-correction-mode-row";
  modeRow.append(stepCorrectionField("Correction type", modeSelect));

  const panels = document.createElement("div");
  panels.className = "step-correction-panels";

  const commandPanel = document.createElement("div");
  commandPanel.dataset.stepCorrectionPanel = "command";
  const commandText = stepCorrectionTextarea(
    editable.command || "",
    3,
    "Paste the corrected command.",
  );
  editor._stepCorrectionCommand = commandText;
  commandPanel.append(stepCorrectionField("Corrected command", commandText));

  const codePanel = document.createElement("div");
  codePanel.dataset.stepCorrectionPanel = "code";
  const codeText = stepCorrectionTextarea(
    editable.code || "",
    8,
    "Paste corrected side-effect-free Python code.",
  );
  editor._stepCorrectionCode = codeText;
  codePanel.append(stepCorrectionField("Corrected Python", codeText));

  const planPanel = document.createElement("div");
  planPanel.dataset.stepCorrectionPanel = "plan";
  const planText = stepCorrectionTextarea(
    stepCorrectionPrettyJson(editable.plan || {}, {}),
    10,
    "Edit the OperatorPlan JSON.",
  );
  editor._stepCorrectionPlan = planText;
  planPanel.append(stepCorrectionField("OperatorPlan JSON", planText));

  const lrtPanel = document.createElement("div");
  lrtPanel.dataset.stepCorrectionPanel = "lr_tasks";
  const taskList = document.createElement("div");
  taskList.className = "step-correction-task-list";
  const tasks = Array.isArray(editable.tasks) ? editable.tasks : [];
  (tasks.length ? tasks : [{ id: "task_1", semantic_verb: "unknown", object_type: "artifact", description: "" }])
    .forEach((task, index) => taskList.append(stepCorrectionTaskRow(task, index)));
  const addTask = document.createElement("button");
  addTask.type = "button";
  addTask.className = "settings-action-button";
  addTask.textContent = "Add step";
  addTask.addEventListener("click", () => {
    taskList.append(stepCorrectionTaskRow({}, taskList.children.length));
  });
  const globalConstraints = stepCorrectionTextarea(
    stepCorrectionPrettyJson(editable.global_constraints || {}, {}),
    4,
    "Edit global constraints JSON.",
  );
  editor._stepCorrectionTaskList = taskList;
  editor._stepCorrectionGlobalConstraints = globalConstraints;
  lrtPanel.append(taskList, addTask, stepCorrectionField("Global constraints JSON", globalConstraints));

  const instructionPanel = document.createElement("div");
  instructionPanel.dataset.stepCorrectionPanel = "instruction";

  panels.append(commandPanel, codePanel, planPanel, lrtPanel, instructionPanel);

  const instruction = stepCorrectionTextarea(
    editable.instruction || "",
    3,
    "Optional guidance for future similar runs.",
  );
  editor._stepCorrectionInstruction = instruction;

  const actions = document.createElement("div");
  actions.className = "step-correction-editor-actions";
  const validate = document.createElement("button");
  validate.type = "button";
  validate.className = "settings-action-button";
  validate.textContent = "Validate";
  const save = document.createElement("button");
  save.type = "button";
  save.className = "settings-action-button";
  save.textContent = "Save correction";
  const deleteStep = document.createElement("button");
  deleteStep.type = "button";
  deleteStep.className = "settings-action-button step-correction-delete-button";
  deleteStep.textContent = "Delete this learnt step";
  deleteStep.title = "Delete only this selected learnt step. Other learnt actions in this plan or request stay intact.";
  const cancel = document.createElement("button");
  cancel.type = "button";
  cancel.className = "settings-action-button";
  cancel.textContent = "Cancel";
  const status = document.createElement("span");
  status.className = "step-correction-status";
  editor._stepCorrectionStatus = status;

  validate.addEventListener("click", async () => {
    const correctionPayload = buildStepCorrectionPayload(editor, snapshot, originalRef, status);
    if (!correctionPayload) return;
    setStepCorrectionEditorDisabled(editor, true);
    status.textContent = "Validating...";
    try {
      const response = await postStepCorrectionJson("/api/agent/corrections/step/validate", correctionPayload);
      if (!response.ok) {
        status.textContent = await responseErrorMessage(response, "Validation failed.");
      } else {
        status.textContent = "Correction payload is valid.";
      }
    } catch (error) {
      status.textContent = `Validation failed: ${shortStatusError(error)}`;
    } finally {
      setStepCorrectionEditorDisabled(editor, false);
    }
  });

  save.addEventListener("click", async () => {
    const correctionPayload = buildStepCorrectionPayload(editor, snapshot, originalRef, status);
    if (!correctionPayload) return;
    setStepCorrectionEditorDisabled(editor, true);
    status.textContent = "Saving correction...";
    try {
      const response = await postStepCorrectionJson("/api/agent/corrections/step", correctionPayload);
      if (!response.ok) {
        status.textContent = await responseErrorMessage(response, "Correction save failed.");
        setStepCorrectionEditorDisabled(editor, false);
        return;
      }
      const result = await response.json();
      renderStepCorrectionResult(editor, result);
    } catch (error) {
      status.textContent = `Correction save failed: ${shortStatusError(error)}`;
      setStepCorrectionEditorDisabled(editor, false);
    }
  });
  deleteStep.addEventListener("click", async () => {
    if (!window.confirm("Delete only this learnt step? Other learnt actions in this plan or request will stay.")) {
      return;
    }
    const deletionPayload = buildStepDeletionPayload(snapshot, originalRef);
    setStepCorrectionEditorDisabled(editor, true);
    status.textContent = "Deleting learnt step...";
    try {
      const response = await postStepCorrectionJson("/api/agent/corrections/step/delete", deletionPayload);
      if (!response.ok) {
        status.textContent = await responseErrorMessage(response, "Learnt step delete failed.");
        setStepCorrectionEditorDisabled(editor, false);
        return;
      }
      const result = await response.json();
      renderStepDeletionResult(editor, result);
      setStepCorrectionEditorDisabled(editor, true);
      cancel.disabled = false;
    } catch (error) {
      status.textContent = `Learnt step delete failed: ${shortStatusError(error)}`;
      setStepCorrectionEditorDisabled(editor, false);
    }
  });
  cancel.addEventListener("click", () => editor.remove());
  modeSelect.addEventListener("change", () => setStepCorrectionMode(editor, modeSelect.value));
  actions.append(validate, save, deleteStep, cancel, status);

  editor.append(
    heading,
    modeRow,
    panels,
    stepCorrectionField("Guidance", instruction),
    actions,
  );
  message.append(editor);
  setStepCorrectionMode(editor, defaultMode);
  if (defaultMode === "command") {
    commandText.focus();
  } else if (defaultMode === "code") {
    codeText.focus();
  } else if (defaultMode === "plan") {
    planText.focus();
  } else {
    instruction.focus();
  }
  scrollChatToBottom();
  return editor;
}

async function openStepCorrectionEditor(artifactRef, anchor) {
  const ref = artifactRef && typeof artifactRef === "object" ? artifactRef : null;
  if (!ref?.artifact_kind || !ref?.artifact_id) return;
  const message = anchor?.closest?.(".message") || inlineNoticeTargetForRequest(ref.request_id || state.requestId);
  const existing = message?.querySelector(":scope > .step-correction-editor");
  if (existing && existing.dataset.artifactId === String(ref.artifact_id || "")) {
    existing.querySelector("textarea, input, select")?.focus();
    return;
  }
  if (anchor) {
    anchor.disabled = true;
  }
  try {
    const response = await fetch(
      `/api/agent/corrections/artifact/${encodeURIComponent(ref.artifact_kind)}/${encodeURIComponent(ref.artifact_id)}`,
    );
    if (!response.ok) {
      const errorMessage = await responseErrorMessage(response, "Could not load learned artifact.");
      addMessage("assistant", "Correction", errorMessage);
      return;
    }
    const snapshot = await response.json();
    renderStepCorrectionEditor(message, snapshot, ref);
  } catch (error) {
    addMessage("assistant", "Correction", `Could not load learned artifact: ${shortStatusError(error)}`);
  } finally {
    if (anchor) {
      anchor.disabled = false;
    }
  }
}

async function fetchWithLlmActivity(input, init) {
  beginLlmActivity();
  try {
    return await fetch(input, init);
  } finally {
    endLlmActivity();
  }
}

async function postMemoryFeedbackJson(path, payload) {
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), memoryFeedbackRequestTimeoutMs);
  try {
    return await fetchWithLlmActivity(path, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
  } catch (error) {
    if (controller.signal.aborted) {
      throw new Error("feedback request timed out");
    }
    throw error;
  } finally {
    window.clearTimeout(timeoutId);
  }
}

function setInlineMemoryEditorDisabled(editor, disabled) {
  editor?.querySelectorAll("button, textarea, select").forEach((control) => {
    control.disabled = Boolean(disabled);
  });
}

async function refreshMemoryAfterFeedback(status) {
  if (!state.memoryDrawerOpen) {
    return;
  }
  try {
    await loadMemory();
  } catch (error) {
    status.textContent += ` Memory refresh failed: ${shortStatusError(error)}`;
  }
}

async function draftInlineMemoryFeedback(context, outcome, textarea, status, button) {
  if (!textarea || !status) return;
  const runFeedback = buildRunFeedbackObject(context, outcome);
  status.textContent = "Drafting feedback...";
  if (button) button.disabled = true;
  try {
    const response = await postMemoryFeedbackJson(
      "/api/agent/memory/feedback/draft",
      {
        outcome: runFeedback.outcome,
        ...memoryFeedbackEndpointContext(),
        prompt: String(context?.prompt || ""),
        request_id: String(context?.request_id || ""),
        model_name: String(context?.model_name || state.engineModelName || state.activeModelName || ""),
        run_feedback: runFeedback,
      },
    );
    if (!response.ok) {
      status.textContent = "Auto draft failed.";
      showUiActionError({
        title: "Memory draft failed",
        message: shortStatusError(await response.text()),
        fix: "Try again, or write the memory note manually.",
      });
      return;
    }
    const payload = await response.json();
    const feedback = String(payload.feedback || "").trim();
    if (feedback) {
      textarea.value = feedback;
      textarea.focus();
      status.textContent = "Draft ready. Edit before saving.";
    } else {
      status.textContent = "No draft was generated.";
    }
  } catch (error) {
    status.textContent = `Auto draft failed: ${shortStatusError(error)}`;
    showUiActionError({
      title: "Memory draft failed",
      message: shortStatusError(error),
      fix: "Try again, or write the memory note manually.",
    });
  } finally {
    if (button) button.disabled = false;
  }
}

async function commitInlineMemoryFeedback(feedback, context, status, editor) {
  const trimmed = String(feedback || "").trim();
  if (!trimmed) {
    status.textContent = "Add a note first.";
    showUiActionError({
      title: "Memory note required",
      message: "The memory was not saved because the note is empty.",
      fix: "Add a note explaining what to remember, then save again.",
      field: editor?.querySelector("textarea"),
    });
    return;
  }
  setInlineMemoryEditorDisabled(editor, true);
  const feedbackTarget = String(context?.feedback_target || "memory");
  status.textContent = feedbackTarget === "validation_policy"
    ? "Digesting validation policy..."
    : "Digesting memory...";
  try {
    const response = await postMemoryFeedbackJson(
      "/api/agent/memory/feedback",
      {
        feedback: trimmed,
        feedback_target: feedbackTarget,
        ...memoryFeedbackEndpointContext(),
        prompt: String(context?.prompt || ""),
        request_id: String(context?.request_id || ""),
        model_name: String(context?.model_name || state.engineModelName || state.activeModelName || ""),
        task_type: "",
        tool_type: "",
        intent_type: "",
        validator_error_type: String(context?.validator_error_type || ""),
        run_feedback: context?.run_feedback || null,
      },
    );
    if (!response.ok) {
      status.textContent = "Memory save failed.";
      setInlineMemoryEditorDisabled(editor, false);
      showUiActionError({
        title: "Memory save failed",
        message: shortStatusError(await response.text()),
        fix: "Review the note and try saving it again.",
      });
      return;
    }
    const payload = await response.json();
    const proposals = Array.isArray(payload.proposals) ? payload.proposals : [];
    let appliedCount = 0;
    let failedApplyCount = 0;
    let pendingValidationPolicyCount = 0;
    for (const proposal of proposals) {
      const proposalId = String(proposal?.proposal_id || "").trim();
      if (!proposalId) continue;
      const proposalKind = String(proposal?.draft?.memory_kind || "").trim();
      if (feedbackTarget === "validation_policy" && proposalKind === "validation_policy") {
        pendingValidationPolicyCount += 1;
        continue;
      }
      try {
        const applyResponse = await fetch(
          `/api/agent/memory/proposals/${encodeURIComponent(proposalId)}/apply`,
          { method: "POST" },
        );
        if (applyResponse.ok) {
          appliedCount += 1;
        } else {
          failedApplyCount += 1;
        }
      } catch {
        failedApplyCount += 1;
      }
    }
    const statusParts = [];
    if (appliedCount) {
      statusParts.push(`Saved ${appliedCount} memory item${appliedCount === 1 ? "" : "s"}.`);
    }
    if (pendingValidationPolicyCount) {
      statusParts.push(
        `Proposed ${pendingValidationPolicyCount} validation polic${pendingValidationPolicyCount === 1 ? "y" : "ies"}.`,
      );
    }
    if (failedApplyCount) {
      statusParts.push(`${failedApplyCount} proposal${failedApplyCount === 1 ? "" : "s"} failed.`);
      showUiActionError({
        title: "Memory proposal apply failed",
        message: `${failedApplyCount} memory proposal${failedApplyCount === 1 ? "" : "s"} could not be applied.`,
        fix: "Open the Memory drawer, review pending proposals, and try applying them again.",
      });
    }
    status.textContent = statusParts.length ? statusParts.join(" ") : "No memory item was created.";
    if (failedApplyCount) {
      setInlineMemoryEditorDisabled(editor, false);
    } else if (!appliedCount && !pendingValidationPolicyCount) {
      setInlineMemoryEditorDisabled(editor, false);
    }
    await refreshMemoryAfterFeedback(status);
  } catch (error) {
    status.textContent = `Memory save failed: ${shortStatusError(error)}`;
    setInlineMemoryEditorDisabled(editor, false);
    showUiActionError({
      title: "Memory save failed",
      message: shortStatusError(error),
      fix: "Review the note and try saving it again.",
    });
  }
}

function showInlineMemoryEditor(actions, context, options = {}) {
  if (!actions) return;
  const existing = actions.querySelector(".inline-memory-editor");
  if (existing) {
    existing.querySelector("textarea")?.focus();
    return;
  }
  const editorOptions = options && typeof options === "object" ? options : {};
  const editor = document.createElement("div");
  editor.className = "inline-memory-editor";
  const label = document.createElement("label");
  label.textContent = editorOptions.label || "What should the agent remember about this plan?";
  let outcomeSelect = null;
  if (editorOptions.includeOutcome) {
    const outcomeLabel = document.createElement("label");
    outcomeLabel.textContent = "Run outcome";
    outcomeSelect = document.createElement("select");
    outcomeSelect.className = "inline-memory-outcome";
    [
      ["right_decision", "Right decision"],
      ["partially_right", "Partially right"],
      ["wrong_decision", "Wrong decision"],
      ["unclear", "Unclear"],
    ].forEach(([value, text]) => {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = text;
      outcomeSelect.append(option);
    });
    outcomeLabel.append(outcomeSelect);
    editor.append(outcomeLabel);
  }
  const textarea = document.createElement("textarea");
  textarea.rows = 3;
  textarea.placeholder = editorOptions.placeholder || "Example: This plan is wrong because... Next time, prefer...";
  const controls = document.createElement("div");
  controls.className = "inline-memory-editor-actions";
  const autoDraft = document.createElement("button");
  autoDraft.type = "button";
  autoDraft.className = "settings-action-button";
  autoDraft.textContent = "Auto generate";
  autoDraft.hidden = !editorOptions.includeOutcome;
  const save = document.createElement("button");
  save.type = "button";
  save.className = "settings-action-button";
  save.textContent = editorOptions.saveText || "Save memory";
  const cancel = document.createElement("button");
  cancel.type = "button";
  cancel.className = "settings-action-button";
  cancel.textContent = "Cancel";
  const status = document.createElement("span");
  status.className = "inline-memory-status";
  autoDraft.addEventListener("click", () => {
    void draftInlineMemoryFeedback(
      context,
      outcomeSelect?.value || "unclear",
      textarea,
      status,
      autoDraft,
    );
  });
  save.addEventListener("click", () => {
    const nextContext = { ...(context || {}) };
    if (editorOptions.feedbackTarget) {
      nextContext.feedback_target = editorOptions.feedbackTarget;
    }
    if (editorOptions.includeOutcome) {
      nextContext.run_feedback = buildRunFeedbackObject(
        nextContext,
        outcomeSelect?.value || "unclear",
      );
    }
    void commitInlineMemoryFeedback(textarea.value, nextContext, status, editor);
  });
  cancel.addEventListener("click", () => {
    editor.remove();
  });
  controls.append(autoDraft, save, cancel, status);
  label.append(textarea);
  editor.append(label, controls);
  actions.append(editor);
  textarea.focus();
  scrollChatToBottom();
}

function appendRunFeedbackAction(message, context) {
  if (!message || message.querySelector(".run-feedback-actions")) return;
  const actions = document.createElement("div");
  actions.className = "run-feedback-actions";
  appendContinueFromFailureAction(actions, context);
  const button = document.createElement("button");
  button.type = "button";
  button.className = "settings-action-button run-feedback-button";
  button.textContent = "Run feedback";
  button.title = "Tell the agent what went right or wrong so it can update memory.";
  button.addEventListener("click", () => {
    showInlineMemoryEditor(actions, context, {
      includeOutcome: true,
      label: "What should the agent learn from this run?",
      placeholder: "Example: This was the right/wrong decision because... Next time...",
      saveText: "Save feedback",
    });
  });
  actions.append(button);
  if (!isStructuredSchemaFailure(context)) {
    const validationButton = document.createElement("button");
    validationButton.type = "button";
    validationButton.className = "settings-action-button run-feedback-button";
    validationButton.textContent = "Modify Validation";
    validationButton.title = "Tell the agent how this validation should behave next time.";
    validationButton.addEventListener("click", () => {
      showInlineMemoryEditor(actions, context, {
        feedbackTarget: "validation_policy",
        label: "Tell the agent how this validation should behave next time.",
        placeholder: "Example: Allow this syntax only when it appears inside a literal file payload...",
        saveText: "Propose validation policy",
      });
    });
    actions.append(validationButton);
  }
  message.append(actions);
}

function continuationInfoFromTracePayload(payload) {
  for (const event of Array.isArray(payload?.events) ? payload.events : []) {
    const eventType = String(event?.event_type || "");
    if (eventType !== "operator.continuation.available") {
      continue;
    }
    const detail = event?.detail && typeof event.detail === "object" ? event.detail : {};
    if (detail.resumable) {
      return { ...detail };
    }
  }
  const metadata = payload?.metadata && typeof payload.metadata === "object" ? payload.metadata : {};
  const existing = metadata.operator_failure_continuation && typeof metadata.operator_failure_continuation === "object"
    ? metadata.operator_failure_continuation
    : null;
  if (existing?.resumable) {
    return { ...existing };
  }
  const records = Array.isArray(metadata.operator_execution_records)
    ? [...metadata.operator_execution_records]
    : [];
  const streamingState = metadata.operator_streaming_state && typeof metadata.operator_streaming_state === "object"
    ? metadata.operator_streaming_state
    : null;
  if (streamingState) {
    for (const taskResult of Array.isArray(streamingState.prior_results) ? streamingState.prior_results : []) {
      if (!taskResult || typeof taskResult !== "object") {
        continue;
      }
      for (const record of Array.isArray(taskResult.records) ? taskResult.records : []) {
        if (record && typeof record === "object") {
          records.push(record);
        }
      }
    }
  }
  const successful = records
    .filter((record) => String(record?.status || "") === "success" && String(record?.action_id || "").trim())
    .map((record) => String(record.action_id));
  const failed = records.find((record) => String(record?.status || "") === "error");
  if (successful.length && failed) {
    return {
      resumable: true,
      agent_mode: String(metadata.agent_mode || "llm_operator"),
      conversation_id: String(metadata.conversation_id || ""),
      parent_request_id: String(metadata.parent_request_id || ""),
      successful_action_ids: successful,
      failed_action_id: String(failed.action_id || ""),
      failed_action_kind: String(failed.kind || ""),
      failed_exit_code: failed.exit_code,
      failed_error: String(failed.error || failed.stderr || failed.stdout || ""),
      record_count: records.length,
    };
  }
  return null;
}

function appendContinueFromFailureAction(actions, context) {
  const requestId = String(context?.request_id || "").trim();
  const continuation = context?.operator_continuation && typeof context.operator_continuation === "object"
    ? context.operator_continuation
    : null;
  if (!actions || !requestId || !continuation?.resumable) {
    return;
  }
  const button = document.createElement("button");
  button.type = "button";
  button.className = "settings-action-button run-feedback-button continue-failure-button";
  button.textContent = "Continue from failure";
  const completed = Array.isArray(continuation.successful_action_ids)
    ? continuation.successful_action_ids.length
    : 0;
  const failed = String(continuation.failed_action_id || "failed action");
  button.title = `${completed} action(s) completed. Continue from ${failed} after live state reconciliation.`;
  button.addEventListener("click", () => {
    void handleContinueFromFailure(requestId, button);
  });
  actions.append(button);
}

async function handleContinueFromFailure(requestId, button, notes = "") {
  if (!requestId || state.continuationHandled.has(requestId)) {
    return;
  }
  state.continuationHandled.add(requestId);
  if (button) {
    button.disabled = true;
  }
  setRunStatus("continuing", "running");
  addThinkingIndicator();
  await refreshAgentSettingsBeforeRequest();
  const payload = { context: agentSettingsContext() };
  const correctionNotes = String(
    notes || state.stepCorrectionRetryNotesByRequest.get(requestId) || "",
  ).trim();
  if (correctionNotes) {
    payload.notes = correctionNotes;
  }
  const requestScopedAutoApprove = state.requestAutoApproveIds.has(requestId);
  if (requestScopedAutoApprove) {
    payload.context = {
      ...payload.context,
      auto_approve_commands: true,
      auto_approve_scope: "request",
    };
  }
  const terminalExecution = terminalExecutionEnabled();
  if (terminalExecution) {
    await waitForTerminalRequestContext();
  }
  await syncTerminalCwd();
  const terminalContext = terminalRequestContext();
  if (terminalExecution && !Object.keys(terminalContext).length) {
    state.continuationHandled.delete(requestId);
    if (button) button.disabled = false;
    removeThinkingIndicator();
    setRunStatus("failed", "failed");
    addMessage("assistant", "Failure", "Run in Terminal needs an active terminal session with a known cwd.");
    return;
  }
  if (terminalExecution) {
    terminalContext.execute_in_terminal = true;
  }
  if (Object.keys(terminalContext).length) {
    payload.context = {
      ...payload.context,
      ...terminalContext,
    };
  }
  const response = await fetch(`/api/agent/continue/${requestId}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!response.ok) {
    state.continuationHandled.delete(requestId);
    if (button) button.disabled = false;
    removeThinkingIndicator();
    setRunStatus("failed", "failed");
    addMessage("assistant", "Continuation error", await response.text());
    return;
  }
  const responsePayload = await response.json();
  if (responsePayload.conversation_id) {
    state.conversationId = responsePayload.conversation_id;
  }
  applyContextWindowTokens(responsePayload.llm_context_window_tokens);
  setComposerPreparing(true);
  if (requestScopedAutoApprove && responsePayload.request_id) {
    state.requestAutoApproveIds.add(responsePayload.request_id);
  }
  if (responsePayload.request_id) {
    rememberLearningRequestLink(responsePayload.request_id, requestId);
  }
  startTraceStream(responsePayload.request_id, responsePayload.stream_url);
}

async function optimizeMemory() {
  try {
    const response = await fetchWithLlmActivity("/api/agent/memory/optimize", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: String(memorySearch?.value || "") }),
    });
    if (!response.ok) {
      throw new Error(await response.text());
    }
    await loadMemory();
  } catch (error) {
    showUiActionError({
      title: "Memory optimize failed",
      message: shortStatusError(error),
      fix: "Adjust the memory search/filter and try optimizing again.",
    });
  }
}

async function applyMemoryProposal(proposalId) {
  if (!proposalId) {
    showUiActionError({
      title: "No proposal selected",
      message: "There is no memory proposal selected to apply.",
      fix: "Select a pending proposal and try applying it again.",
    });
    return;
  }
  try {
    const response = await fetch(
      `/api/agent/memory/proposals/${encodeURIComponent(proposalId)}/apply`,
      { method: "POST" },
    );
    if (!response.ok) {
      throw new Error(await response.text());
    }
    await loadMemory();
  } catch (error) {
    showUiActionError({
      title: "Memory proposal apply failed",
      message: shortStatusError(error),
      fix: "Refresh memory proposals and try applying again.",
    });
  }
}

function drawerWidthBounds() {
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 720;
  return {
    min: Math.min(420, Math.max(320, viewportWidth - 24)),
    max: Math.max(320, viewportWidth - 24),
  };
}

function clampDrawerWidth(width) {
  const bounds = drawerWidthBounds();
  return Math.min(bounds.max, Math.max(bounds.min, Math.round(Number(width) || 720)));
}

function setDrawerWidth(kind, width, persist = true) {
  const safeWidth = clampDrawerWidth(width);
  const drawer = kind === "memory"
    ? memoryDrawer
    : kind === "parameters"
      ? parametersDrawer
    : kind === "gateway"
      ? gatewayDrawer
      : kind === "events"
        ? eventsDrawer
        : kind === "tasks"
          ? tasksDrawer
          : kind === "monitors"
            ? monitorsDrawer
          : settingsDrawer;
  drawer?.style.setProperty("--drawer-width", `${safeWidth}px`);
  if (kind === "memory") {
    state.memoryDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.memoryDrawerWidthPx, safeWidth);
    }
  } else if (kind === "parameters") {
    state.parametersDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.parametersDrawerWidthPx, safeWidth);
    }
  } else if (kind === "gateway") {
    state.gatewayDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.gatewayDrawerWidthPx, safeWidth);
    }
  } else if (kind === "events") {
    state.eventsDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.eventsDrawerWidthPx, safeWidth);
    }
  } else if (kind === "tasks") {
    state.tasksDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.tasksDrawerWidthPx, safeWidth);
    }
  } else if (kind === "monitors") {
    state.monitorsDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.monitorsDrawerWidthPx, safeWidth);
    }
  } else {
    state.settingsDrawerWidthPx = safeWidth;
    if (persist) {
      persistNumber(uiPreferences.settingsDrawerWidthPx, safeWidth);
    }
  }
}

function resizeOpenDrawersToViewport() {
  setDrawerWidth("settings", state.settingsDrawerWidthPx, false);
  setDrawerWidth("memory", state.memoryDrawerWidthPx, false);
  setDrawerWidth("parameters", state.parametersDrawerWidthPx, false);
  setDrawerWidth("gateway", state.gatewayDrawerWidthPx, false);
  setDrawerWidth("events", state.eventsDrawerWidthPx, false);
  setDrawerWidth("tasks", state.tasksDrawerWidthPx, false);
  setDrawerWidth("monitors", state.monitorsDrawerWidthPx, false);
}

function setupDrawerResize(handle, drawer, kind) {
  if (!handle || !drawer) return;
  const startResize = (event) => {
    if (event.button !== undefined && event.button !== 0) {
      return;
    }
    event.preventDefault();
    const startX = event.clientX;
    const startWidth = drawer.getBoundingClientRect().width || (
      kind === "memory"
        ? state.memoryDrawerWidthPx
        : kind === "parameters"
          ? state.parametersDrawerWidthPx
        : kind === "gateway"
          ? state.gatewayDrawerWidthPx
        : kind === "events"
          ? state.eventsDrawerWidthPx
          : kind === "tasks"
            ? state.tasksDrawerWidthPx
            : kind === "monitors"
              ? state.monitorsDrawerWidthPx
            : state.settingsDrawerWidthPx
    );
    drawer.classList.add("resizing");
    document.body.style.cursor = "ew-resize";
    const onMove = (moveEvent) => {
      setDrawerWidth(kind, startWidth + startX - moveEvent.clientX);
    };
    const onUp = () => {
      drawer.classList.remove("resizing");
      document.body.style.cursor = "";
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp, { once: true });
    window.addEventListener("pointercancel", onUp, { once: true });
  };
  handle.addEventListener("pointerdown", startResize);
  handle.addEventListener("keydown", (event) => {
    if (!["ArrowLeft", "ArrowRight", "PageUp", "PageDown", "Home", "End"].includes(event.key)) {
      return;
    }
    event.preventDefault();
    const current = kind === "memory"
      ? state.memoryDrawerWidthPx
      : kind === "parameters"
        ? state.parametersDrawerWidthPx
      : kind === "gateway"
        ? state.gatewayDrawerWidthPx
        : kind === "events"
          ? state.eventsDrawerWidthPx
          : kind === "tasks"
            ? state.tasksDrawerWidthPx
            : kind === "monitors"
              ? state.monitorsDrawerWidthPx
            : state.settingsDrawerWidthPx;
    const step = event.key === "PageUp" || event.key === "PageDown" ? 80 : 24;
    if (event.key === "Home") {
      setDrawerWidth(kind, drawerWidthBounds().min);
    } else if (event.key === "End") {
      setDrawerWidth(kind, drawerWidthBounds().max);
    } else if (event.key === "ArrowLeft" || event.key === "PageUp") {
      setDrawerWidth(kind, current + step);
    } else {
      setDrawerWidth(kind, current - step);
    }
  });
}

const persistentDetailsSelector = [
  "details.settings-collapsible-section",
  "details.memory-section-card",
  "details.gateway-section-card",
  "details.event-section-card",
  "details.monitor-section-card",
  "details.memory-advanced-filters",
  "details.memory-association-panel",
  "details.memory-audit-panel",
].join(", ");

const taskTransientDetailsSelector = [
  "details.task-row",
  "details.task-detail-row",
].join(", ");

const monitorTransientDetailsSelector = [
  "details.monitor-row",
  "details.monitor-detail-row",
].join(", ");

const drawerCollapseControls = [
  { button: settingsCollapseAllButton, drawer: settingsDrawer, label: "settings" },
  { button: memoryCollapseAllButton, drawer: memoryDrawer, label: "memory" },
  { button: parametersCollapseAllButton, drawer: parametersDrawer, label: "parameter" },
  { button: gatewayCollapseAllButton, drawer: gatewayDrawer, label: "gateway" },
  { button: eventsCollapseAllButton, drawer: eventsDrawer, label: "event" },
  { button: tasksCollapseAllButton, drawer: tasksDrawer, label: "task" },
  { button: monitorsCollapseAllButton, drawer: monitorsDrawer, label: "monitor" },
];

function collapsibleDetailsIn(root) {
  if (!root) {
    return [];
  }
  const selector = root === tasksDrawer
    ? `${persistentDetailsSelector}, ${taskTransientDetailsSelector}`
    : root === monitorsDrawer
      ? `${persistentDetailsSelector}, ${monitorTransientDetailsSelector}`
    : persistentDetailsSelector;
  return Array.from(root.querySelectorAll(selector)).filter(
    (details) => details instanceof HTMLDetailsElement,
  );
}

function syncDrawerCollapseButtons() {
  for (const { button, drawer, label } of drawerCollapseControls) {
    if (!button || !drawer) {
      continue;
    }
    const details = collapsibleDetailsIn(drawer);
    const hasOpenSection = details.some((section) => section.open);
    button.disabled = details.length === 0;
    button.textContent = hasOpenSection ? "Collapse all" : "Expand all";
    button.setAttribute(
      "aria-label",
      `${hasOpenSection ? "Collapse" : "Expand"} all ${label} sections`,
    );
  }
}

function setDrawerSectionsCollapsed(drawer, collapsed) {
  if (drawer === tasksDrawer) {
    state.taskDetailsCollapsed = Boolean(collapsed);
    state.taskDetailsExpanded = !collapsed;
  } else if (drawer === monitorsDrawer) {
    state.monitorDetailsCollapsed = Boolean(collapsed);
    state.monitorDetailsExpanded = !collapsed;
  }
  for (const details of collapsibleDetailsIn(drawer)) {
    details.open = !collapsed;
    persistPersistentDetailsState(details);
  }
  syncDrawerCollapseButtons();
}

function wireDrawerCollapseButton(button, drawer) {
  button?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const sections = collapsibleDetailsIn(drawer);
    const shouldCollapse = sections.some((details) => details.open);
    setDrawerSectionsCollapsed(drawer, shouldCollapse);
  });
}

function normalizePersistentDetailsKeyPart(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function persistentDetailsKey(details) {
  if (!details) {
    return "";
  }
  const explicitId = normalizePersistentDetailsKeyPart(details.id);
  if (explicitId) {
    return `id:${explicitId}`;
  }
  const scope = normalizePersistentDetailsKeyPart(
    details.closest("aside[id], section[id], main[id], .pane[id]")?.id || "agent-ui",
  );
  const label = normalizePersistentDetailsKeyPart(
    details.getAttribute("aria-label")
      || details.querySelector("summary h2, summary h3, summary strong, summary")?.textContent
      || Array.from(details.classList).join("-"),
  );
  return `${scope || "agent-ui"}:${label || "details"}`;
}

function persistPersistentDetailsState(details) {
  const key = persistentDetailsKey(details);
  if (!key) {
    return;
  }
  const snapshot = storedJson(uiPreferences.detailsOpen, {});
  snapshot[key] = Boolean(details.open);
  persistJson(uiPreferences.detailsOpen, snapshot);
}

function restorePersistentDetailsState() {
  const snapshot = storedJson(uiPreferences.detailsOpen, {});
  document.querySelectorAll(persistentDetailsSelector).forEach((details) => {
    const key = persistentDetailsKey(details);
    if (!key) {
      return;
    }
    details.dataset.persistentDetailsKey = key;
    if (Object.prototype.hasOwnProperty.call(snapshot, key)) {
      details.open = snapshot[key] === true;
    }
    details.addEventListener("toggle", () => {
      persistPersistentDetailsState(details);
      syncDrawerCollapseButtons();
    });
  });
  syncDrawerCollapseButtons();
}

