    visualizationToggle.classList.toggle("visualization-hidden", visualizationHidden);
    visualizationToggle.setAttribute("aria-expanded", String(!visualizationHidden));
    visualizationToggle.title = visualizationHidden
      ? "Show architecture visualization"
      : "Collapse architecture visualization";
