terminalSplitResizer?.addEventListener("pointerdown", (event) => {
  const terminalExpanded =
    state.terminalVisible && !state.terminalCollapsed && terminalPanel && !terminalPanel.hidden;
  if (!terminalExpanded || state.conversationCollapsed) {
    return;
  }
  event.preventDefault();
  const startY = event.clientY;
  const startHeight = terminalPanel.getBoundingClientRect().height;
  document.body.classList.add("resizing-terminal-split");
  terminalSplitResizer.setPointerCapture?.(event.pointerId);
  const onPointerMove = (moveEvent) => {
    const delta = startY - moveEvent.clientY;
    setTerminalHeightPx(startHeight + delta);
  };
  const onPointerUp = (upEvent) => {
    terminalSplitResizer.releasePointerCapture?.(upEvent.pointerId);
    document.body.classList.remove("resizing-terminal-split");
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
    window.removeEventListener("pointercancel", onPointerUp);
  };
  window.addEventListener("pointermove", onPointerMove);
  window.addEventListener("pointerup", onPointerUp);
  window.addEventListener("pointercancel", onPointerUp);
});
terminalSplitResizer?.addEventListener("keydown", (event) => {
  if (!["ArrowUp", "ArrowDown", "PageUp", "PageDown"].includes(event.key)) {
    return;
  }
  const terminalExpanded =
    state.terminalVisible && !state.terminalCollapsed && terminalPanel && !terminalPanel.hidden;
  if (!terminalExpanded || state.conversationCollapsed) {
    return;
  }
  event.preventDefault();
  const step = event.key === "PageUp" || event.key === "PageDown" ? 48 : 16;
  const direction = event.key === "ArrowUp" || event.key === "PageUp" ? 1 : -1;
  const current =
    state.terminalHeightPx || terminalPanel.getBoundingClientRect().height || terminalHeightBounds().min;
  setTerminalHeightPx(current + step * direction);
});
