settingsSaveButton?.addEventListener("click", async () => {
  settingsSaveButton.disabled = true;
  try {
    saveAgentSettings(readSettingsFromControls(), { persistBackend: false });
    await persistAgentSettingsToBackend(state.agentSettings);
    await saveRuntimeControls({ rethrow: true });
    setSettingsDrawerOpen(false);
  } catch (error) {
    showUiActionError({
      title: "Settings apply failed",
      message: shortStatusError(error),
      fix: "Review the settings and try applying again.",
    });
  } finally {
    settingsSaveButton.disabled = false;
  }
});
