setTraceVisible(state.traceVisible, { syncSettings: false });
setTraceCollapsed(state.traceCollapsed);
syncTraceEventsCollapsed();
setVisualizationVisible(state.visualizationVisible, { syncSettings: false });
setVisualizationCollapsed(state.visualizationCollapsed);
setVisualizationLive(state.visualizationLive);
setVisualizationDirection(state.visualizationDirection);
setVisualizationZoom(state.visualizationZoom, { persist: false });
setVisualizationInverted(state.visualizationInverted);
setVisualizationDetailsCollapsed(state.visualizationDetailsCollapsed);
setChatBubbleLayout(state.chatBubbleLayout, { syncSettings: false });
setImmersiveMode(state.immersiveMode, { persist: false });
installResponsiveImmersiveObserver();
syncResponsiveImmersiveMode();
setConversationCollapsed(state.conversationCollapsed);
setLlmStreamCollapsed(state.llmStreamCollapsed);
setProgressCollapsed(state.progressCollapsed);
renderLlmServiceStatus();
renderLlmActivityIndicator();
renderLearningRuntimeIndicator();
setEventsDrawerOpen(state.eventsDrawerOpen);
setTasksDrawerOpen(state.tasksDrawerOpen);
setMonitorsDrawerOpen(state.monitorsDrawerOpen);
setNotificationsDrawerOpen(state.notificationsDrawerOpen);
applyStoredTerminalHeight();
installMobileZoomGuards();
installMobileKeyboardGuards();
void gatewayStartup.finally(() => {
  const openTerminalFromUrl = terminalOpenRequestedFromUrl();
  const nextTerminalVisible = state.terminalVisible || openTerminalFromUrl;
  const visibilityUpdate = setTerminalVisible(nextTerminalVisible, {
    syncSettings: openTerminalFromUrl,
  });
  if (openTerminalFromUrl && !state.agentUiClientMode) {
    saveAgentSettings({ ...readSettingsFromControls(), ui_terminal_visible: true });
  }
  void visibilityUpdate
    .then(() => {
      if (openTerminalFromUrl) {
        setTerminalCollapsed(false);
        state.terminal?.focus?.();
      }
    });
});
void eventsStartup;
void tasksStartup;
void monitorsStartup;
void notificationsStartup;
initPipeline();
resetVisualizationState();
